import type { BankQuestion } from "@/lib/bank";

/** Soils, Agriculture and Irrigation (Geography): 214 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"geo-soils-agriculture-1","question":"“Regur” is another name for which soil?","options":["Black soil","Red soil","Laterite soil","Alluvial soil"],"answer":0,"explanation":"Black soil of the Deccan is called regur (and black cotton soil); it forms from the weathering of basalt.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"“रेगुर” किस मृदा का दूसरा नाम है?","optionsHi":["काली मृदा","लाल मृदा","लेटराइट मृदा","जलोढ़ मृदा"],"explanationHi":"दक्कन की काली मृदा को रेगुर (और काली कपास मृदा) कहा जाता है; यह बेसाल्ट के अपक्षय से बनती है।"},
  {"id":"geo-soils-agriculture-2","question":"Which of these is a kharif crop?","options":["Wheat","Mustard","Rice","Gram"],"answer":2,"explanation":"Kharif crops are sown with the onset of the monsoon (June–July); rice is the main one. Wheat, mustard and gram are rabi crops.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"इनमें से कौन-सी खरीफ फसल है?","optionsHi":["गेहूँ","सरसों","चावल","चना"],"explanationHi":"खरीफ फसलें मानसून के आगमन (जून–जुलाई) के साथ बोई जाती हैं; चावल इनमें प्रमुख है। गेहूँ, सरसों और चना रबी फसलें हैं।"},
  {"id":"geo-soils-agriculture-3","question":"The Green Revolution of the late 1960s brought the biggest early gains in the production of:","options":["Oilseeds","Pulses","Wheat","Jute"],"answer":2,"explanation":"High-yielding dwarf wheat varieties, with irrigation and fertilisers, raised wheat output sharply in Punjab, Haryana and western UP; pulses lagged behind.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"1960 के दशक के अंत की हरित क्रांति से सबसे अधिक प्रारंभिक लाभ किसके उत्पादन में हुआ?","optionsHi":["तिलहन","दलहन","गेहूँ","जूट"],"explanationHi":"सिंचाई और उर्वरकों के साथ उच्च उपज वाली बौनी गेहूँ किस्मों ने पंजाब, हरियाणा और पश्चिमी उत्तर प्रदेश में गेहूँ का उत्पादन तेज़ी से बढ़ाया; दलहन पीछे रह गए।"},
  {"id":"geo-soils-agriculture-4","question":"Who is widely regarded as the father of the Green Revolution in India?","options":["Vikram Sarabhai","M. S. Swaminathan","Verghese Kurien","Norman E. Borlaug"],"answer":1,"explanation":"M. S. Swaminathan led the spread of high-yielding wheat and rice varieties in India and is called the father of its Green Revolution. Norman Borlaug bred the Mexican dwarf wheats and is the father of the global Green Revolution, the usual trap; Kurien led the White Revolution.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"भारत में हरित क्रांति का जनक व्यापक रूप से किसे माना जाता है?","optionsHi":["विक्रम साराभाई","एम. एस. स्वामीनाथन","वर्गीज़ कुरियन","नॉर्मन ई. बोरलॉग"],"explanationHi":"एम. एस. स्वामीनाथन ने भारत में उच्च उपज वाली गेहूँ और चावल की किस्मों का प्रसार कराया और उन्हें भारत की हरित क्रांति का जनक कहा जाता है। नॉर्मन बोरलॉग ने मेक्सिको की बौनी गेहूँ किस्में विकसित कीं और वे वैश्विक हरित क्रांति के जनक हैं, जो प्रायः भ्रम का कारण बनता है; कुरियन ने श्वेत क्रांति का नेतृत्व किया।"},
  {"id":"geo-soils-agriculture-5","question":"Watermelon, muskmelon and cucumber grown between the rabi and kharif seasons (roughly March–June) are called:","options":["Kharif crops","Plantation crops","Zaid crops","Rabi crops"],"answer":2,"explanation":"The short summer season between rabi and kharif is the zaid season; melons, cucumber and fodder crops are typical.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"रबी और खरीफ मौसमों के बीच (लगभग मार्च–जून) उगाए जाने वाले तरबूज, खरबूज और खीरे को क्या कहा जाता है?","optionsHi":["खरीफ फसलें","रोपण फसलें","जायद फसलें","रबी फसलें"],"explanationHi":"रबी और खरीफ के बीच का छोटा ग्रीष्म मौसम जायद मौसम कहलाता है; तरबूज-खरबूज, खीरा और चारा फसलें इसकी विशिष्ट फसलें हैं।"},
  {"id":"geo-soils-agriculture-6","question":"Cashew nut grows best on which soil?","options":["Alluvial soil","Red laterite soil","Black cotton soil","Saline soil"],"answer":1,"explanation":"Red laterite soils of Tamil Nadu, Andhra Pradesh and Kerala, well drained and on slopes, suit cashew; with manuring they also support tea and coffee.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"काजू किस मृदा में सबसे अच्छा उगता है?","optionsHi":["जलोढ़ मृदा","लाल लेटराइट मृदा","काली कपास मृदा","लवणीय मृदा"],"explanationHi":"तमिलनाडु, आंध्र प्रदेश और केरल की लाल लेटराइट मृदाएँ, जो अच्छी जल-निकासी वाली और ढालों पर होती हैं, काजू के लिए उपयुक्त हैं; खाद डालने पर इनमें चाय और कॉफी भी उगाई जा सकती है।"},
  {"id":"geo-soils-agriculture-7","question":"Which soil develops deep, wide cracks in the dry season and is described as “self-ploughing”?","options":["Black soil","Red soil","Laterite soil","Mountain soil"],"answer":0,"explanation":"Black soil is rich in clay that swells when wet and shrinks when dry, opening cracks that let air in; this is why it is called self-ploughing.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"कौन-सी मृदा शुष्क मौसम में गहरी, चौड़ी दरारें विकसित करती है और “स्वतः जुताई वाली” कही जाती है?","optionsHi":["काली मृदा","लाल मृदा","लेटराइट मृदा","पर्वतीय मृदा"],"explanationHi":"काली मृदा में चिकनी मिट्टी (क्ले) अधिक होती है, जो गीली होने पर फूलती और सूखने पर सिकुड़ती है, जिससे दरारें खुलती हैं और हवा अंदर जाती है; इसीलिए इसे स्वतः जुताई वाली कहा जाता है।"},
  {"id":"geo-soils-agriculture-8","question":"Rabi crops are generally sown in ___ and harvested in ___.","options":["October–December; April–June","March–April; June","July–August; December","June–July; September–October"],"answer":0,"explanation":"Rabi crops are sown in winter (October–December) and harvested in summer (April–June); kharif crops are sown with the monsoon and harvested in September–October.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"रबी फसलें सामान्यतः ___ में बोई जाती हैं और ___ में काटी जाती हैं।","optionsHi":["अक्टूबर–दिसंबर; अप्रैल–जून","मार्च–अप्रैल; जून","जुलाई–अगस्त; दिसंबर","जून–जुलाई; सितंबर–अक्टूबर"],"explanationHi":"रबी फसलें सर्दियों (अक्टूबर–दिसंबर) में बोई जाती हैं और गर्मियों (अप्रैल–जून) में काटी जाती हैं; खरीफ फसलें मानसून के साथ बोई जाती हैं और सितंबर–अक्टूबर में काटी जाती हैं।"},
  {"id":"geo-soils-agriculture-9","question":"“Jhum”, a form of slash-and-burn shifting cultivation, is practised mainly in:","options":["The canal-fed Punjab plains","The salt flats of the Rann","The islands of the Ganga delta","The north-eastern hill states"],"answer":3,"explanation":"Jhum is practised in the hills of Assam, Meghalaya, Mizoram, Nagaland and other north-eastern states; forest is cleared, burnt, cropped for a few years and then left to recover.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"“झूम”, जो स्थानांतरित कृषि (काटो और जलाओ) का एक रूप है, मुख्यतः कहाँ की जाती है?","optionsHi":["नहर-सिंचित पंजाब के मैदानों में","कच्छ के रण के लवणीय क्षेत्रों में","गंगा डेल्टा के द्वीपों में","उत्तर-पूर्वी पहाड़ी राज्यों में"],"explanationHi":"झूम कृषि असम, मेघालय, मिज़ोरम, नगालैंड और अन्य उत्तर-पूर्वी राज्यों की पहाड़ियों में की जाती है; वन को काटकर जलाया जाता है, कुछ वर्ष फसल उगाई जाती है और फिर भूमि को पुनः उपजाऊ होने के लिए छोड़ दिया जाता है।"},
  {"id":"geo-soils-agriculture-10","question":"Which of these conditions is NOT suitable for a tea plantation?","options":["Water standing around the roots","Deep, fertile soil rich in humus","Warm, moist, frost-free climate","Well-drained hill slopes"],"answer":0,"explanation":"Tea needs heavy, well-distributed rain but water must drain away; waterlogging damages the roots, which is why tea is grown on slopes.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"इनमें से कौन-सी स्थिति चाय बागान के लिए उपयुक्त नहीं है?","optionsHi":["जड़ों के चारों ओर पानी खड़ा रहना","ह्यूमस से भरपूर गहरी, उपजाऊ मृदा","गर्म, आर्द्र, पाला-रहित जलवायु","अच्छी जल-निकासी वाले पहाड़ी ढाल"],"explanationHi":"चाय को भारी और अच्छी तरह वितरित वर्षा चाहिए, पर पानी बह जाना चाहिए; जलभराव से जड़ें नष्ट होती हैं, इसीलिए चाय ढालों पर उगाई जाती है।"},
  {"id":"geo-soils-agriculture-11","question":"Terrace farming is practised on hill slopes mainly to:","options":["Drain water quickly downhill","Check soil erosion and run-off","Increase the salinity of the soil","Allow shifting cultivation"],"answer":1,"explanation":"Cutting steps (terraces) on slopes slows running water, holds soil and moisture, and creates flat land for cultivation.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"पहाड़ी ढालों पर सीढ़ीदार खेती मुख्यतः किसलिए की जाती है?","optionsHi":["पानी को तेज़ी से नीचे बहाने के लिए","मृदा अपरदन और अपवाह को रोकने के लिए","मृदा की लवणता बढ़ाने के लिए","स्थानांतरित कृषि की अनुमति देने के लिए"],"explanationHi":"ढालों पर सीढ़ियाँ (सोपान) काटने से बहता पानी धीमा होता है, मृदा और नमी रुकी रहती है, और खेती के लिए समतल भूमि बन जाती है।"},
  {"id":"geo-soils-agriculture-12","question":"For orchards in water-scarce, arid areas, the most water-efficient method of irrigation is:","options":["Basin irrigation","Drip irrigation","Furrow irrigation","Flood irrigation"],"answer":1,"explanation":"Drip irrigation delivers water drop by drop to the root zone, cutting evaporation and run-off losses; flood irrigation wastes the most water.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"जल-अभाव वाले शुष्क क्षेत्रों में बागानों के लिए सिंचाई की सबसे जल-कुशल विधि कौन-सी है?","optionsHi":["थाला सिंचाई","ड्रिप (बूँद-बूँद) सिंचाई","कूँड़ सिंचाई","बाढ़ सिंचाई"],"explanationHi":"ड्रिप सिंचाई में पानी बूँद-बूँद करके जड़ क्षेत्र तक पहुँचाया जाता है, जिससे वाष्पीकरण और अपवाह से होने वाली हानि घटती है; बाढ़ सिंचाई में सबसे अधिक पानी बर्बाद होता है।"},
  {"id":"geo-soils-agriculture-13","question":"Which state is the largest producer of coffee in India?","options":["Assam","Tamil Nadu","Kerala","Karnataka"],"answer":3,"explanation":"Karnataka (Kodagu, Chikkamagaluru, Hassan) produces about 70% of India's coffee; Kerala and Tamil Nadu follow. Assam is a tea state.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"भारत में कॉफी का सबसे बड़ा उत्पादक राज्य कौन-सा है?","optionsHi":["असम","तमिलनाडु","केरल","कर्नाटक"],"explanationHi":"कर्नाटक (कोडागु, चिकमगलूर, हासन) भारत की लगभग 70% कॉफी उत्पादित करता है; केरल और तमिलनाडु उसके बाद आते हैं। असम चाय का राज्य है।"},
  {"id":"geo-soils-agriculture-14","question":"Black soil is generally poor in:","options":["Calcium carbonate","Magnesium","Potash","Phosphorus"],"answer":3,"explanation":"Black soil is rich in calcium carbonate, magnesium, potash and lime but generally poor in phosphoric content, nitrogen and organic matter. Its dark colour suggests it is rich in everything, which is the trap.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"काली मृदा में सामान्यतः किसकी कमी होती है?","optionsHi":["कैल्शियम कार्बोनेट","मैग्नीशियम","पोटाश","फॉस्फोरस"],"explanationHi":"काली मृदा कैल्शियम कार्बोनेट, मैग्नीशियम, पोटाश और चूने से समृद्ध होती है, परंतु इसमें सामान्यतः फॉस्फोरस, नाइट्रोजन और जैव पदार्थ की कमी होती है। इसका गहरा रंग देखकर लगता है कि यह हर पोषक तत्व में समृद्ध है, यही भ्रम है।"},
  {"id":"geo-soils-agriculture-15","question":"Farmers are advised to add gypsum to which kind of soil?","options":["Peaty, waterlogged soil","Acidic forest soil","Saline and alkaline soil","Leached laterite soil"],"answer":2,"explanation":"Saline/alkaline soils (reh, kallar, usar), common where over-irrigation has raised salts, are reclaimed by adding gypsum, which replaces sodium in the soil.","difficulty":"hard","source":"UPSC Prelims","questionHi":"किसानों को किस प्रकार की मृदा में जिप्सम मिलाने की सलाह दी जाती है?","optionsHi":["पीट युक्त, जलमग्न मृदा","अम्लीय वन मृदा","लवणीय और क्षारीय मृदा","निक्षालित लेटराइट मृदा"],"explanationHi":"लवणीय/क्षारीय मृदाओं (रेह, कल्लर, ऊसर), जो अत्यधिक सिंचाई से लवण बढ़ने पर प्रायः बनती हैं, का सुधार जिप्सम मिलाकर किया जाता है, जो मृदा में सोडियम का स्थान ले लेता है।"},
  {"id":"geo-soils-agriculture-16","question":"Rice is a major crop in Punjab and Haryana although these states get relatively low rainfall, mainly because of:","options":["Black soil that stores water","Flooding by the Brahmaputra","Assured canal and tube-well irrigation","Heavy winter rain from western disturbances"],"answer":2,"explanation":"Rice needs plenty of water; in Punjab and Haryana it is grown with canal and tube-well irrigation, which has also caused falling water tables.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"पंजाब और हरियाणा में अपेक्षाकृत कम वर्षा होने पर भी चावल एक प्रमुख फसल है, इसका मुख्य कारण है:","optionsHi":["पानी संग्रहित करने वाली काली मृदा","ब्रह्मपुत्र की बाढ़","नहरों और नलकूपों से सुनिश्चित सिंचाई","पश्चिमी विक्षोभ से होने वाली भारी शीतकालीन वर्षा"],"explanationHi":"चावल को बहुत पानी चाहिए; पंजाब और हरियाणा में यह नहरों और नलकूपों की सिंचाई से उगाया जाता है, जिससे भूजल स्तर भी गिरता जा रहा है।"},
  {"id":"geo-soils-agriculture-17","question":"Which crop needs a hot, humid climate with rainfall above 200 cm and temperatures above 25 °C?","options":["Bajra","Cotton","Rubber","Wheat"],"answer":2,"explanation":"Rubber is an equatorial crop needing heavy rain and high temperature, grown mainly in Kerala; cotton and bajra need far less rain.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"किस फसल को गर्म, आर्द्र जलवायु, 200 सेमी से अधिक वर्षा और 25 °C से अधिक तापमान चाहिए?","optionsHi":["बाजरा","कपास","रबर","गेहूँ"],"explanationHi":"रबर एक विषुवतीय फसल है जिसे भारी वर्षा और उच्च तापमान चाहिए; यह मुख्यतः केरल में उगाई जाती है। कपास और बाजरे को बहुत कम वर्षा चाहिए।"},
  {"id":"geo-soils-agriculture-18","question":"The Bhoodan movement, in which landowners donated land to the landless, was started by Vinoba Bhave in 1951 at:","options":["Bardoli","Paunar (Wardha)","Pochampalli","Champaran"],"answer":2,"explanation":"Vinoba Bhave began Bhoodan at Pochampalli in present-day Telangana in April 1951. Paunar near Wardha was his own ashram, which makes it the tempting trap; Champaran and Bardoli are linked with earlier Gandhian satyagrahas.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"भूदान आंदोलन, जिसमें भूस्वामियों ने भूमिहीनों को भूमि दान की, विनोबा भावे ने 1951 में कहाँ से शुरू किया?","optionsHi":["बारडोली","पवनार (वर्धा)","पोचमपल्ली","चंपारण"],"explanationHi":"विनोबा भावे ने भूदान की शुरुआत अप्रैल 1951 में वर्तमान तेलंगाना के पोचमपल्ली से की। वर्धा के पास पवनार उनका अपना आश्रम था, इसीलिए वह भ्रमित करने वाला विकल्प है; चंपारण और बारडोली पहले के गांधीवादी सत्याग्रहों से जुड़े हैं।"},
  {"id":"geo-soils-agriculture-19","question":"Which source provides the largest share of the net irrigated area in India?","options":["Wells and tube-wells","Lift from rivers","Canals from dams and barrages","Tanks and ponds"],"answer":0,"explanation":"Wells and tube-wells (groundwater) irrigate more than 60% of India's net irrigated area; canals come a distant second, and tanks matter mainly in the south.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भारत के शुद्ध सिंचित क्षेत्र का सबसे बड़ा हिस्सा किस स्रोत से मिलता है?","optionsHi":["कुएँ और नलकूप","नदियों से लिफ्ट","बाँधों और बैराजों से निकली नहरें","तालाब और पोखर"],"explanationHi":"कुएँ और नलकूप (भूजल) भारत के शुद्ध सिंचित क्षेत्र के 60% से अधिक भाग की सिंचाई करते हैं; नहरें बहुत पीछे दूसरे स्थान पर हैं, और तालाब मुख्यतः दक्षिण में महत्वपूर्ण हैं।"},
  {"id":"geo-soils-agriculture-20","question":"Tank irrigation is common in peninsular India mainly because:","options":["The region has deep, porous alluvial aquifers","Hard rock limits groundwater and uneven land eases bunding","Rainfall is spread evenly through all the months of the year","The rivers are snow-fed and keep flowing throughout the year"],"answer":1,"explanation":"On the hard crystalline rocks of the peninsula, water does not soak in easily, rivers are seasonal and the undulating terrain allows bunds to store run-off, so tanks are widely used.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"प्रायद्वीपीय भारत में तालाब सिंचाई मुख्यतः इसलिए प्रचलित है क्योंकि:","optionsHi":["इस क्षेत्र में गहरे, रंध्रयुक्त जलोढ़ जलभृत हैं","कठोर चट्टानें भूजल को सीमित करती हैं और असमतल भूमि में बाँध बनाना आसान होता है","वर्षा वर्ष के सभी महीनों में समान रूप से होती है","नदियाँ हिम-पोषित हैं और पूरे वर्ष बहती रहती हैं"],"explanationHi":"प्रायद्वीप की कठोर क्रिस्टलीय चट्टानों में पानी आसानी से नहीं रिसता, नदियाँ मौसमी हैं और ऊबड़-खाबड़ भूभाग में बाँध बनाकर अपवाह का जल रोका जा सकता है, इसीलिए तालाबों का व्यापक उपयोग होता है।"},
  {"id":"geo-soils-agriculture-21","question":"The Indira Gandhi Canal, which irrigates north-western Rajasthan, draws its water from:","options":["The Harike barrage on the Sutlej–Beas","The Tehri dam on the Bhagirathi","The Gandhi Sagar dam on the Chambal","The Bhakra dam on the Sutlej in Himachal"],"answer":0,"explanation":"The canal starts at the Harike barrage in Punjab, where the Beas joins the Sutlej, and runs into the Thar desert of Rajasthan.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"इंदिरा गांधी नहर, जो उत्तर-पश्चिमी राजस्थान की सिंचाई करती है, अपना जल कहाँ से लेती है?","optionsHi":["सतलुज–ब्यास पर हरिके बैराज से","भागीरथी पर टिहरी बाँध से","चंबल पर गांधी सागर बाँध से","हिमाचल में सतलुज पर भाखड़ा बाँध से"],"explanationHi":"यह नहर पंजाब में हरिके बैराज से शुरू होती है, जहाँ ब्यास सतलुज से मिलती है, और राजस्थान के थार मरुस्थल तक जाती है।"},
  {"id":"geo-soils-agriculture-22","question":"Saffron cultivation in India is confined mainly to:","options":["Kashmir","Gujarat","Kerala","Assam"],"answer":0,"explanation":"Saffron is grown mainly on the karewa (lake-deposit) plateaus of Kashmir, especially around Pampore.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"भारत में केसर की खेती मुख्यतः कहाँ तक सीमित है?","optionsHi":["कश्मीर","गुजरात","केरल","असम"],"explanationHi":"केसर मुख्यतः कश्मीर के करेवा (झील-निक्षेप) पठारों पर, विशेषकर पंपोर के आसपास, उगाया जाता है।"},
  {"id":"geo-soils-agriculture-23","question":"According to NCERT, cotton needs about how many frost-free days to grow well?","options":["120","365","210","90"],"answer":2,"explanation":"Cotton needs high temperature, light rainfall or irrigation, bright sunshine and about 210 frost-free days; it grows well on black cotton soil.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"NCERT के अनुसार, कपास को भली-भाँति उगने के लिए लगभग कितने पाला-रहित दिन चाहिए?","optionsHi":["120","365","210","90"],"explanationHi":"कपास को उच्च तापमान, हल्की वर्षा या सिंचाई, तेज़ धूप और लगभग 210 पाला-रहित दिन चाहिए; यह काली कपास मृदा में अच्छी उगती है।"},
  {"id":"geo-soils-agriculture-24","question":"Rajasthan is the largest producer of which millet?","options":["Ragi","Maize","Bajra","Jowar"],"answer":2,"explanation":"Bajra (pearl millet) grows on sandy and shallow black soils and suits dry Rajasthan; Karnataka leads in ragi and Maharashtra in jowar.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"राजस्थान किस मोटे अनाज (millet) का सबसे बड़ा उत्पादक है?","optionsHi":["रागी","मक्का","बाजरा","ज्वार"],"explanationHi":"बाजरा (पर्ल मिलेट) रेतीली और उथली काली मृदाओं में उगता है और शुष्क राजस्थान के अनुकूल है; रागी में कर्नाटक और ज्वार में महाराष्ट्र अग्रणी है।"},
  {"id":"geo-soils-agriculture-25","question":"Match the “revolution” with the sector. A. Yellow Revolution  B. Blue Revolution  C. White Revolution  D. Silver Revolution; 1. Milk  2. Oilseeds  3. Eggs and poultry  4. Fisheries","options":["A-3, B-4, C-1, D-2","A-2, B-3, C-1, D-4","A-2, B-4, C-1, D-3","A-2, B-4, C-3, D-1"],"answer":2,"explanation":"Yellow = oilseeds, Blue = fisheries, White = milk (Operation Flood), Silver = eggs and poultry.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"“क्रांति” का क्षेत्र से मिलान कीजिए। A. पीली क्रांति  B. नीली क्रांति  C. श्वेत क्रांति  D. रजत क्रांति; 1. दूध  2. तिलहन  3. अंडे और मुर्गीपालन  4. मत्स्य पालन","optionsHi":["A-3, B-4, C-1, D-2","A-2, B-3, C-1, D-4","A-2, B-4, C-1, D-3","A-2, B-4, C-3, D-1"],"explanationHi":"पीली = तिलहन, नीली = मत्स्य पालन, श्वेत = दूध (ऑपरेशन फ्लड), रजत = अंडे और मुर्गीपालन।"},
  {"id":"geo-soils-agriculture-26","question":"Match the crop with the state that leads its production. A. Coffee  B. Tea  C. Jute  D. Natural rubber; 1. Kerala  2. West Bengal  3. Karnataka  4. Assam","options":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-1, B-4, C-2, D-3","A-2, B-4, C-3, D-1"],"answer":1,"explanation":"Karnataka leads in coffee, Assam in tea, West Bengal in jute and Kerala in natural rubber.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"फसल का मिलान उस राज्य से कीजिए जो उसके उत्पादन में अग्रणी है। A. कॉफी  B. चाय  C. जूट  D. प्राकृतिक रबर; 1. केरल  2. पश्चिम बंगाल  3. कर्नाटक  4. असम","optionsHi":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-1, B-4, C-2, D-3","A-2, B-4, C-3, D-1"],"explanationHi":"कॉफी में कर्नाटक, चाय में असम, जूट में पश्चिम बंगाल और प्राकृतिक रबर में केरल अग्रणी है।"},
  {"id":"geo-soils-agriculture-27","question":"How many of the following statements about Indian soils are correct? I. Laterite soils are poor in nitrogen and rich in iron oxide. II. Black soil has formed from the weathering of the Deccan basalt. III. Red soil develops on crystalline igneous rocks in low-rainfall parts of the eastern and southern Deccan. IV. Desert soils are rich in humus.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: desert soils are sandy and low in humus because there is little vegetation and evaporation is high.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भारतीय मृदाओं के बारे में निम्नलिखित में से कितने कथन सही हैं? I. लेटराइट मृदाएँ नाइट्रोजन में निर्धन और आयरन ऑक्साइड में समृद्ध होती हैं। II. काली मृदा दक्कन के बेसाल्ट के अपक्षय से बनी है। III. लाल मृदा पूर्वी और दक्षिणी दक्कन के कम वर्षा वाले भागों में क्रिस्टलीय आग्नेय चट्टानों पर विकसित होती है। IV. मरुस्थलीय मृदाएँ ह्यूमस में समृद्ध होती हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। IV गलत है: मरुस्थलीय मृदाएँ रेतीली होती हैं और उनमें ह्यूमस कम होता है, क्योंकि वहाँ वनस्पति कम और वाष्पीकरण अधिक होता है।"},
  {"id":"geo-soils-agriculture-28","question":"Arrange in chronological order: 1. Launch of Operation Flood  2. National Food Security Act  3. Introduction of high-yielding varieties (start of the Green Revolution)  4. Launch of PM-KISAN","options":["2-1-3-4","2-3-1-4","3-2-1-4","3-1-2-4"],"answer":3,"explanation":"HYV seeds were introduced in 1965–66, Operation Flood began in 1970, the National Food Security Act was passed in 2013 and PM-KISAN started in 2019.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"कालक्रमानुसार व्यवस्थित कीजिए: 1. ऑपरेशन फ्लड का शुभारंभ  2. राष्ट्रीय खाद्य सुरक्षा अधिनियम  3. उच्च उपज वाली किस्मों का प्रारंभ (हरित क्रांति की शुरुआत)  4. पीएम-किसान का शुभारंभ","optionsHi":["2-1-3-4","2-3-1-4","3-2-1-4","3-1-2-4"],"explanationHi":"HYV बीज 1965–66 में लाए गए, ऑपरेशन फ्लड 1970 में शुरू हुआ, राष्ट्रीय खाद्य सुरक्षा अधिनियम 2013 में पारित हुआ और पीएम-किसान 2019 में शुरू हुआ।"},
  {"id":"geo-soils-agriculture-29","question":"How many of the following statements about Minimum Support Price (MSP) are correct? I. MSP is announced for both kharif and rabi crops. II. The Commission for Agricultural Costs and Prices is a statutory body. III. For sugarcane, MSP has been replaced by the Fair and Remunerative Price (FRP). IV. MSP is legally guaranteed by an Act of Parliament.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. The CACP is an attached office of the Agriculture Ministry, not a statutory body (II wrong), and MSP has no statutory guarantee (IV wrong).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"न्यूनतम समर्थन मूल्य (MSP) के बारे में निम्नलिखित में से कितने कथन सही हैं? I. MSP खरीफ और रबी दोनों फसलों के लिए घोषित किया जाता है। II. कृषि लागत और मूल्य आयोग एक सांविधिक निकाय है। III. गन्ने के लिए MSP का स्थान उचित और लाभकारी मूल्य (FRP) ने ले लिया है। IV. MSP को संसद के अधिनियम द्वारा कानूनी गारंटी प्राप्त है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और III सही हैं। CACP कृषि मंत्रालय का संलग्न कार्यालय है, सांविधिक निकाय नहीं (II गलत), और MSP की कोई वैधानिक गारंटी नहीं है (IV गलत)।"},
  {"id":"geo-soils-agriculture-30","question":"Which group contains only kharif crops?","options":["Rice, barley, groundnut, tur","Rice, cotton, jute, soybean","Maize, mustard, cotton, jute","Soybean, peas, bajra, jute"],"answer":1,"explanation":"Mustard, barley and peas are rabi crops, which rules out the other three groups; rice, cotton, jute and soybean are all sown with the monsoon.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"किस समूह में केवल खरीफ फसलें हैं?","optionsHi":["चावल, जौ, मूँगफली, अरहर","चावल, कपास, जूट, सोयाबीन","मक्का, सरसों, कपास, जूट","सोयाबीन, मटर, बाजरा, जूट"],"explanationHi":"सरसों, जौ और मटर रबी फसलें हैं, जिससे अन्य तीन समूह बाहर हो जाते हैं; चावल, कपास, जूट और सोयाबीन सभी मानसून के साथ बोई जाती हैं।"},
  {"id":"geo-soils-agriculture-31","question":"Which of these is NOT a coffee-growing region?","options":["Chikkamagaluru","Wayanad","Dooars","Kodagu"],"answer":2,"explanation":"Chikkamagaluru and Kodagu (Karnataka) and Wayanad (Kerala) are coffee areas; the Dooars at the foot of the Himalaya in West Bengal and Assam are known for tea.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"इनमें से कौन-सा कॉफी उत्पादक क्षेत्र नहीं है?","optionsHi":["चिकमगलूर","वायनाड","दुआर","कोडागु"],"explanationHi":"चिकमगलूर और कोडागु (कर्नाटक) तथा वायनाड (केरल) कॉफी क्षेत्र हैं; पश्चिम बंगाल और असम में हिमालय की तलहटी में स्थित दुआर चाय के लिए जाने जाते हैं।"},
  {"id":"geo-soils-agriculture-32","question":"Assertion (A): Black soil can support crops like cotton with little irrigation. Reason (R): Black soil has a high clay content and holds moisture for a long time.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Because of its fine clay, black soil retains moisture for long periods, which lets cotton grow in the dry Deccan with limited irrigation.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): काली मृदा कपास जैसी फसलों को कम सिंचाई में सहारा दे सकती है। कारण (R): काली मृदा में चिकनी मिट्टी की मात्रा अधिक होती है और वह नमी को लंबे समय तक रोके रखती है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"महीन चिकनी मिट्टी के कारण काली मृदा लंबे समय तक नमी बनाए रखती है, जिससे शुष्क दक्कन में सीमित सिंचाई के साथ भी कपास उग पाती है।"},
  {"id":"geo-soils-agriculture-33","question":"Match the dam with its river. A. Nagarjuna Sagar  B. Mettur  C. Ukai  D. Gandhi Sagar; 1. Tapi  2. Chambal  3. Krishna  4. Kaveri","options":["A-3, B-2, C-1, D-4","A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2","A-4, B-3, C-1, D-2"],"answer":1,"explanation":"Nagarjuna Sagar is on the Krishna, Mettur on the Kaveri, Ukai on the Tapi and Gandhi Sagar on the Chambal.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"बाँध का उसकी नदी से मिलान कीजिए। A. नागार्जुन सागर  B. मेट्टूर  C. उकाई  D. गांधी सागर; 1. ताप्ती  2. चंबल  3. कृष्णा  4. कावेरी","optionsHi":["A-3, B-2, C-1, D-4","A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2","A-4, B-3, C-1, D-2"],"explanationHi":"नागार्जुन सागर कृष्णा पर, मेट्टूर कावेरी पर, उकाई ताप्ती पर और गांधी सागर चंबल पर है।"},
  {"id":"geo-soils-agriculture-34","question":"How many of the following statements about the Green Revolution are correct? I. It began in the mid-1960s with high-yielding rice varieties developed in Mexico. II. Its early benefits were concentrated in Punjab, Haryana and western Uttar Pradesh. III. It contributed to regional inequality and to falling groundwater tables. IV. Pulses showed the sharpest rise in production.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"II and III are correct. The varieties developed in Mexico were high-yielding wheat (rice HYVs came from the Philippines), and the gains came mainly in wheat and later rice while pulses stagnated, so I and IV are wrong.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"हरित क्रांति के बारे में निम्नलिखित में से कितने कथन सही हैं? I. इसकी शुरुआत 1960 के दशक के मध्य में मेक्सिको में विकसित उच्च उपज वाली चावल किस्मों से हुई। II. इसके प्रारंभिक लाभ पंजाब, हरियाणा और पश्चिमी उत्तर प्रदेश में केंद्रित थे। III. इसने क्षेत्रीय असमानता और भूजल स्तर के गिरने में योगदान दिया। IV. दलहनों के उत्पादन में सबसे तेज़ वृद्धि हुई।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"II और III सही हैं। मेक्सिको में विकसित किस्में उच्च उपज वाले गेहूँ की थीं (चावल की HYV फिलीपींस से आईं), और लाभ मुख्यतः गेहूँ तथा बाद में चावल में हुए जबकि दलहन स्थिर रहे, इसलिए I और IV गलत हैं।"},
  {"id":"geo-soils-agriculture-35","question":"Which of the following pairs of crop and season is NOT correctly matched?","options":["Ragi — rabi","Barley — rabi","Gram — rabi","Tur (arhar) — kharif"],"answer":0,"explanation":"Ragi is mainly a kharif millet grown in Karnataka and Tamil Nadu; tur is a kharif pulse, and gram and barley are rabi crops.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"फसल और मौसम के निम्नलिखित युग्मों में से कौन-सा सही सुमेलित नहीं है?","optionsHi":["रागी — रबी","जौ — रबी","चना — रबी","अरहर (तूर) — खरीफ"],"explanationHi":"रागी मुख्यतः खरीफ का मोटा अनाज है जो कर्नाटक और तमिलनाडु में उगाया जाता है; अरहर खरीफ की दलहन है, और चना तथा जौ रबी फसलें हैं।"},
  {"id":"geo-soils-agriculture-36","question":"Black soil covers large parts of all of the following EXCEPT:","options":["Saurashtra in Gujarat","The Malwa plateau of Madhya Pradesh","Assam","Maharashtra"],"answer":2,"explanation":"Black soil lies over the Deccan lava region: Maharashtra, Malwa, Saurashtra and parts of Karnataka, Telangana and Andhra Pradesh. Assam has mainly alluvial soil.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"काली मृदा निम्नलिखित सभी के बड़े भागों में फैली है, सिवाय:","optionsHi":["गुजरात के सौराष्ट्र","मध्य प्रदेश के मालवा पठार","असम","महाराष्ट्र"],"explanationHi":"काली मृदा दक्कन के लावा क्षेत्र में फैली है: महाराष्ट्र, मालवा, सौराष्ट्र तथा कर्नाटक, तेलंगाना और आंध्र प्रदेश के कुछ भाग। असम में मुख्यतः जलोढ़ मृदा है।"},
  {"id":"geo-soils-agriculture-37","question":"How many of the following statements are correct? I. Wheat needs a cool growing season and bright sunshine when the grain ripens. II. Sugarcane is a tropical and subtropical crop needing about 75–100 cm of rain. III. Tea bushes need frost during the growing season. IV. Maize is grown only as a rabi crop.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct. Tea needs a frost-free climate (III wrong), and maize is mainly a kharif crop, though grown in rabi in some states such as Bihar (IV wrong).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कितने कथन सही हैं? I. गेहूँ को ठंडा वृद्धि काल और दाना पकते समय तेज़ धूप चाहिए। II. गन्ना एक उष्णकटिबंधीय और उपोष्णकटिबंधीय फसल है जिसे लगभग 75–100 सेमी वर्षा चाहिए। III. चाय की झाड़ियों को वृद्धि काल में पाला चाहिए। IV. मक्का केवल रबी फसल के रूप में उगाई जाती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II सही हैं। चाय को पाला-रहित जलवायु चाहिए (III गलत), और मक्का मुख्यतः खरीफ फसल है, यद्यपि बिहार जैसे कुछ राज्यों में यह रबी में भी उगाई जाती है (IV गलत)।"},
  {"id":"geo-soils-agriculture-38","question":"Match the soil with its feature. A. Alluvial  B. Black  C. Laterite  D. Red; 1. Colour from iron diffused through crystalline rocks  2. Self-ploughing, with cracks in summer  3. Divided into khadar and bhangar  4. Formed by intense leaching; hardens on exposure and is cut as bricks","options":["A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-2, B-3, C-4, D-1","A-3, B-2, C-4, D-1"],"answer":3,"explanation":"Alluvial soil is divided into khadar (new) and bhangar (old); black soil is self-ploughing; laterite results from leaching and is used as building brick; red soil gets its colour from iron.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"मृदा का मिलान उसकी विशेषता से कीजिए। A. जलोढ़  B. काली  C. लेटराइट  D. लाल; 1. क्रिस्टलीय चट्टानों में फैले आयरन से रंग  2. स्वतः जुताई वाली, गर्मियों में दरारें पड़ती हैं  3. खादर और भांगर में विभाजित  4. तीव्र निक्षालन से बनी; खुली हवा में कठोर हो जाती है और ईंटों के रूप में काटी जाती है","optionsHi":["A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-2, B-3, C-4, D-1","A-3, B-2, C-4, D-1"],"explanationHi":"जलोढ़ मृदा खादर (नवीन) और भांगर (प्राचीन) में विभाजित है; काली मृदा स्वतः जुताई वाली है; लेटराइट निक्षालन से बनती है और भवन निर्माण की ईंट के रूप में प्रयोग होती है; लाल मृदा को अपना रंग आयरन से मिलता है।"},
  {"id":"geo-soils-agriculture-39","question":"How many of the following statements are correct? I. The Soil Health Card scheme was launched in 2015. II. “Har Khet Ko Pani” and “More crop per drop” are slogans of the Pradhan Mantri Krishi Sinchayee Yojana. III. The Kisan Credit Card scheme was introduced in 1998. IV. Operation Flood was implemented by the National Dairy Development Board.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: Soil Health Cards began in 2015 at Suratgarh (Rajasthan), PMKSY uses both slogans, KCC dates from 1998, and the NDDB ran Operation Flood.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कितने कथन सही हैं? I. मृदा स्वास्थ्य कार्ड योजना 2015 में शुरू की गई थी। II. “हर खेत को पानी” और “प्रति बूँद अधिक फसल” प्रधानमंत्री कृषि सिंचाई योजना के नारे हैं। III. किसान क्रेडिट कार्ड योजना 1998 में शुरू की गई थी। IV. ऑपरेशन फ्लड को राष्ट्रीय डेयरी विकास बोर्ड ने लागू किया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं: मृदा स्वास्थ्य कार्ड 2015 में सूरतगढ़ (राजस्थान) से शुरू हुए, PMKSY में दोनों नारे प्रयुक्त होते हैं, KCC 1998 से है, और NDDB ने ऑपरेशन फ्लड चलाया।"},
  {"id":"geo-soils-agriculture-40","question":"Identify the crop: it is mainly a kharif oilseed, grows best on well-drained sandy loams with moderate rain, and Gujarat is its largest producer.","options":["Sunflower","Soybean","Mustard","Groundnut"],"answer":3,"explanation":"Groundnut is a kharif oilseed of light sandy soils, led by Gujarat; mustard is a rabi crop of the north, and soybean is concentrated in Madhya Pradesh and Maharashtra.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"फसल पहचानिए: यह मुख्यतः खरीफ की तिलहन फसल है, मध्यम वर्षा वाली अच्छी जल-निकासी की बलुई दोमट मृदा में सबसे अच्छी उगती है, और गुजरात इसका सबसे बड़ा उत्पादक है।","optionsHi":["सूरजमुखी","सोयाबीन","सरसों","मूँगफली"],"explanationHi":"मूँगफली हल्की बलुई मृदाओं की खरीफ तिलहन है, जिसमें गुजरात अग्रणी है; सरसों उत्तर की रबी फसल है, और सोयाबीन मध्य प्रदेश और महाराष्ट्र में केंद्रित है।"},
  {"id":"geo-soils-agriculture-41","question":"Which soil covers the largest area of India?","options":["Black soil","Laterite soil","Alluvial soil","Desert soil"],"answer":2,"explanation":"Alluvial soil, laid down by the Indus, Ganga and Brahmaputra systems and in the coastal deltas, covers about 40% of India's area, more than any other soil.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"कौन-सी मृदा भारत के सबसे बड़े क्षेत्र में फैली है?","optionsHi":["काली मृदा","लेटराइट मृदा","जलोढ़ मृदा","मरुस्थलीय मृदा"],"explanationHi":"सिंधु, गंगा और ब्रह्मपुत्र तंत्रों द्वारा तथा तटीय डेल्टाओं में निक्षेपित जलोढ़ मृदा भारत के लगभग 40% क्षेत्र में फैली है, जो किसी भी अन्य मृदा से अधिक है।"},
  {"id":"geo-soils-agriculture-42","question":"Jute is often called the:","options":["Golden fibre","White gold","Black gold","Silver fibre"],"answer":0,"explanation":"Jute is called the golden fibre for its colour and its value; 'white gold' is a nickname for cotton and 'black gold' for petroleum.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"जूट को प्रायः क्या कहा जाता है?","optionsHi":["सुनहरा रेशा","सफेद सोना","काला सोना","रजत रेशा"],"explanationHi":"जूट को उसके रंग और मूल्य के कारण सुनहरा रेशा कहा जाता है; ‘सफेद सोना’ कपास का और ‘काला सोना’ पेट्रोलियम का उपनाम है।"},
  {"id":"geo-soils-agriculture-43","question":"A farmer who grows crops and also rears cattle and poultry on the same farm practises:","options":["Shifting cultivation","Mixed farming","Plantation farming","Nomadic herding"],"answer":1,"explanation":"Mixed farming combines crop growing with livestock rearing, so the animals give manure and draught power and the crops give fodder.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"जो किसान एक ही खेत में फसलें उगाता है और साथ ही पशु व मुर्गी पालन भी करता है, वह कौन-सी कृषि करता है?","optionsHi":["स्थानांतरित कृषि","मिश्रित कृषि","रोपण कृषि","घुमंतू पशुचारण"],"explanationHi":"मिश्रित कृषि में फसल उगाने के साथ पशुपालन भी किया जाता है, जिससे पशु खाद और भार-वाहक शक्ति देते हैं तथा फसलें चारा देती हैं।"},
  {"id":"geo-soils-agriculture-44","question":"Growing two or more crops one after another on the same field in a single year is called:","options":["Monoculture","Ley farming","Shifting cultivation","Multiple cropping"],"answer":3,"explanation":"Multiple cropping raises the cropping intensity of a field, for example rice in kharif followed by wheat in rabi. Monoculture means a single crop year after year.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"एक ही वर्ष में एक ही खेत में एक के बाद एक दो या अधिक फसलें उगाना क्या कहलाता है?","optionsHi":["एकल फसली कृषि","लेय कृषि","स्थानांतरित कृषि","बहुफसली कृषि"],"explanationHi":"बहुफसली कृषि से खेत की फसल गहनता बढ़ती है, जैसे खरीफ में चावल के बाद रबी में गेहूँ। एकल फसली कृषि का अर्थ है वर्ष-दर-वर्ष एक ही फसल उगाना।"},
  {"id":"geo-soils-agriculture-45","question":"Soil erosion by wind is most serious in:","options":["The flood-prone Brahmaputra valley","The steep Western Ghats slopes","The arid west of Rajasthan","The tidal Sundarbans islands"],"answer":2,"explanation":"Loose sand, sparse vegetation and strong winds make wind erosion a major problem in the Thar region; elsewhere running water is the main agent.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"पवन द्वारा मृदा अपरदन सबसे गंभीर कहाँ है?","optionsHi":["बाढ़-प्रवण ब्रह्मपुत्र घाटी में","पश्चिमी घाट के तीव्र ढालों पर","राजस्थान के शुष्क पश्चिमी भाग में","ज्वारीय सुंदरबन द्वीपों में"],"explanationHi":"ढीली रेत, विरल वनस्पति और तेज़ हवाओं के कारण थार क्षेत्र में पवन अपरदन एक प्रमुख समस्या है; अन्यत्र बहता जल मुख्य कारक है।"},
  {"id":"geo-soils-agriculture-46","question":"Laterite soils develop mainly under:","options":["Cold, dry conditions with very little leaching","Heat and heavy seasonal rain causing intense leaching","Waterlogged, marshy conditions with decaying plants","Wind deposition of fine sand in hot deserts"],"answer":1,"explanation":"Heavy rain leaches away silica and lime, leaving iron and aluminium oxides behind. That is why laterites are found on the summits of the Ghats and on the Meghalaya plateau.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"लेटराइट मृदाएँ मुख्यतः किन परिस्थितियों में विकसित होती हैं?","optionsHi":["ठंडी, शुष्क परिस्थितियाँ जिनमें निक्षालन बहुत कम हो","गर्मी और भारी मौसमी वर्षा, जिससे तीव्र निक्षालन होता है","जलमग्न, दलदली परिस्थितियाँ जिनमें पौधे सड़ते हैं","गर्म मरुस्थलों में पवन द्वारा महीन रेत का निक्षेपण"],"explanationHi":"भारी वर्षा सिलिका और चूने को बहा ले जाती है, जिससे आयरन और ऐलुमिनियम के ऑक्साइड शेष रह जाते हैं। इसीलिए लेटराइट मृदाएँ घाटों की चोटियों और मेघालय पठार पर पाई जाती हैं।"},
  {"id":"geo-soils-agriculture-47","question":"Peaty soils, rich in organic matter and often black and acidic, develop mainly in:","options":["The dry interior of the Deccan plateau","The sandy tracts of western Rajasthan","The cold desert of Ladakh","Badly drained humid coasts and deltas"],"answer":3,"explanation":"Heavy rain and waterlogging let dead plant matter pile up faster than it decomposes, forming peaty soils. Dry regions cannot build up such organic matter.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"पीट मृदाएँ, जो जैव पदार्थ से समृद्ध और प्रायः काली तथा अम्लीय होती हैं, मुख्यतः कहाँ विकसित होती हैं?","optionsHi":["दक्कन पठार के शुष्क आंतरिक भाग में","पश्चिमी राजस्थान के रेतीले क्षेत्रों में","लद्दाख के शीत मरुस्थल में","खराब जल-निकासी वाले आर्द्र तटों और डेल्टाओं में"],"explanationHi":"भारी वर्षा और जलभराव के कारण मृत वनस्पति पदार्थ सड़ने की अपेक्षा तेज़ी से जमा होता है, जिससे पीट मृदाएँ बनती हैं। शुष्क क्षेत्रों में ऐसा जैव पदार्थ जमा नहीं हो सकता।"},
  {"id":"geo-soils-agriculture-48","question":"The deep ravines along the Chambal river are the result of:","options":["Sheet erosion by rain","Wind erosion and deflation","Gully erosion by running water","Glacial erosion in the Ice Age"],"answer":2,"explanation":"Running water cuts deep channels (gullies) in soft soil; these widen into the badlands of the Chambal. Sheet erosion removes a thin layer evenly over a wide area.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"चंबल नदी के किनारे की गहरी खड्ड-भूमि (उत्खात भूमि) किसका परिणाम है?","optionsHi":["वर्षा द्वारा परत अपरदन","पवन अपरदन और अपवाहन","बहते जल द्वारा अवनालिका अपरदन","हिमयुग में हिमानी अपरदन"],"explanationHi":"बहता जल मुलायम मृदा में गहरी नालियाँ (अवनालिकाएँ) काट देता है; ये चौड़ी होकर चंबल की उत्खात भूमि (बैडलैंड) बन जाती हैं। परत अपरदन में एक विस्तृत क्षेत्र से मृदा की पतली परत समान रूप से हट जाती है।"},
  {"id":"geo-soils-agriculture-49","question":"Which of these is a rabi oilseed?","options":["Groundnut","Mustard","Soybean","Sesamum grown in the monsoon"],"answer":1,"explanation":"Rapeseed-mustard is sown in October–November and harvested in spring, mainly in Rajasthan, Haryana and Uttar Pradesh. Groundnut and soybean are kharif crops.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"इनमें से कौन-सी रबी तिलहन है?","optionsHi":["मूँगफली","सरसों","सोयाबीन","मानसून में उगाया गया तिल"],"explanationHi":"राई-सरसों अक्टूबर–नवंबर में बोई जाती है और वसंत में काटी जाती है, मुख्यतः राजस्थान, हरियाणा और उत्तर प्रदेश में। मूँगफली और सोयाबीन खरीफ फसलें हैं।"},
  {"id":"geo-soils-agriculture-50","question":"Which of these is NOT a feature of plantation agriculture?","options":["A single crop grown on a large estate","Large capital investment and hired labour","Produce grown mainly for sale and processing","Small family plots growing food for the home"],"answer":3,"explanation":"Plantations such as tea, coffee and rubber are large, capital-intensive, single-crop estates for the market. Family plots for home consumption describe subsistence farming.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"इनमें से कौन-सी रोपण कृषि की विशेषता नहीं है?","optionsHi":["एक बड़े एस्टेट पर एकल फसल उगाना","बड़ी पूँजी का निवेश और किराये का श्रम","उपज का मुख्यतः बिक्री और प्रसंस्करण के लिए उत्पादन","घर के लिए खाद्यान्न उगाने वाले छोटे पारिवारिक खेत"],"explanationHi":"चाय, कॉफी और रबर जैसे रोपण बड़े, पूँजी-प्रधान, एकल फसल वाले एस्टेट होते हैं जो बाज़ार के लिए उत्पादन करते हैं। घरेलू उपभोग के लिए पारिवारिक खेत निर्वाह कृषि का वर्णन करते हैं।"},
  {"id":"geo-soils-agriculture-51","question":"Intensive subsistence farming, where high doses of inputs and labour are used on small plots, is typical of:","options":["Thinly populated areas with large farms","Densely populated areas where land is scarce","Cold deserts with a very short growing season","Commercial ranching areas of the grasslands"],"answer":1,"explanation":"Where land is scarce, farmers use heavy labour, manure and irrigation to get the most from a small plot, as on the rice fields of the Ganga plain and coastal deltas.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"गहन निर्वाह कृषि, जिसमें छोटे खेतों पर अधिक मात्रा में आदानों और श्रम का उपयोग होता है, किसकी विशिष्टता है?","optionsHi":["बड़े खेतों वाले विरल आबादी के क्षेत्र","घनी आबादी वाले क्षेत्र जहाँ भूमि दुर्लभ है","शीत मरुस्थल जहाँ वृद्धि काल बहुत छोटा होता है","घास के मैदानों के वाणिज्यिक पशुपालन क्षेत्र"],"explanationHi":"जहाँ भूमि कम होती है, वहाँ किसान छोटे खेत से अधिकतम उपज लेने के लिए भारी श्रम, खाद और सिंचाई का प्रयोग करते हैं, जैसे गंगा के मैदान और तटीय डेल्टाओं के धान के खेतों में।"},
  {"id":"geo-soils-agriculture-52","question":"Canals drawn from rivers through barrages or weirs that supply water throughout the year are called:","options":["Perennial canals","Inundation canals","Distributaries of tanks","Karez channels"],"answer":0,"explanation":"Perennial canals have a regulated, year-round supply from snow-fed or dammed rivers. Inundation canals carry water only when the river is in flood.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"बैराज या वियर के माध्यम से नदियों से निकाली गई वे नहरें, जो पूरे वर्ष जल पहुँचाती हैं, क्या कहलाती हैं?","optionsHi":["सदानीरा नहरें","बाढ़ (अंतःप्लावन) नहरें","तालाबों की वितरिकाएँ","करेज नालियाँ"],"explanationHi":"सदानीरा नहरों में हिम-पोषित या बाँध वाली नदियों से नियमित, वर्ष भर जल-आपूर्ति होती है। बाढ़ नहरें केवल तब जल ले जाती हैं जब नदी में बाढ़ आती है।"},
  {"id":"geo-soils-agriculture-53","question":"Shifting cultivation is known as 'Podu' in:","options":["Andhra Pradesh and Odisha","Mizoram and Manipur","Punjab and Haryana","Madhya Pradesh"],"answer":0,"explanation":"The slash-and-burn practice is called Podu in Andhra Pradesh and Odisha, Jhum in the north-east and Bewar or Dahiya in Madhya Pradesh.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"स्थानांतरित कृषि को किस क्षेत्र में ‘पोडू’ कहा जाता है?","optionsHi":["आंध्र प्रदेश और ओडिशा","मिज़ोरम और मणिपुर","पंजाब और हरियाणा","मध्य प्रदेश"],"explanationHi":"काटो और जलाओ की इस पद्धति को आंध्र प्रदेश और ओडिशा में पोडू, उत्तर-पूर्व में झूम और मध्य प्रदेश में बेवर या दहिया कहा जाता है।"},
  {"id":"geo-soils-agriculture-54","question":"Indian agriculture has been called a 'gamble on the monsoon' mainly because:","options":["Most crops are grown only in the dry winter season","Most farmland is rain-fed, so output tracks rainfall","India has almost no irrigation canals, tanks or wells","The monsoon brings frost and hail every year"],"answer":1,"explanation":"A large share of the net sown area still depends on rainfall, so a weak or erratic monsoon cuts kharif output and farm incomes.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"भारतीय कृषि को ‘मानसून पर जुआ’ मुख्यतः इसलिए कहा गया है क्योंकि:","optionsHi":["अधिकांश फसलें केवल शुष्क शीत ऋतु में उगाई जाती हैं","अधिकांश कृषि भूमि वर्षा-आधारित है, इसलिए उत्पादन वर्षा के अनुसार घटता-बढ़ता है","भारत में लगभग कोई सिंचाई नहरें, तालाब या कुएँ नहीं हैं","मानसून हर वर्ष पाला और ओले लाता है"],"explanationHi":"शुद्ध बोए गए क्षेत्र का एक बड़ा हिस्सा अब भी वर्षा पर निर्भर है, इसलिए कमज़ोर या अनियमित मानसून खरीफ उत्पादन और किसानों की आय घटा देता है।"},
  {"id":"geo-soils-agriculture-55","question":"Red soil appears yellow when:","options":["It is hydrated","It is rich in humus","It is waterlogged with salt","It contains lime nodules"],"answer":0,"explanation":"Red soil gets its colour from iron diffused through crystalline rocks; in hydrated form the iron oxide gives a yellow colour, hence 'red and yellow soils'.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"लाल मृदा पीली कब दिखाई देती है?","optionsHi":["जब वह जलयोजित हो","जब वह ह्यूमस से समृद्ध हो","जब वह नमक के साथ जलमग्न हो","जब उसमें चूने की ग्रंथियाँ हों"],"explanationHi":"लाल मृदा को अपना रंग क्रिस्टलीय चट्टानों में फैले आयरन से मिलता है; जलयोजित रूप में आयरन ऑक्साइड पीला रंग देता है, इसीलिए इन्हें ‘लाल और पीली मृदाएँ’ कहा जाता है।"},
  {"id":"geo-soils-agriculture-56","question":"In the snow-bound areas of the high Himalaya, soils are typically:","options":["Rich in humus and strongly alkaline","Thick, deep and highly fertile","Saline and rich in sodium salts","Acidic, low in humus and denuded"],"answer":3,"explanation":"NCERT notes that soils of the snow-bound Himalaya undergo denudation and are acidic with low humus; the deeper, fertile forest soils occur lower down on valley slopes.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"उच्च हिमालय के हिमाच्छादित क्षेत्रों में मृदाएँ प्रायः कैसी होती हैं?","optionsHi":["ह्यूमस से समृद्ध और अत्यधिक क्षारीय","मोटी, गहरी और अत्यंत उपजाऊ","लवणीय और सोडियम लवणों से समृद्ध","अम्लीय, ह्यूमस में कम और अनाच्छादित"],"explanationHi":"NCERT के अनुसार हिमाच्छादित हिमालय की मृदाओं का अनाच्छादन होता है और वे अम्लीय तथा कम ह्यूमस वाली होती हैं; अधिक गहरी, उपजाऊ वन मृदाएँ घाटी के ढालों पर नीचे की ओर मिलती हैं।"},
  {"id":"geo-soils-agriculture-57","question":"Saline and alkaline soils are locally known as:","options":["Regur and kankar","Khadar and bhangar","Reh, kallar and usar","Bhabar, terai and duar"],"answer":2,"explanation":"Reh, kallar and usar are local names for salt-affected, infertile soils in Uttar Pradesh, Punjab and Haryana. Regur is black soil, and khadar/bhangar are new and old alluvium.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"लवणीय और क्षारीय मृदाएँ स्थानीय रूप से किन नामों से जानी जाती हैं?","optionsHi":["रेगुर और कंकड़","खादर और भांगर","रेह, कल्लर और ऊसर","भाबर, तराई और दुआर"],"explanationHi":"रेह, कल्लर और ऊसर उत्तर प्रदेश, पंजाब और हरियाणा की लवण-प्रभावित, अनुपजाऊ मृदाओं के स्थानीय नाम हैं। रेगुर काली मृदा है, और खादर/भांगर नवीन और प्राचीन जलोढ़ हैं।"},
  {"id":"geo-soils-agriculture-58","question":"Which state is the largest producer of mulberry silk in India?","options":["Assam","Karnataka","West Bengal","Jammu and Kashmir"],"answer":1,"explanation":"Karnataka, around Ramanagara and Mysuru, produces the largest share of India's mulberry silk. Assam is known for muga and eri silk rather than mulberry.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"भारत में शहतूती रेशम (मलबरी सिल्क) का सबसे बड़ा उत्पादक राज्य कौन-सा है?","optionsHi":["असम","कर्नाटक","पश्चिम बंगाल","जम्मू और कश्मीर"],"explanationHi":"कर्नाटक, रामनगर और मैसूरु के आसपास, भारत के शहतूती रेशम का सबसे बड़ा हिस्सा उत्पादित करता है। असम शहतूती नहीं, बल्कि मूगा और एरी रेशम के लिए जाना जाता है।"},
  {"id":"geo-soils-agriculture-59","question":"The Planning Commission divided India into how many agro-climatic regions for agricultural planning?","options":["8","10","15","20"],"answer":2,"explanation":"The Planning Commission (1988–89) identified 15 agro-climatic regions based on soil, climate, physiography and water resources. Eight is the number of major soil groups in the NCERT classification.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"योजना आयोग ने कृषि नियोजन के लिए भारत को कितने कृषि-जलवायु प्रदेशों में बाँटा?","optionsHi":["8","10","15","20"],"explanationHi":"योजना आयोग (1988–89) ने मृदा, जलवायु, भू-आकृति और जल संसाधनों के आधार पर 15 कृषि-जलवायु प्रदेश निर्धारित किए। आठ NCERT वर्गीकरण में प्रमुख मृदा समूहों की संख्या है।"},
  {"id":"geo-soils-agriculture-60","question":"Coffee cultivation in India began with Arabica seeds that Baba Budan is said to have brought from Yemen and planted in the hills of:","options":["The Nilgiris, Tamil Nadu","Kodagu (Coorg), Karnataka","Wayanad, Kerala","Chikkamagaluru, Karnataka"],"answer":3,"explanation":"The Baba Budan hills near Chikkamagaluru are where coffee is said to have first been grown in India, from Arabica seeds brought from Yemen.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"भारत में कॉफी की खेती अरेबिका बीजों से शुरू हुई, जिन्हें बाबा बुदन द्वारा यमन से लाकर किन पहाड़ियों में लगाया माना जाता है?","optionsHi":["नीलगिरि, तमिलनाडु","कोडागु (कूर्ग), कर्नाटक","वायनाड, केरल","चिकमगलूर, कर्नाटक"],"explanationHi":"चिकमगलूर के पास की बाबा बुदन पहाड़ियों में भारत में पहली बार कॉफी उगाई गई मानी जाती है, जो यमन से लाए गए अरेबिका बीजों से शुरू हुई थी।"},
  {"id":"geo-soils-agriculture-61","question":"In the production of fruits and vegetables, India ranks:","options":["Second in the world, after China","First in the world, ahead of China","Third, after China and the USA","Fifth in the world, after Brazil"],"answer":0,"explanation":"India is the world's second largest producer of both fruits and vegetables, behind China.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"फलों और सब्जियों के उत्पादन में भारत का स्थान क्या है?","optionsHi":["विश्व में दूसरा, चीन के बाद","विश्व में पहला, चीन से आगे","तीसरा, चीन और अमेरिका के बाद","विश्व में पाँचवाँ, ब्राज़ील के बाद"],"explanationHi":"भारत फलों और सब्जियों, दोनों का विश्व का दूसरा सबसे बड़ा उत्पादक है, चीन से पीछे।"},
  {"id":"geo-soils-agriculture-62","question":"According to NCERT, dryland farming is largely confined to regions that receive annual rainfall of less than:","options":["25 cm","75 cm","150 cm","200 cm"],"answer":1,"explanation":"Dryland farming, with hardy crops like ragi, bajra, moong, gram and guar, is found where rainfall is below about 75 cm; wetland farming is where rain exceeds the crops' needs.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"NCERT के अनुसार, शुष्क भूमि कृषि मुख्यतः उन क्षेत्रों तक सीमित है जहाँ वार्षिक वर्षा कितने से कम होती है?","optionsHi":["25 सेमी","75 सेमी","150 सेमी","200 सेमी"],"explanationHi":"रागी, बाजरा, मूँग, चना और ग्वार जैसी सहनशील फसलों वाली शुष्क भूमि कृषि वहाँ होती है जहाँ वर्षा लगभग 75 सेमी से कम होती है; आर्द्र भूमि कृषि वहाँ होती है जहाँ वर्षा फसलों की आवश्यकता से अधिक होती है।"},
  {"id":"geo-soils-agriculture-63","question":"Which of the following is NOT one of the eight major soil groups in the NCERT classification of Indian soils?","options":["Peaty soil","Saline soil","Podzol","Forest soil"],"answer":2,"explanation":"NCERT lists alluvial, black, red and yellow, laterite, arid, saline, peaty and forest soils. Podzols are soils of cool, coniferous regions and are not among them.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"निम्नलिखित में से कौन-सी भारतीय मृदाओं के NCERT वर्गीकरण के आठ प्रमुख मृदा समूहों में से एक नहीं है?","optionsHi":["पीट मृदा","लवणीय मृदा","पॉडज़ॉल","वन मृदा"],"explanationHi":"NCERT जलोढ़, काली, लाल और पीली, लेटराइट, शुष्क, लवणीय, पीट तथा वन मृदाओं को सूचीबद्ध करता है। पॉडज़ॉल ठंडे, शंकुधारी क्षेत्रों की मृदाएँ हैं और इनमें सम्मिलित नहीं हैं।"},
  {"id":"geo-soils-agriculture-64","question":"Identify the crop: it is a rabi pulse grown largely on residual moisture in Madhya Pradesh, Maharashtra and Rajasthan, and India is the world's largest producer of it.","options":["Arhar (pigeon pea)","Urad (black gram)","Moong (green gram)","Gram (chickpea)"],"answer":3,"explanation":"Gram is a rabi pulse of drier areas grown on residual soil moisture, and India is its largest producer. Arhar, urad and moong are mainly kharif pulses; do not let the word 'gram' in their English names mislead you.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"फसल पहचानिए: यह रबी की दलहन है जो मुख्यतः मध्य प्रदेश, महाराष्ट्र और राजस्थान में अवशिष्ट नमी पर उगाई जाती है, और भारत इसका विश्व का सबसे बड़ा उत्पादक है।","optionsHi":["अरहर","उड़द","मूँग","चना"],"explanationHi":"चना शुष्क क्षेत्रों की रबी दलहन है जो मृदा की अवशिष्ट नमी पर उगाई जाती है, और भारत इसका सबसे बड़ा उत्पादक है। अरहर, उड़द और मूँग मुख्यतः खरीफ दलहन हैं; इनके अंग्रेज़ी नामों में ‘gram’ शब्द से भ्रमित न हों।"},
  {"id":"geo-soils-agriculture-65","question":"Which of these is NOT a millet?","options":["Sorghum","Barley","Bajra","Ragi"],"answer":1,"explanation":"Sorghum (jowar), bajra and ragi are millets, hardy grains of dry areas. Barley is a temperate rabi cereal, not a millet.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"इनमें से कौन-सा मोटा अनाज (millet) नहीं है?","optionsHi":["ज्वार","जौ","बाजरा","रागी"],"explanationHi":"ज्वार, बाजरा और रागी मोटे अनाज हैं, जो शुष्क क्षेत्रों के सहनशील अनाज हैं। जौ एक शीतोष्ण रबी अनाज है, मोटा अनाज नहीं।"},
  {"id":"geo-soils-agriculture-66","question":"Sprinkler irrigation is especially suited to:","options":["Sandy soils and uneven land","Clayey soils in flat river deltas","Paddy fields that need standing water","Saline marshes near the coast"],"answer":0,"explanation":"Sprinklers spray water like rain, so they work on light, sandy soils and undulating land where water would run off or seep away under flood irrigation.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"फव्वारा (स्प्रिंकलर) सिंचाई विशेष रूप से किसके लिए उपयुक्त है?","optionsHi":["रेतीली मृदाएँ और असमतल भूमि","समतल नदी डेल्टाओं की चिकनी मृदाएँ","धान के खेत जिन्हें खड़ा पानी चाहिए","तट के निकट लवणीय दलदल"],"explanationHi":"स्प्रिंकलर वर्षा की तरह पानी छिड़कते हैं, इसलिए वे हल्की, रेतीली मृदाओं और ऊबड़-खाबड़ भूमि पर कारगर हैं, जहाँ बाढ़ सिंचाई में पानी बह जाता या रिस जाता है।"},
  {"id":"geo-soils-agriculture-67","question":"Which state was declared India's first fully organic state in 2016?","options":["Kerala","Himachal Pradesh","Mizoram","Sikkim"],"answer":3,"explanation":"Sikkim converted all its farmland to certified organic farming and was declared fully organic in 2016.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"2016 में किस राज्य को भारत का पहला पूर्ण जैविक राज्य घोषित किया गया?","optionsHi":["केरल","हिमाचल प्रदेश","मिज़ोरम","सिक्किम"],"explanationHi":"सिक्किम ने अपनी सारी कृषि भूमि को प्रमाणित जैविक खेती में बदल दिया और 2016 में उसे पूर्णतः जैविक राज्य घोषित किया गया।"},
  {"id":"geo-soils-agriculture-68","question":"Match the traditional water-harvesting system with its region. A. Kuls  B. Zings  C. Eris  D. Khadins; 1. Ladakh  2. Western Himalaya (Himachal Pradesh)  3. Jaisalmer, Rajasthan  4. Tamil Nadu","options":["A-1, B-2, C-4, D-3","A-2, B-1, C-3, D-4","A-2, B-1, C-4, D-3","A-2, B-4, C-1, D-3"],"answer":2,"explanation":"Kuls are diversion channels of the western Himalaya, zings are glacier-melt tanks in Ladakh, eris are tanks of Tamil Nadu and khadins are runoff-harvesting fields of Jaisalmer.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"पारंपरिक जल-संचयन प्रणाली का उसके क्षेत्र से मिलान कीजिए। A. कूल  B. ज़िंग  C. एरी  D. खड़ीन; 1. लद्दाख  2. पश्चिमी हिमालय (हिमाचल प्रदेश)  3. जैसलमेर, राजस्थान  4. तमिलनाडु","optionsHi":["A-1, B-2, C-4, D-3","A-2, B-1, C-3, D-4","A-2, B-1, C-4, D-3","A-2, B-4, C-1, D-3"],"explanationHi":"कूल पश्चिमी हिमालय की अपवर्तन नहरें हैं, ज़िंग लद्दाख में हिमगलन जल के कुंड हैं, एरी तमिलनाडु के तालाब हैं और खड़ीन जैसलमेर के अपवाह-संचयन वाले खेत हैं।"},
  {"id":"geo-soils-agriculture-69","question":"How many of the following statements about alluvial soils are correct? I. Khadar is the older alluvium lying above the flood level. II. Alluvial soils are generally rich in phosphorus but poor in potash. III. Bhangar, the older alluvium, contains kankar nodules. IV. Alluvial soils are absent from the Brahmaputra valley.","options":["Only one","Only two","All four","Only three"],"answer":0,"explanation":"Only III is correct. Khadar is the newer alluvium renewed by floods; alluvial soils are generally rich in potash but poor in phosphorus (not the reverse); and the Brahmaputra valley is a major alluvial plain.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"जलोढ़ मृदाओं के बारे में निम्नलिखित में से कितने कथन सही हैं? I. खादर प्राचीन जलोढ़ है जो बाढ़ स्तर से ऊपर स्थित होता है। II. जलोढ़ मृदाएँ सामान्यतः फॉस्फोरस में समृद्ध पर पोटाश में निर्धन होती हैं। III. भांगर, प्राचीन जलोढ़, में कंकड़ ग्रंथियाँ होती हैं। IV. ब्रह्मपुत्र घाटी में जलोढ़ मृदाएँ नहीं पाई जातीं।","optionsHi":["केवल एक","केवल दो","सभी चार","केवल तीन"],"explanationHi":"केवल III सही है। खादर नवीन जलोढ़ है जिसका बाढ़ से नवीनीकरण होता है; जलोढ़ मृदाएँ सामान्यतः पोटाश में समृद्ध पर फॉस्फोरस में निर्धन होती हैं (उलटा नहीं); और ब्रह्मपुत्र घाटी एक प्रमुख जलोढ़ मैदान है।"},
  {"id":"geo-soils-agriculture-70","question":"Match the crop with the state that leads its production. A. Sugarcane  B. Ragi  C. Rapeseed-mustard  D. Apple; 1. Jammu and Kashmir  2. Rajasthan  3. Karnataka  4. Uttar Pradesh","options":["A-4, B-3, C-2, D-1","A-4, B-2, C-3, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2"],"answer":0,"explanation":"Uttar Pradesh leads in sugarcane, Karnataka in ragi, Rajasthan in rapeseed-mustard and Jammu and Kashmir in apples.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"फसल का मिलान उस राज्य से कीजिए जो उसके उत्पादन में अग्रणी है। A. गन्ना  B. रागी  C. राई-सरसों  D. सेब; 1. जम्मू और कश्मीर  2. राजस्थान  3. कर्नाटक  4. उत्तर प्रदेश","optionsHi":["A-4, B-3, C-2, D-1","A-4, B-2, C-3, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2"],"explanationHi":"उत्तर प्रदेश गन्ने में, कर्नाटक रागी में, राजस्थान राई-सरसों में और जम्मू और कश्मीर सेब में अग्रणी है।"},
  {"id":"geo-soils-agriculture-71","question":"Assertion (A): Pulses are often grown in rotation with cereals. Reason (R): Leguminous crops fix atmospheric nitrogen through bacteria in their root nodules.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Rhizobium bacteria in the root nodules of legumes fix nitrogen, restoring soil fertility for the next cereal crop. So R explains A.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): दलहनों को प्रायः अनाजों के साथ फसल चक्र में उगाया जाता है। कारण (R): दलहनी फसलें अपनी जड़ों की गाँठों में स्थित जीवाणुओं द्वारा वायुमंडलीय नाइट्रोजन का स्थिरीकरण करती हैं।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दलहनों की जड़ों की गाँठों में स्थित राइज़ोबियम जीवाणु नाइट्रोजन का स्थिरीकरण करते हैं, जिससे अगली अनाज फसल के लिए मृदा की उर्वरता लौट आती है। अतः R, A की व्याख्या करता है।"},
  {"id":"geo-soils-agriculture-72","question":"Assertion (A): Shifting cultivation leads to deforestation and soil erosion. Reason (R): Shifting cultivation is practised mainly in the Indo-Gangetic plain.","options":["Both A and R are true and R is the correct explanation of A","A is true but R is false","Both A and R are true but R is not the correct explanation of A","A is false but R is true"],"answer":1,"explanation":"A is true: forest is cleared and burnt and the bare slopes erode. R is false: shifting cultivation is found mainly in the north-eastern hills and the forested tribal belts of Odisha, Andhra Pradesh and Madhya Pradesh, not the plains.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): स्थानांतरित कृषि से वनों का क्षरण और मृदा अपरदन होता है। कारण (R): स्थानांतरित कृषि मुख्यतः सिंधु-गंगा के मैदान में की जाती है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A सत्य है, परंतु R असत्य है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A असत्य है, परंतु R सत्य है"],"explanationHi":"A सत्य है: वन काटकर जलाए जाते हैं और नंगे ढाल अपरदित होते हैं। R असत्य है: स्थानांतरित कृषि मुख्यतः उत्तर-पूर्वी पहाड़ियों और ओडिशा, आंध्र प्रदेश तथा मध्य प्रदेश की वनाच्छादित जनजातीय पट्टियों में होती है, मैदानों में नहीं।"},
  {"id":"geo-soils-agriculture-73","question":"How many of the following are sound methods of soil conservation? I. Contour ploughing on hill slopes. II. Shifting (jhum) cultivation on steep hill slopes. III. Burning crop stubble after harvest. IV. Ploughing up and down the slope.","options":["Only one","Only three","Only two","All four"],"answer":0,"explanation":"Only I is a conservation method; contour ploughing checks runoff. Jhum clears forest cover from slopes, stubble burning destroys organic matter and soil life, and ploughing up and down the slope makes channels that speed erosion.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"निम्नलिखित में से कितने मृदा संरक्षण के उचित तरीके हैं? I. पहाड़ी ढालों पर समोच्च जुताई। II. तीव्र पहाड़ी ढालों पर स्थानांतरित (झूम) कृषि। III. कटाई के बाद फसल के ठूँठ (पराली) को जलाना। IV. ढाल के ऊपर-नीचे जुताई करना।","optionsHi":["केवल एक","केवल तीन","केवल दो","सभी चार"],"explanationHi":"केवल I संरक्षण की विधि है; समोच्च जुताई अपवाह को रोकती है। झूम ढालों से वन आवरण हटा देती है, पराली जलाने से जैव पदार्थ और मृदा जीव नष्ट होते हैं, और ढाल के ऊपर-नीचे जुताई से बनी नालियाँ अपरदन को तेज़ करती हैं।"},
  {"id":"geo-soils-agriculture-74","question":"Match the term with what it involves. A. Ratooning  B. Viticulture  C. Apiculture  D. Pisciculture; 1. Grapes  2. Honey bees  3. Fish  4. Raising a new crop from the stubble of the old one, as in sugarcane","options":["A-4, B-2, C-1, D-3","A-4, B-1, C-3, D-2","A-1, B-4, C-2, D-3","A-4, B-1, C-2, D-3"],"answer":3,"explanation":"A ratoon crop grows from the stubble left after harvest, common in sugarcane; viticulture is grape growing, apiculture is bee-keeping and pisciculture is fish farming.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"शब्द का मिलान उससे संबंधित कार्य से कीजिए। A. रैटूनिंग  B. विटीकल्चर  C. एपीकल्चर  D. पिसीकल्चर; 1. अंगूर  2. मधुमक्खियाँ  3. मछली  4. पुरानी फसल के ठूँठ से नई फसल उगाना, जैसे गन्ने में","optionsHi":["A-4, B-2, C-1, D-3","A-4, B-1, C-3, D-2","A-1, B-4, C-2, D-3","A-4, B-1, C-2, D-3"],"explanationHi":"रैटून फसल कटाई के बाद बचे ठूँठ से उगती है, जो गन्ने में आम है; विटीकल्चर अंगूर की खेती है, एपीकल्चर मधुमक्खी पालन है और पिसीकल्चर मत्स्य पालन है।"},
  {"id":"geo-soils-agriculture-75","question":"Which pair of crop and its category is NOT correct?","options":["Jowar — coarse cereal","Masoor — pulse","Castor — non-edible oilseed","Mesta — beverage crop"],"answer":3,"explanation":"Mesta (kenaf) is a fibre crop grown like jute, not a beverage crop. Jowar is a coarse cereal (millet), masoor a rabi pulse and castor a non-edible oilseed.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"फसल और उसकी श्रेणी का कौन-सा युग्म सही नहीं है?","optionsHi":["ज्वार — मोटा अनाज","मसूर — दलहन","अरंडी — अखाद्य तिलहन","मेस्टा — पेय फसल"],"explanationHi":"मेस्टा (केनाफ) जूट की तरह उगाई जाने वाली रेशा फसल है, पेय फसल नहीं। ज्वार मोटा अनाज है, मसूर रबी दलहन है और अरंडी अखाद्य तिलहन है।"},
  {"id":"geo-soils-agriculture-76","question":"How many of the following statements about crop requirements are correct? I. Rice needs temperatures above 25 °C, high humidity and rainfall above about 100 cm. II. Maize grows well in old alluvial soil at temperatures of about 21–27 °C. III. Jute grows best on fertile flood-plain soils that are renewed every year. IV. Wheat needs a cool growing season and bright sunshine at the time of ripening.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Rice needs heat, humidity and heavy rain; maize suits old alluvium at 21–27 °C; jute prefers annually renewed flood-plain soils; and wheat, a rabi crop, needs a cool growing season and bright sun at ripening.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"फसलों की आवश्यकताओं के बारे में निम्नलिखित में से कितने कथन सही हैं? I. चावल को 25 °C से अधिक तापमान, उच्च आर्द्रता और लगभग 100 सेमी से अधिक वर्षा चाहिए। II. मक्का लगभग 21–27 °C तापमान पर पुरानी जलोढ़ मृदा में अच्छी उगती है। III. जूट प्रतिवर्ष नवीनीकृत होने वाली उपजाऊ बाढ़-मैदान की मृदाओं में सबसे अच्छा उगता है। IV. गेहूँ को ठंडा वृद्धि काल और पकते समय तेज़ धूप चाहिए।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। चावल को गर्मी, आर्द्रता और भारी वर्षा चाहिए; मक्का 21–27 °C पर पुरानी जलोढ़ मृदा के अनुकूल है; जूट प्रतिवर्ष नवीनीकृत बाढ़-मैदान की मृदाओं को पसंद करता है; और गेहूँ, एक रबी फसल, को ठंडा वृद्धि काल तथा पकते समय तेज़ धूप चाहिए।"},
  {"id":"geo-soils-agriculture-77","question":"Arrange in chronological order: 1. Approval of Bt cotton for commercial cultivation  2. Setting up of NABARD  3. Launch of PM-KISAN  4. Setting up of the (Imperial) Council of Agricultural Research, now ICAR","options":["4-2-1-3","2-4-1-3","4-1-2-3","4-2-3-1"],"answer":0,"explanation":"ICAR began as the Imperial Council of Agricultural Research in 1929, NABARD was set up in 1982, Bt cotton was approved in 2002 and PM-KISAN started in 2019.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"कालक्रमानुसार व्यवस्थित कीजिए: 1. बीटी कपास को व्यावसायिक खेती की मंज़ूरी  2. नाबार्ड (NABARD) की स्थापना  3. पीएम-किसान का शुभारंभ  4. (इंपीरियल) कृषि अनुसंधान परिषद की स्थापना, जो अब ICAR है","optionsHi":["4-2-1-3","2-4-1-3","4-1-2-3","4-2-3-1"],"explanationHi":"ICAR की शुरुआत 1929 में इंपीरियल कृषि अनुसंधान परिषद के रूप में हुई, नाबार्ड 1982 में स्थापित हुआ, बीटी कपास को 2002 में मंज़ूरी मिली और पीएम-किसान 2019 में शुरू हुआ।"},
  {"id":"geo-soils-agriculture-78","question":"How many of the following statements about Kuttanad are correct? I. It is a region of Kerala where farming is done below sea level. II. The FAO has recognised it as a Globally Important Agricultural Heritage System. III. Many of its soils are acidic and peaty. IV. It lies in the rain shadow of the Western Ghats and gets scanty rain.","options":["Only one","Only three","Only two","All four"],"answer":1,"explanation":"I, II and III are correct. Kuttanad, in the backwaters around Vembanad lake, gets heavy rain from the south-west monsoon, so IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"कुट्टनाड के बारे में निम्नलिखित में से कितने कथन सही हैं? I. यह केरल का वह क्षेत्र है जहाँ समुद्र तल से नीचे खेती की जाती है। II. FAO ने इसे विश्व के महत्वपूर्ण कृषि विरासत तंत्र के रूप में मान्यता दी है। III. इसकी कई मृदाएँ अम्लीय और पीट युक्त हैं। IV. यह पश्चिमी घाट की वृष्टि छाया में स्थित है और यहाँ कम वर्षा होती है।","optionsHi":["केवल एक","केवल तीन","केवल दो","सभी चार"],"explanationHi":"I, II और III सही हैं। वेम्बनाड झील के आसपास के पश्चाजल (बैकवाटर) क्षेत्र में स्थित कुट्टनाड में दक्षिण-पश्चिम मानसून से भारी वर्षा होती है, इसलिए IV गलत है।"},
  {"id":"geo-soils-agriculture-79","question":"Match the rice crop of West Bengal with its season. A. Aus  B. Aman  C. Boro; 1. Main winter rice, sown with the monsoon and harvested in November–December  2. Summer rice, sown in winter under irrigation and harvested in April–May  3. Autumn rice, sown in pre-monsoon showers and harvested in August–September","options":["A-1, B-3, C-2","A-3, B-1, C-2","A-3, B-2, C-1","A-2, B-1, C-3"],"answer":1,"explanation":"Aus is the autumn crop, Aman the main winter (kharif) crop and Boro the irrigated summer crop. Aman covers the largest area.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"पश्चिम बंगाल की चावल की फसल का उसके मौसम से मिलान कीजिए। A. ऑस  B. अमन  C. बोरो; 1. मुख्य शीतकालीन चावल, मानसून के साथ बोया जाता है और नवंबर–दिसंबर में काटा जाता है  2. ग्रीष्मकालीन चावल, सर्दियों में सिंचाई से बोया जाता है और अप्रैल–मई में काटा जाता है  3. शरदकालीन चावल, मानसून-पूर्व वर्षा में बोया जाता है और अगस्त–सितंबर में काटा जाता है","optionsHi":["A-1, B-3, C-2","A-3, B-1, C-2","A-3, B-2, C-1","A-2, B-1, C-3"],"explanationHi":"ऑस शरदकालीन फसल है, अमन मुख्य शीतकालीन (खरीफ) फसल है और बोरो सिंचित ग्रीष्मकालीन फसल है। अमन सबसे बड़े क्षेत्र में उगाई जाती है।"},
  {"id":"geo-soils-agriculture-80","question":"Assertion (A): Waterlogging and soil salinity have become serious problems in parts of canal-irrigated Punjab and Haryana. Reason (R): Over-irrigation raises the water table, and capillary action brings salts to the surface.","options":["A is true but R is false","Both A and R are true but R is not the correct explanation of A","Both A and R are true and R is the correct explanation of A","A is false but R is true"],"answer":2,"explanation":"Heavy canal irrigation without drainage raises the water table; as water evaporates, salts are left on the surface. So R explains A.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): पंजाब और हरियाणा के नहर-सिंचित भागों में जलभराव और मृदा लवणता गंभीर समस्याएँ बन गई हैं। कारण (R): अत्यधिक सिंचाई से भूजल स्तर ऊपर उठ जाता है और केशिका क्रिया लवणों को सतह पर ले आती है।","optionsHi":["A सत्य है, परंतु R असत्य है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A असत्य है, परंतु R सत्य है"],"explanationHi":"जल-निकासी के बिना भारी नहर सिंचाई से भूजल स्तर ऊपर उठता है; जैसे-जैसे पानी वाष्पित होता है, लवण सतह पर रह जाते हैं। अतः R, A की व्याख्या करता है।"},
  {"id":"geo-soils-agriculture-81","question":"Match the soil with the region where it is typically found. A. Laterite  B. Arid  C. Saline  D. Forest; 1. Western Rajasthan  2. Rann of Kutch  3. Summits of the Western and Eastern Ghats  4. Himalayan slopes","options":["A-3, B-1, C-2, D-4","A-3, B-2, C-1, D-4","A-4, B-1, C-2, D-3","A-3, B-1, C-4, D-2"],"answer":0,"explanation":"Laterites cap the Ghats summits, arid soils cover western Rajasthan, saline soils occur in the Rann of Kutch and coastal marshes, and forest soils develop on Himalayan slopes.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"मृदा का मिलान उस क्षेत्र से कीजिए जहाँ वह सामान्यतः पाई जाती है। A. लेटराइट  B. शुष्क  C. लवणीय  D. वन; 1. पश्चिमी राजस्थान  2. कच्छ का रण  3. पश्चिमी और पूर्वी घाट की चोटियाँ  4. हिमालय के ढाल","optionsHi":["A-3, B-1, C-2, D-4","A-3, B-2, C-1, D-4","A-4, B-1, C-2, D-3","A-3, B-1, C-4, D-2"],"explanationHi":"लेटराइट घाटों की चोटियों पर आच्छादित है, शुष्क मृदाएँ पश्चिमी राजस्थान में फैली हैं, लवणीय मृदाएँ कच्छ के रण और तटीय दलदलों में मिलती हैं, और वन मृदाएँ हिमालय के ढालों पर विकसित होती हैं।"},
  {"id":"geo-soils-agriculture-82","question":"Which pair of crop and the soil it is best suited to is NOT correct?","options":["Cotton — black soil","Tea — well-drained, slightly acidic hill soil","Jute — fertile alluvial delta soil","Rice — porous sandy desert soil"],"answer":3,"explanation":"Rice needs standing water, so it prefers clayey alluvial soils that hold water; porous desert sand drains too fast. The other pairs are correct.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"फसल और उसके लिए सबसे उपयुक्त मृदा का कौन-सा युग्म सही नहीं है?","optionsHi":["कपास — काली मृदा","चाय — अच्छी जल-निकासी वाली, हल्की अम्लीय पहाड़ी मृदा","जूट — उपजाऊ जलोढ़ डेल्टाई मृदा","चावल — रंध्रयुक्त रेतीली मरुस्थलीय मृदा"],"explanationHi":"चावल को खड़ा पानी चाहिए, इसलिए वह पानी रोकने वाली चिकनी जलोढ़ मृदाओं को पसंद करता है; रंध्रयुक्त मरुस्थलीय रेत से पानी बहुत तेज़ी से निकल जाता है। अन्य युग्म सही हैं।"},
  {"id":"geo-soils-agriculture-83","question":"How many of the following are rabi crops? I. Barley  II. Gram  III. Linseed  IV. Peas","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are sown in October–December and harvested in spring, so they are rabi crops.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"निम्नलिखित में से कितनी रबी फसलें हैं? I. जौ  II. चना  III. अलसी  IV. मटर","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों अक्टूबर–दिसंबर में बोई जाती हैं और वसंत में काटी जाती हैं, इसलिए ये रबी फसलें हैं।"},
  {"id":"geo-soils-agriculture-84","question":"How many of the following pulses are grown mainly as kharif crops? I. Arhar (tur)  II. Moong  III. Urad  IV. Moth","options":["Only three","Only two","Only one","All four"],"answer":3,"explanation":"All four are kharif pulses sown with the monsoon: arhar, moong, urad and moth (a drought-hardy pulse of Rajasthan). Rabi pulses include gram and masoor (lentil).","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"निम्नलिखित में से कितनी दलहनें मुख्यतः खरीफ फसलों के रूप में उगाई जाती हैं? I. अरहर (तूर)  II. मूँग  III. उड़द  IV. मोठ","optionsHi":["केवल तीन","केवल दो","केवल एक","सभी चार"],"explanationHi":"चारों खरीफ दलहनें हैं जो मानसून के साथ बोई जाती हैं: अरहर, मूँग, उड़द और मोठ (राजस्थान की सूखा-सहनशील दलहन)। रबी दलहनों में चना और मसूर शामिल हैं।"},
  {"id":"geo-soils-agriculture-85","question":"Match the research institute with its location. A. Indian Agricultural Research Institute  B. National Rice Research Institute  C. Central Potato Research Institute  D. Indian Institute of Sugarcane Research; 1. Shimla  2. Lucknow  3. New Delhi  4. Cuttack","options":["A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-2, B-4, C-1, D-3","A-3, B-4, C-2, D-1"],"answer":1,"explanation":"IARI (Pusa) is in New Delhi, NRRI (formerly CRRI) in Cuttack, CPRI in Shimla and IISR in Lucknow.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अनुसंधान संस्थान का मिलान उसके स्थान से कीजिए। A. भारतीय कृषि अनुसंधान संस्थान  B. राष्ट्रीय चावल अनुसंधान संस्थान  C. केंद्रीय आलू अनुसंधान संस्थान  D. भारतीय गन्ना अनुसंधान संस्थान; 1. शिमला  2. लखनऊ  3. नई दिल्ली  4. कटक","optionsHi":["A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-2, B-4, C-1, D-3","A-3, B-4, C-2, D-1"],"explanationHi":"IARI (पूसा) नई दिल्ली में, NRRI (पूर्व CRRI) कटक में, CPRI शिमला में और IISR लखनऊ में है।"},
  {"id":"geo-soils-agriculture-86","question":"Which crop is the staple food of most people in eastern and southern India?","options":["Rice","Wheat","Barley","Maize"],"answer":0,"explanation":"Rice, a kharif crop of hot, wet areas, is the main cereal of the east, the south and the coasts; wheat dominates in the drier north-west.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"पूर्वी और दक्षिणी भारत के अधिकांश लोगों का मुख्य भोजन कौन-सी फसल है?","optionsHi":["चावल","गेहूँ","जौ","मक्का"],"explanationHi":"चावल, गर्म और आर्द्र क्षेत्रों की खरीफ फसल, पूर्व, दक्षिण और तटीय क्षेत्रों का प्रमुख अनाज है; शुष्क उत्तर-पश्चिम में गेहूँ प्रमुख है।"},
  {"id":"geo-soils-agriculture-87","question":"Urea is applied to crops mainly to supply which nutrient?","options":["Phosphorus","Nitrogen","Potassium","Calcium"],"answer":1,"explanation":"Urea contains about 46% nitrogen, the nutrient most needed for leafy growth. DAP supplies phosphorus and muriate of potash supplies potassium.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"यूरिया फसलों में मुख्यतः किस पोषक तत्व की पूर्ति के लिए डाला जाता है?","optionsHi":["फॉस्फोरस","नाइट्रोजन","पोटैशियम","कैल्शियम"],"explanationHi":"यूरिया में लगभग 46% नाइट्रोजन होती है, जो पत्तेदार वृद्धि के लिए सबसे आवश्यक पोषक तत्व है। DAP फॉस्फोरस और म्यूरिएट ऑफ पोटाश पोटैशियम की आपूर्ति करता है।"},
  {"id":"geo-soils-agriculture-88","question":"The main benefit of crop rotation is that it:","options":["Lets the farmer use more chemical fertiliser","Keeps the soil permanently waterlogged","Maintains fertility and breaks pest cycles","Removes the need to plough the field every year"],"answer":2,"explanation":"Changing crops season to season, especially bringing in legumes, restores nitrogen and denies pests a constant host. Growing the same crop repeatedly drains the same nutrients.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"फसल चक्र का मुख्य लाभ यह है कि वह:","optionsHi":["किसान को अधिक रासायनिक उर्वरक प्रयोग करने देता है","मृदा को स्थायी रूप से जलमग्न रखता है","उर्वरता बनाए रखता है और कीटों का चक्र तोड़ता है","हर वर्ष खेत की जुताई की आवश्यकता समाप्त करता है"],"explanationHi":"मौसम-दर-मौसम फसलें बदलने से, विशेषकर दलहनी फसलें लाने से, नाइट्रोजन की पूर्ति होती है और कीटों को लगातार पोषी नहीं मिलता। एक ही फसल बार-बार उगाने से वही पोषक तत्व घटते रहते हैं।"},
  {"id":"geo-soils-agriculture-89","question":"Mulching in agriculture means:","options":["Spraying pesticides from the air on crops","Flooding a field before sowing the seed","Deep ploughing to bring up the subsoil","Covering soil with straw or plastic sheet"],"answer":3,"explanation":"A mulch layer cuts evaporation, keeps soil temperature even, suppresses weeds and reduces erosion by rain splash.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"कृषि में मल्चिंग (पलवार) का अर्थ है:","optionsHi":["फसलों पर हवा से कीटनाशकों का छिड़काव","बीज बोने से पहले खेत में पानी भर देना","अवमृदा को ऊपर लाने के लिए गहरी जुताई","मृदा को पुआल या प्लास्टिक की चादर से ढकना"],"explanationHi":"मल्च की परत वाष्पीकरण घटाती है, मृदा का तापमान समान रखती है, खरपतवार दबाती है और वर्षा की बूँदों से होने वाले अपरदन को कम करती है।"},
  {"id":"geo-soils-agriculture-90","question":"To correct a strongly acidic soil, farmers are generally advised to add:","options":["Lime","Gypsum","Common salt","Sulphur"],"answer":0,"explanation":"Lime (calcium carbonate) neutralises acidity and raises pH. Gypsum is used for alkaline (sodic) soils, and sulphur would make the soil more acidic.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"अत्यधिक अम्लीय मृदा के सुधार के लिए किसानों को सामान्यतः क्या मिलाने की सलाह दी जाती है?","optionsHi":["चूना","जिप्सम","साधारण नमक","सल्फर"],"explanationHi":"चूना (कैल्शियम कार्बोनेट) अम्लीयता को उदासीन करता है और pH बढ़ाता है। जिप्सम क्षारीय (सोडिक) मृदाओं के लिए प्रयुक्त होता है, और सल्फर मृदा को और अम्लीय बना देगा।"},
  {"id":"geo-soils-agriculture-91","question":"Agroforestry refers to:","options":["Clearing forests to grow crops on the land","Growing trees with crops or livestock together","Planting only fruit orchards on farm land","Growing crops inside reserved forest areas"],"answer":1,"explanation":"Agroforestry deliberately mixes trees with crops or pasture, giving timber, fodder and fruit while improving soil and microclimate. It is the opposite of clearing forest.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"कृषि-वानिकी (एग्रोफॉरेस्ट्री) का अर्थ है:","optionsHi":["भूमि पर फसल उगाने के लिए वनों को साफ़ करना","पेड़ों को फसलों या पशुधन के साथ एक साथ उगाना","खेती की भूमि पर केवल फलों के बाग लगाना","आरक्षित वन क्षेत्रों के भीतर फसलें उगाना"],"explanationHi":"कृषि-वानिकी में जानबूझकर पेड़ों को फसलों या चरागाह के साथ मिलाया जाता है, जिससे इमारती लकड़ी, चारा और फल मिलते हैं तथा मृदा और सूक्ष्म जलवायु में सुधार होता है। यह वन साफ़ करने के ठीक विपरीत है।"},
  {"id":"geo-soils-agriculture-92","question":"Azolla is grown in paddy fields as a biofertiliser because:","options":["It kills the stem borers of rice","It releases potassium from the rocks","Its partner Anabaena fixes nitrogen","It makes acidic paddy soil alkaline"],"answer":2,"explanation":"Azolla is a small floating fern that houses Anabaena azollae in its leaves; this partnership fixes nitrogen that becomes available to rice when the fern decomposes.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"अज़ोला को धान के खेतों में जैव-उर्वरक के रूप में इसलिए उगाया जाता है क्योंकि:","optionsHi":["यह चावल के तना छेदक कीटों को मारता है","यह चट्टानों से पोटैशियम मुक्त करता है","इसका सहजीवी एनाबीना नाइट्रोजन का स्थिरीकरण करता है","यह अम्लीय धान मृदा को क्षारीय बनाता है"],"explanationHi":"अज़ोला एक छोटी तैरने वाली फर्न है जिसकी पत्तियों में एनाबीना ऐज़ोली रहता है; यह साझेदारी नाइट्रोजन का स्थिरीकरण करती है, जो फर्न के सड़ने पर चावल को उपलब्ध हो जाती है।"},
  {"id":"geo-soils-agriculture-93","question":"Which of these crops uses the C4 pathway of photosynthesis, which suits hot, sunny conditions?","options":["Wheat","Rice","Gram","Maize"],"answer":3,"explanation":"Maize, sugarcane, sorghum and pearl millet are C4 plants that fix carbon efficiently in heat and strong light with less water loss. Wheat, rice and gram are C3 crops.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"इनमें से कौन-सी फसल प्रकाश संश्लेषण के C4 पथ का उपयोग करती है, जो गर्म, धूप वाली परिस्थितियों के अनुकूल है?","optionsHi":["गेहूँ","चावल","चना","मक्का"],"explanationHi":"मक्का, गन्ना, ज्वार और बाजरा C4 पौधे हैं जो गर्मी और तेज़ प्रकाश में कम जल-हानि के साथ कार्बन का कुशलता से स्थिरीकरण करते हैं। गेहूँ, चावल और चना C3 फसलें हैं।"},
  {"id":"geo-soils-agriculture-94","question":"“Fertigation” means:","options":["Supplying fertiliser through irrigation water","Spraying fertiliser from drones only","Burning crop residue to add ash to the soil","Using fertiliser made from fish waste"],"answer":0,"explanation":"In fertigation, dissolved fertilisers are fed into the drip or sprinkler line so they reach the root zone in small, timed doses, saving both water and nutrients.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"“फर्टिगेशन” का अर्थ है:","optionsHi":["सिंचाई के जल के माध्यम से उर्वरक देना","केवल ड्रोन से उर्वरक का छिड़काव करना","मृदा में राख मिलाने के लिए फसल अवशेष जलाना","मछली के अपशिष्ट से बने उर्वरक का उपयोग करना"],"explanationHi":"फर्टिगेशन में घुले हुए उर्वरक ड्रिप या स्प्रिंकलर की लाइन में डाले जाते हैं, ताकि वे जड़ क्षेत्र तक छोटी, समयबद्ध मात्रा में पहुँचें, जिससे जल और पोषक तत्व दोनों की बचत होती है।"},
  {"id":"geo-soils-agriculture-95","question":"Hydroponics is a method of:","options":["Growing plants in flooded fields only","Growing plants in nutrient solution, no soil","Irrigating crops using desalinated sea water","Breeding fish in flooded paddy fields"],"answer":1,"explanation":"In hydroponics roots sit in a nutrient solution or inert medium instead of soil. Raising fish in paddy fields is rice–fish culture, a different practice.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"हाइड्रोपोनिक्स (जलकृषि) किसकी एक विधि है?","optionsHi":["केवल जलमग्न खेतों में पौधे उगाने की","मृदा के बिना, पोषक विलयन में पौधे उगाने की","विलवणीकृत समुद्री जल से फसलों की सिंचाई की","जलमग्न धान के खेतों में मछली पालन की"],"explanationHi":"हाइड्रोपोनिक्स में जड़ें मृदा के स्थान पर पोषक विलयन या अक्रिय माध्यम में रहती हैं। धान के खेतों में मछली पालन चावल–मत्स्य संवर्धन है, जो एक अलग पद्धति है।"},
  {"id":"geo-soils-agriculture-96","question":"The “Happy Seeder” machine promoted in Punjab and Haryana helps farmers to:","options":["Harvest wheat and rice in one pass","Spray pesticides at night with drones","Drill wheat into rice stubble without burning","Transplant rice seedlings by machine"],"answer":2,"explanation":"The Happy Seeder cuts and lifts the paddy straw and drills wheat seed into the soil in one pass, so the straw becomes mulch instead of being burnt, which feeds north India's winter smog.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"पंजाब और हरियाणा में प्रोत्साहित की गई “हैप्पी सीडर” मशीन किसानों की किस प्रकार सहायता करती है?","optionsHi":["गेहूँ और चावल की एक ही बार में कटाई करने में","रात में ड्रोन से कीटनाशकों का छिड़काव करने में","पराली जलाए बिना धान के ठूँठ में गेहूँ की बुआई करने में","मशीन से धान की पौध रोपने में"],"explanationHi":"हैप्पी सीडर धान की पराली को काटकर ऊपर उठाता है और एक ही बार में मृदा में गेहूँ का बीज बो देता है, जिससे पराली जलाने की जगह पलवार बन जाती है; पराली जलाना उत्तर भारत के शीतकालीन स्मॉग का कारण बनता है।"},
  {"id":"geo-soils-agriculture-97","question":"The System of Rice Intensification (SRI) involves:","options":["Keeping fields flooded and planting old seedlings in clumps","Sowing rice only by broadcasting dry seed on the field","Growing rice only in the rabi season under irrigation","Young single seedlings, wide spacing, wet-dry cycles"],"answer":3,"explanation":"SRI uses fewer, younger seedlings, wider spacing and intermittent irrigation instead of standing water, which saves water and seed and often raises yields.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"श्री (SRI) पद्धति, यानी धान सघनीकरण प्रणाली, में क्या शामिल है?","optionsHi":["खेतों में पानी भरे रखना और पुरानी पौध को गुच्छों में रोपना","चावल को केवल सूखा बीज छिटककर बोना","चावल केवल रबी मौसम में सिंचाई से उगाना","कम उम्र की एकल पौध, चौड़ी दूरी, गीले-सूखे चक्र"],"explanationHi":"SRI में खड़े पानी के स्थान पर कम, कम उम्र की पौध, चौड़ी दूरी और रुक-रुककर सिंचाई का प्रयोग होता है, जिससे जल और बीज की बचत होती है तथा उपज प्रायः बढ़ती है।"},
  {"id":"geo-soils-agriculture-98","question":"“Golden Rice” has been genetically engineered to contain:","options":["Beta-carotene, a precursor of vitamin A","Extra iron and zinc","A gene for pest resistance from Bacillus thuringiensis","Higher gluten"],"answer":0,"explanation":"Golden Rice makes beta-carotene in its grain, which gives it a yellow colour and is meant to fight vitamin A deficiency. The Bt gene is used in Bt cotton for pest resistance.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"“गोल्डन राइस” को आनुवंशिक रूप से किसे धारण करने के लिए रूपांतरित किया गया है?","optionsHi":["बीटा-कैरोटीन, जो विटामिन A का पूर्वगामी है","अतिरिक्त आयरन और जिंक","बैसिलस थुरिंजिएंसिस से कीट-प्रतिरोध का जीन","अधिक ग्लूटेन"],"explanationHi":"गोल्डन राइस अपने दाने में बीटा-कैरोटीन बनाता है, जो उसे पीला रंग देता है और विटामिन A की कमी से लड़ने के लिए है। कीट-प्रतिरोध के लिए Bt जीन का उपयोग बीटी कपास में होता है।"},
  {"id":"geo-soils-agriculture-99","question":"How many of these statements about a soil profile are correct? I. The A horizon is the topsoil, rich in humus and biological activity. II. The B horizon is the subsoil, where minerals washed down from above accumulate. III. The C horizon is the solid, unweathered bedrock. IV. The organic O horizon lies below the bedrock.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct. The C horizon is weathered parent material; solid bedrock is the R layer at the bottom. The O horizon of leaf litter lies at the very top, above the A horizon, so III and IV are wrong.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"मृदा परिच्छेदिका (सॉइल प्रोफ़ाइल) के बारे में इनमें से कितने कथन सही हैं? I. A संस्तर ऊपरी मृदा है, जो ह्यूमस और जैविक गतिविधि से समृद्ध होती है। II. B संस्तर अवमृदा है, जहाँ ऊपर से धुलकर आए खनिज जमा होते हैं। III. C संस्तर ठोस, अपक्षयित न हुई आधारशैल है। IV. जैविक O संस्तर आधारशैल के नीचे स्थित होता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II सही हैं। C संस्तर अपक्षयित मूल पदार्थ है; ठोस आधारशैल सबसे नीचे की R परत है। पत्तियों के कचरे वाला O संस्तर सबसे ऊपर, A संस्तर के ऊपर स्थित होता है, इसलिए III और IV गलत हैं।"},
  {"id":"geo-soils-agriculture-100","question":"Match the term with what it deals with. A. Sericulture  B. Olericulture  C. Floriculture  D. Pomology; 1. Vegetables  2. Rearing silkworms  3. Fruits  4. Flowers","options":["A-2, B-1, C-4, D-3","A-1, B-2, C-4, D-3","A-2, B-3, C-4, D-1","A-2, B-1, C-3, D-4"],"answer":0,"explanation":"Sericulture is silk farming, olericulture the growing of vegetables, floriculture of flowers and pomology the science of fruit growing. Olericulture is the usual trap.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"शब्द का मिलान उसके विषय से कीजिए। A. सेरीकल्चर  B. ओलेरीकल्चर  C. फ्लोरीकल्चर  D. पोमोलॉजी; 1. सब्जियाँ  2. रेशम कीट पालन  3. फल  4. फूल","optionsHi":["A-2, B-1, C-4, D-3","A-1, B-2, C-4, D-3","A-2, B-3, C-4, D-1","A-2, B-1, C-3, D-4"],"explanationHi":"सेरीकल्चर रेशम की खेती है, ओलेरीकल्चर सब्जियाँ उगाना, फ्लोरीकल्चर फूलों की खेती और पोमोलॉजी फल उगाने का विज्ञान है। ओलेरीकल्चर प्रायः भ्रम का कारण बनता है।"},
  {"id":"geo-soils-agriculture-101","question":"How many of these statements about neem-coated urea are correct? I. The neem coating slows the release of nitrogen into the soil. II. It discourages the diversion of subsidised urea to industrial uses. III. In 2015 the government made neem coating mandatory for all domestically produced urea. IV. Urea itself contains about 46% nitrogen.","options":["Only one","Only two","All four","Only three"],"answer":2,"explanation":"All four are correct. The neem coating acts as a nitrification inhibitor and makes urea unfit for industrial use, it was made mandatory in 2015, and urea carries about 46% nitrogen, the highest of common solid fertilisers.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"नीम-लेपित यूरिया के बारे में इनमें से कितने कथन सही हैं? I. नीम का लेप मृदा में नाइट्रोजन के निकलने की गति को धीमा करता है। II. यह अनुदानित यूरिया के औद्योगिक उपयोग में विपथन को हतोत्साहित करता है। III. 2015 में सरकार ने सभी घरेलू रूप से उत्पादित यूरिया के लिए नीम-लेपन अनिवार्य कर दिया। IV. यूरिया में स्वयं लगभग 46% नाइट्रोजन होती है।","optionsHi":["केवल एक","केवल दो","सभी चार","केवल तीन"],"explanationHi":"चारों सही हैं। नीम का लेप नाइट्रीकरण संदमक का काम करता है और यूरिया को औद्योगिक उपयोग के अनुपयुक्त बना देता है, इसे 2015 में अनिवार्य किया गया, और यूरिया में लगभग 46% नाइट्रोजन होती है, जो सामान्य ठोस उर्वरकों में सबसे अधिक है।"},
  {"id":"geo-soils-agriculture-102","question":"Arrange these soil particles in increasing order of size: 1. Sand  2. Clay  3. Gravel  4. Silt","options":["4-2-1-3","2-1-4-3","2-4-1-3","2-4-3-1"],"answer":2,"explanation":"Clay particles are under 0.002 mm, silt 0.002–0.05 mm, sand 0.05–2 mm and gravel coarser still. Fine clay holds water and nutrients; sand drains fast.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"इन मृदा कणों को आकार के बढ़ते क्रम में व्यवस्थित कीजिए: 1. रेत  2. चिकनी मिट्टी (क्ले)  3. बजरी  4. गाद (सिल्ट)","optionsHi":["4-2-1-3","2-1-4-3","2-4-1-3","2-4-3-1"],"explanationHi":"चिकनी मिट्टी के कण 0.002 मिमी से छोटे, गाद के 0.002–0.05 मिमी, रेत के 0.05–2 मिमी और बजरी के उससे भी मोटे होते हैं। महीन चिकनी मिट्टी जल और पोषक तत्वों को रोकती है; रेत से जल तेज़ी से निकल जाता है।"},
  {"id":"geo-soils-agriculture-103","question":"How many of these statements about millets are correct? I. Most millets tolerate drought and poor soils. II. Ragi (finger millet) is especially rich in calcium. III. Jowar and bajra are C4 crops. IV. Bajra is grown mainly on the sandy soils of Rajasthan, its largest producer.","options":["Only one","Only three","Only two","All four"],"answer":3,"explanation":"All four are correct. Millets are hardy C4 crops suited to rain-fed dryland farming, ragi is notably rich in calcium, and bajra grows well on sandy soils, with Rajasthan the leading producer.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"मोटे अनाजों (मिलेट) के बारे में इनमें से कितने कथन सही हैं? I. अधिकांश मोटे अनाज सूखा और निर्धन मृदाएँ सहन कर लेते हैं। II. रागी (फिंगर मिलेट) विशेष रूप से कैल्शियम में समृद्ध है। III. ज्वार और बाजरा C4 फसलें हैं। IV. बाजरा मुख्यतः राजस्थान की रेतीली मृदाओं में उगाया जाता है, जो उसका सबसे बड़ा उत्पादक है।","optionsHi":["केवल एक","केवल तीन","केवल दो","सभी चार"],"explanationHi":"चारों सही हैं। मोटे अनाज सहनशील C4 फसलें हैं जो वर्षा-आधारित शुष्क भूमि कृषि के अनुकूल हैं, रागी विशेष रूप से कैल्शियम में समृद्ध है, और बाजरा रेतीली मृदाओं में अच्छा उगता है, जिसमें राजस्थान अग्रणी उत्पादक है।"},
  {"id":"geo-soils-agriculture-104","question":"Match the soil problem with the usual remedy. A. Alkaline (sodic) soil  B. Acidic soil  C. Sheet erosion on gentle slopes  D. Wind erosion in dry areas; 1. Shelter belts of trees  2. Lime  3. Gypsum  4. Contour bunding","options":["A-3, B-2, C-1, D-4","A-2, B-3, C-4, D-1","A-3, B-4, C-2, D-1","A-3, B-2, C-4, D-1"],"answer":3,"explanation":"Gypsum replaces sodium in sodic soils; lime neutralises acidity; contour bunds slow water running down slopes; rows of trees break wind speed over open dry land.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"मृदा समस्या का उसके सामान्य उपाय से मिलान कीजिए। A. क्षारीय (सोडिक) मृदा  B. अम्लीय मृदा  C. मंद ढालों पर परत अपरदन  D. शुष्क क्षेत्रों में पवन अपरदन; 1. वृक्षों की रक्षक पट्टियाँ  2. चूना  3. जिप्सम  4. समोच्च बाँध","optionsHi":["A-3, B-2, C-1, D-4","A-2, B-3, C-4, D-1","A-3, B-4, C-2, D-1","A-3, B-2, C-4, D-1"],"explanationHi":"जिप्सम सोडिक मृदाओं में सोडियम का स्थान लेता है; चूना अम्लीयता को उदासीन करता है; समोच्च बाँध ढालों पर बहते जल को धीमा करते हैं; वृक्षों की पंक्तियाँ खुली शुष्क भूमि पर पवन की गति को तोड़ती हैं।"},
  {"id":"geo-soils-agriculture-105","question":"Assertion (A): The groundwater table has fallen sharply in much of central Punjab. Reason (R): Paddy grown in the hot summer months is irrigated largely by tube-wells, helped by cheap or free farm power.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Water-hungry paddy in a low-rainfall state, pumped from tube-wells with subsidised power, draws out far more groundwater than is recharged. Punjab's law delaying paddy transplanting to mid-June was a response.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): मध्य पंजाब के अधिकांश भाग में भूजल स्तर तेज़ी से गिर गया है। कारण (R): गर्मी के महीनों में उगाए जाने वाले धान की सिंचाई मुख्यतः नलकूपों से होती है, जिसे सस्ती या मुफ्त कृषि बिजली से सहायता मिलती है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"कम वर्षा वाले राज्य में जल-प्रधान धान को अनुदानित बिजली से नलकूपों द्वारा सींचने पर भूजल पुनर्भरण से कहीं अधिक निकाला जाता है। धान की रोपाई जून के मध्य तक टालने वाला पंजाब का कानून इसी की प्रतिक्रिया थी।"},
  {"id":"geo-soils-agriculture-106","question":"How many of these statements about Integrated Pest Management (IPM) are correct? I. It combines biological, cultural, mechanical and need-based chemical methods. II. It uses tools such as pheromone traps to monitor pests. III. Its aim is to wipe out every pest from the field. IV. It encourages natural enemies such as ladybird beetles.","options":["Only three","Only one","Only two","All four"],"answer":0,"explanation":"I, II and IV are correct. IPM aims to keep pests below the economic threshold level, not to exterminate them; total eradication would need heavy spraying that IPM tries to avoid, so III is wrong.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"समेकित कीट प्रबंधन (IPM) के बारे में इनमें से कितने कथन सही हैं? I. यह जैविक, सांस्कृतिक, यांत्रिक और आवश्यकता-आधारित रासायनिक विधियों को जोड़ता है। II. यह कीटों की निगरानी के लिए फेरोमोन ट्रैप जैसे उपकरणों का उपयोग करता है। III. इसका उद्देश्य खेत से हर कीट को समाप्त करना है। IV. यह लेडीबर्ड बीटल जैसे प्राकृतिक शत्रुओं को प्रोत्साहित करता है।","optionsHi":["केवल तीन","केवल एक","केवल दो","सभी चार"],"explanationHi":"I, II और IV सही हैं। IPM का लक्ष्य कीटों को आर्थिक देहली स्तर से नीचे रखना है, उनका उन्मूलन करना नहीं; पूर्ण उन्मूलन के लिए भारी छिड़काव चाहिए जिससे IPM बचना चाहता है, इसलिए III गलत है।"},
  {"id":"geo-soils-agriculture-107","question":"How many of these statements about the arid soils of western Rajasthan are correct? I. They are sandy, and saline in some areas. II. They are poor in humus and nitrogen, while their phosphate content is normal. III. Their lower horizons often contain kankar layers, because calcium content increases downward, and these restrict infiltration. IV. With irrigation, as in the Indira Gandhi Canal command area, they can be made productive.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Low rainfall and high evaporation leave salts and calcium in the profile; once water is supplied, crops such as wheat and mustard do well, as the canal tracts show.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"पश्चिमी राजस्थान की शुष्क मृदाओं के बारे में इनमें से कितने कथन सही हैं? I. वे रेतीली हैं और कुछ क्षेत्रों में लवणीय हैं। II. वे ह्यूमस और नाइट्रोजन में निर्धन हैं, जबकि उनमें फॉस्फेट की मात्रा सामान्य है। III. उनके निचले संस्तरों में प्रायः कंकड़ की परतें होती हैं, क्योंकि कैल्शियम की मात्रा नीचे की ओर बढ़ती है, और ये जल-अंतःस्रवण को रोकती हैं। IV. सिंचाई के साथ, जैसे इंदिरा गांधी नहर कमान क्षेत्र में, उन्हें उत्पादक बनाया जा सकता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। कम वर्षा और अधिक वाष्पीकरण के कारण लवण और कैल्शियम परिच्छेदिका में रह जाते हैं; जल उपलब्ध होने पर गेहूँ और सरसों जैसी फसलें अच्छी होती हैं, जैसा नहर क्षेत्र दिखाते हैं।"},
  {"id":"geo-soils-agriculture-108","question":"How many of these statements about laterite soils are correct? I. The name comes from the Latin word 'later', meaning red. II. They form where heavy rain and high temperature leach away iron and aluminium, leaving silica and lime. III. They are naturally rich in nitrogen, phosphorus and potash. IV. Blocks cut from them harden on exposure to air and are used for building.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only IV is correct. 'Later' means brick, not red; leaching removes silica and lime and leaves oxides of iron and aluminium (not the reverse); and laterites are poor in nitrogen, phosphorus and potash.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"लेटराइट मृदाओं के बारे में इनमें से कितने कथन सही हैं? I. इसका नाम लैटिन शब्द ‘later’ से आया है, जिसका अर्थ लाल है। II. ये वहाँ बनती हैं जहाँ भारी वर्षा और उच्च तापमान आयरन और ऐलुमिनियम को बहा ले जाते हैं, और सिलिका तथा चूना शेष रह जाते हैं। III. ये स्वाभाविक रूप से नाइट्रोजन, फॉस्फोरस और पोटाश में समृद्ध होती हैं। IV. इनसे काटे गए खंड हवा के संपर्क में कठोर हो जाते हैं और निर्माण में प्रयुक्त होते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल IV सही है। ‘Later’ का अर्थ ईंट है, लाल नहीं; निक्षालन सिलिका और चूने को हटा देता है और आयरन तथा ऐलुमिनियम के ऑक्साइड शेष रखता है (उलटा नहीं); और लेटराइट नाइट्रोजन, फॉस्फोरस और पोटाश में निर्धन होती हैं।"},
  {"id":"geo-soils-agriculture-109","question":"Consider the following statements: I. Sesamum (til) is a kharif crop in north India but a rabi crop in the south. II. Castor is grown both as a kharif and as a rabi crop. III. In some states such as Bihar, maize is also grown in the rabi season. IV. Mustard is mainly a kharif oilseed. Which of the statements given above are correct?","options":["I and II only","I, II and III only","II and III only","I, II, III and IV"],"answer":1,"explanation":"I, II and III follow NCERT. Rapeseed–mustard is a rabi oilseed of the northern plains, so IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: I. तिल उत्तर भारत में खरीफ फसल है, परंतु दक्षिण में रबी फसल है। II. अरंडी खरीफ और रबी दोनों फसल के रूप में उगाई जाती है। III. बिहार जैसे कुछ राज्यों में मक्का रबी मौसम में भी उगाई जाती है। IV. सरसों मुख्यतः खरीफ की तिलहन है। ऊपर दिए गए कथनों में से कौन-से सही हैं?","optionsHi":["केवल I और II","केवल I, II और III","केवल II और III","I, II, III और IV"],"explanationHi":"I, II और III NCERT के अनुरूप हैं। राई-सरसों उत्तरी मैदानों की रबी तिलहन है, इसलिए IV गलत है।"},
  {"id":"geo-soils-agriculture-110","question":"A district has a net sown area of 150 thousand hectares, of which 60 thousand hectares are sown more than once in the year. Its cropping intensity is:","options":["140%","40%","71.4%","210%"],"answer":0,"explanation":"Gross cropped area = 150 + 60 = 210 thousand ha; cropping intensity = GCA ÷ NSA × 100 = 210/150 × 100 = 140%. 40% is only the share sown more than once, and 71.4% inverts the ratio.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"किसी जिले का शुद्ध बोया गया क्षेत्र 150 हज़ार हेक्टेयर है, जिसमें से 60 हज़ार हेक्टेयर वर्ष में एक से अधिक बार बोया जाता है। उसकी फसल गहनता है:","optionsHi":["140%","40%","71.4%","210%"],"explanationHi":"सकल फसली क्षेत्र = 150 + 60 = 210 हज़ार हेक्टेयर; फसल गहनता = GCA ÷ NSA × 100 = 210/150 × 100 = 140%। 40% केवल एक से अधिक बार बोए गए क्षेत्र का अंश है, और 71.4% अनुपात को उलट देता है।"},
  {"id":"geo-soils-agriculture-111","question":"In India's nine-fold land-use classification, land left uncultivated for more than one year but less than five years is recorded as:","options":["current fallow","fallow other than current fallow","culturable waste land","land under miscellaneous tree crops"],"answer":1,"explanation":"Current fallow is land left uncultivated for one agricultural year or less; one to five years makes it 'fallow other than current fallow'; beyond five years it becomes culturable waste land.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भारत के नौ-स्तरीय भूमि-उपयोग वर्गीकरण में, एक वर्ष से अधिक परंतु पाँच वर्ष से कम समय तक बिना जोती छोड़ी गई भूमि को क्या दर्ज किया जाता है?","optionsHi":["चालू परती","चालू परती के अतिरिक्त परती","कृषि योग्य बंजर भूमि","विविध वृक्ष फसलों के अंतर्गत भूमि"],"explanationHi":"चालू परती वह भूमि है जो एक कृषि वर्ष या उससे कम समय के लिए बिना जोती छोड़ी गई हो; एक से पाँच वर्ष होने पर वह ‘चालू परती के अतिरिक्त परती’ कहलाती है; पाँच वर्ष से अधिक होने पर वह कृषि योग्य बंजर भूमि बन जाती है।"},
  {"id":"geo-soils-agriculture-112","question":"Match the local name of shifting cultivation with its region. A. Pamlou  B. Dipa  C. Bewar (Dahiya)  D. Kumari; 1. Western Ghats  2. Manipur  3. Madhya Pradesh  4. Bastar (Chhattisgarh) and the Andaman and Nicobar Islands","options":["A-2, B-4, C-3, D-1","A-4, B-2, C-3, D-1","A-2, B-3, C-4, D-1","A-2, B-4, C-1, D-3"],"answer":0,"explanation":"NCERT lists Pamlou in Manipur, Dipa in Bastar and the Andamans, Bewar or Dahiya in Madhya Pradesh and Kumari in the Western Ghats, alongside Jhum in the north-east and Podu in Andhra Pradesh.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"स्थानांतरित कृषि के स्थानीय नाम का उसके क्षेत्र से मिलान कीजिए। A. पामलू  B. दीपा  C. बेवर (दहिया)  D. कुमारी; 1. पश्चिमी घाट  2. मणिपुर  3. मध्य प्रदेश  4. बस्तर (छत्तीसगढ़) तथा अंडमान और निकोबार द्वीपसमूह","optionsHi":["A-2, B-4, C-3, D-1","A-4, B-2, C-3, D-1","A-2, B-3, C-4, D-1","A-2, B-4, C-1, D-3"],"explanationHi":"NCERT पामलू को मणिपुर में, दीपा को बस्तर और अंडमान में, बेवर या दहिया को मध्य प्रदेश में और कुमारी को पश्चिमी घाट में सूचीबद्ध करता है, साथ ही उत्तर-पूर्व में झूम और आंध्र प्रदेश में पोडू।"},
  {"id":"geo-soils-agriculture-113","question":"The NPK ratio of 4:2:1, often cited as the desirable norm for fertiliser use in India, refers to the proportion of:","options":["nitrogen, P₂O₅ and K₂O applied as nutrients","nitrogen, potassium and phosphorus, in that order","urea, DAP and gypsum by weight of fertiliser","nitrogen, phosphorus and sulphur as elements"],"answer":0,"explanation":"The norm is about nutrient balance: four parts N to two of P₂O₅ to one of K₂O. Cheap, heavily subsidised urea has pushed actual use far towards nitrogen, damaging soil health.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"भारत में उर्वरक उपयोग के वांछित मानक के रूप में प्रायः उद्धृत 4:2:1 का NPK अनुपात किसके अनुपात को दर्शाता है?","optionsHi":["पोषक तत्वों के रूप में प्रयुक्त नाइट्रोजन, P₂O₅ और K₂O","क्रमशः नाइट्रोजन, पोटैशियम और फॉस्फोरस","उर्वरक के भार के अनुसार यूरिया, DAP और जिप्सम","तत्वों के रूप में नाइट्रोजन, फॉस्फोरस और सल्फर"],"explanationHi":"यह मानक पोषक तत्वों के संतुलन के बारे में है: चार भाग N, दो भाग P₂O₅ और एक भाग K₂O। सस्ते, भारी अनुदान वाले यूरिया ने वास्तविक उपयोग को नाइट्रोजन की ओर बहुत झुका दिया है, जिससे मृदा स्वास्थ्य बिगड़ा है।"},
  {"id":"geo-soils-agriculture-114","question":"Match the biofertiliser with its role. A. Rhizobium  B. Azotobacter  C. Mycorrhiza (VAM fungi)  D. Blue-green algae such as Anabaena; 1. Free-living nitrogen fixer in the soil  2. Fungus that helps roots absorb phosphorus  3. Nitrogen fixer in the root nodules of legumes  4. Nitrogen fixer in flooded paddy fields","options":["A-1, B-3, C-2, D-4","A-3, B-1, C-4, D-2","A-3, B-2, C-1, D-4","A-3, B-1, C-2, D-4"],"answer":3,"explanation":"Rhizobium works only in symbiosis with legumes, Azotobacter fixes nitrogen on its own, mycorrhizal fungi extend the root system for phosphorus uptake, and cyanobacteria thrive in standing water of paddies.","difficulty":"hard","source":"SSC CGL Tier 2","questionHi":"जैव-उर्वरक का उसकी भूमिका से मिलान कीजिए। A. राइज़ोबियम  B. एज़ोटोबैक्टर  C. माइकोराइज़ा (VAM कवक)  D. एनाबीना जैसी नील-हरित शैवाल; 1. मृदा में स्वतंत्र रूप से रहने वाला नाइट्रोजन स्थिरीकारक  2. वह कवक जो जड़ों को फॉस्फोरस अवशोषित करने में सहायता करता है  3. दलहनी फसलों की जड़ों की गाँठों में नाइट्रोजन स्थिरीकारक  4. जलमग्न धान के खेतों में नाइट्रोजन स्थिरीकारक","optionsHi":["A-1, B-3, C-2, D-4","A-3, B-1, C-4, D-2","A-3, B-2, C-1, D-4","A-3, B-1, C-2, D-4"],"explanationHi":"राइज़ोबियम केवल दलहनों के साथ सहजीवन में कार्य करता है, एज़ोटोबैक्टर स्वयं नाइट्रोजन स्थिर करता है, माइकोराइज़ा कवक फॉस्फोरस के अवशोषण के लिए जड़ तंत्र को बढ़ाते हैं, और सायनोबैक्टीरिया धान के खेतों के खड़े पानी में पनपते हैं।"},
  {"id":"geo-soils-agriculture-115","question":"Assertion (A): The same parent rock can give rise to quite different soils in different parts of India. Reason (R): Climate, through temperature and rainfall, strongly controls the weathering and leaching that form soils.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Granite and gneiss weather into red soils in drier areas but laterite where heavy rain leaches them; climate often overrides parent material, which is why NCERT treats it as a key soil-forming factor.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): एक ही मूल चट्टान से भारत के विभिन्न भागों में बिल्कुल भिन्न मृदाएँ बन सकती हैं। कारण (R): जलवायु, तापमान और वर्षा के माध्यम से, मृदा बनाने वाले अपक्षय और निक्षालन को प्रबल रूप से नियंत्रित करती है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"ग्रेनाइट और नाइस शुष्क क्षेत्रों में लाल मृदा में अपक्षयित होते हैं, पर जहाँ भारी वर्षा उनका निक्षालन करती है वहाँ लेटराइट बनती है; जलवायु प्रायः मूल पदार्थ पर हावी रहती है, इसीलिए NCERT इसे मृदा-निर्माण का प्रमुख कारक मानता है।"},
  {"id":"geo-soils-agriculture-116","question":"Black pepper, called the 'King of Spices', and small cardamom, the 'Queen of Spices', are both grown mainly in:","options":["the Brahmaputra valley of Assam","the Malwa plateau of Madhya Pradesh","the Western Ghats of Kerala and Karnataka","the Ganga delta of West Bengal"],"answer":2,"explanation":"Both need a warm, humid climate, heavy rain and shade on well-drained hill slopes, conditions found in the Western Ghats, including the Cardamom Hills of Kerala.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"काली मिर्च, जिसे ‘मसालों का राजा’ कहा जाता है, और छोटी इलायची, जिसे ‘मसालों की रानी’ कहा जाता है, दोनों मुख्यतः कहाँ उगाई जाती हैं?","optionsHi":["असम की ब्रह्मपुत्र घाटी में","मध्य प्रदेश के मालवा पठार में","केरल और कर्नाटक के पश्चिमी घाट में","पश्चिम बंगाल के गंगा डेल्टा में"],"explanationHi":"दोनों को गर्म, आर्द्र जलवायु, भारी वर्षा और अच्छी जल-निकासी वाले पहाड़ी ढालों पर छाया चाहिए, जो पश्चिमी घाट में मिलती हैं, जिसमें केरल की इलायची की पहाड़ियाँ (कार्डमम हिल्स) भी शामिल हैं।"},
  {"id":"geo-soils-agriculture-117","question":"Zero Budget Natural Farming, promoted by Subhash Palekar and adopted at scale by Andhra Pradesh, relies chiefly on:","options":["certified organic fertilisers bought from the market","on-farm Jeevamrutha, mulching and no bought inputs","hydroponic cultivation of crops without any soil","genetically modified seeds that need no fertiliser"],"answer":1,"explanation":"'Zero budget' means farmers buy no external inputs; on-farm microbial preparations, mulch and moisture management replace fertilisers and pesticides. Buying organic inputs from the market defeats the idea.","difficulty":"hard","source":"UPSC Prelims","questionHi":"जीरो बजट प्राकृतिक खेती, जिसे सुभाष पालेकर ने बढ़ावा दिया और आंध्र प्रदेश ने बड़े पैमाने पर अपनाया, मुख्यतः किस पर निर्भर है?","optionsHi":["बाज़ार से खरीदे गए प्रमाणित जैविक उर्वरकों पर","खेत पर बने जीवामृत, मल्चिंग पर और बिना खरीदे आदानों पर","बिना मृदा के फसलों की हाइड्रोपोनिक खेती पर","आनुवंशिक रूप से संवर्धित बीजों पर जिन्हें उर्वरक नहीं चाहिए"],"explanationHi":"‘जीरो बजट’ का अर्थ है कि किसान कोई बाहरी आदान नहीं खरीदते; खेत पर बने सूक्ष्मजैविक मिश्रण, मल्च और नमी प्रबंधन उर्वरकों और कीटनाशकों का स्थान लेते हैं। बाज़ार से जैविक आदान खरीदना इस विचार के विपरीत है।"},
  {"id":"geo-soils-agriculture-118","question":"Which statement correctly distinguishes intercropping from mixed cropping?","options":["Intercropping grows crops one after another in a year; mixed cropping grows them together","Intercropping combines crops with livestock, while mixed cropping uses crops alone","Intercropping is practised only on plantations, mixed cropping only on small farms","Intercropping sows crops in set rows; mixed cropping sows a mixture of their seeds"],"answer":3,"explanation":"Both grow crops together, but intercropping keeps them in set rows (for example soybean with maize), making separate fertilising and harvesting easy. Crops in succession is multiple cropping; crops plus livestock is mixed farming.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"कौन-सा कथन अंतःफसली खेती (इंटरक्रॉपिंग) और मिश्रित फसली खेती (मिक्स्ड क्रॉपिंग) में सही अंतर बताता है?","optionsHi":["अंतःफसली में एक वर्ष में फसलें एक के बाद एक उगाई जाती हैं; मिश्रित फसली में एक साथ","अंतःफसली में फसलों के साथ पशुधन होता है, जबकि मिश्रित फसली में केवल फसलें","अंतःफसली केवल रोपण कृषि में होती है, मिश्रित फसली केवल छोटे खेतों में","अंतःफसली में फसलें निश्चित पंक्तियों में बोई जाती हैं; मिश्रित फसली में उनके बीजों का मिश्रण बोया जाता है"],"explanationHi":"दोनों में फसलें साथ-साथ उगाई जाती हैं, पर अंतःफसली में उन्हें निश्चित पंक्तियों में रखा जाता है (जैसे मक्का के साथ सोयाबीन), जिससे अलग-अलग उर्वरक देना और कटाई करना आसान होता है। फसलें क्रम से उगाना बहुफसली है; फसलें और पशुधन साथ होना मिश्रित कृषि है।"},
  {"id":"geo-soils-agriculture-119","question":"Growing a leguminous crop such as sunn hemp or dhaincha and ploughing it into the soil before it matures is called:","options":["mulching","composting","green manuring","vermicomposting"],"answer":2,"explanation":"The buried legume adds organic matter and fixed nitrogen, which is green manuring. Mulching covers the soil surface, while composting and vermicomposting decompose waste outside the field before it is applied.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"सनई या ढैंचा जैसी दलहनी फसल को उगाकर उसके परिपक्व होने से पहले मृदा में जोत देना क्या कहलाता है?","optionsHi":["मल्चिंग (पलवार)","कंपोस्टिंग (खाद बनाना)","हरी खाद देना","वर्मीकंपोस्टिंग (केंचुआ खाद)"],"explanationHi":"दबाई गई दलहनी फसल जैव पदार्थ और स्थिर की गई नाइट्रोजन जोड़ती है, इसे हरी खाद देना कहते हैं। मल्चिंग मृदा की सतह को ढकती है, जबकि कंपोस्टिंग और वर्मीकंपोस्टिंग में अपशिष्ट खेत के बाहर सड़ाया जाता है और फिर डाला जाता है।"},
  {"id":"geo-soils-agriculture-120","question":"A soil holds 32% water by volume at field capacity and 14% at the permanent wilting point. The water available to plants in a root zone 1 m deep is about:","options":["180 mm","320 mm","140 mm","460 mm"],"answer":0,"explanation":"Available water = field capacity − wilting point = 18% of 1,000 mm = 180 mm. Water below the wilting point is held too tightly for roots, so the full 320 mm is not usable.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"किसी मृदा में क्षेत्र क्षमता पर आयतन के अनुसार 32% जल और स्थायी म्लानि बिंदु पर 14% जल रहता है। 1 मीटर गहरे मूल क्षेत्र में पौधों को उपलब्ध जल लगभग कितना है?","optionsHi":["180 मिमी","320 मिमी","140 मिमी","460 मिमी"],"explanationHi":"उपलब्ध जल = क्षेत्र क्षमता − म्लानि बिंदु = 1,000 मिमी का 18% = 180 मिमी। म्लानि बिंदु से नीचे का जल इतनी कसकर बँधा होता है कि जड़ें उसे नहीं ले सकतीं, इसलिए पूरा 320 मिमी उपयोगी नहीं है।"},
  {"id":"geo-soils-agriculture-121","question":"Under the size classes used in India's Agriculture Census, a farmer operating 3 hectares is classed as:","options":["small","semi-medium","medium","marginal"],"answer":1,"explanation":"Marginal is below 1 ha, small 1–2 ha, semi-medium 2–4 ha, medium 4–10 ha and large 10 ha or more. Many assume anything above 2 ha is 'medium'.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"भारत की कृषि गणना में प्रयुक्त आकार वर्गों के अनुसार, 3 हेक्टेयर पर खेती करने वाला किसान किस श्रेणी में आता है?","optionsHi":["लघु","अर्ध-मध्यम","मध्यम","सीमांत"],"explanationHi":"सीमांत 1 हेक्टेयर से कम, लघु 1–2 हेक्टेयर, अर्ध-मध्यम 2–4 हेक्टेयर, मध्यम 4–10 हेक्टेयर और बड़ा 10 हेक्टेयर या अधिक होता है। बहुत से लोग मान लेते हैं कि 2 हेक्टेयर से ऊपर ‘मध्यम’ है।"},
  {"id":"geo-soils-agriculture-122","question":"Assertion (A): The burning of paddy straw in Punjab and Haryana peaks in October–November. Reason (R): Farmers have only a short window between the paddy harvest and the sowing of wheat.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Combine-harvested paddy leaves loose straw, and with wheat due within a few weeks, burning is the quickest way to clear fields; machines such as the Happy Seeder aim to remove this pressure.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): पंजाब और हरियाणा में धान की पराली जलाना अक्टूबर–नवंबर में चरम पर होता है। कारण (R): किसानों के पास धान की कटाई और गेहूँ की बुआई के बीच बहुत कम समय होता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"कंबाइन से काटे गए धान के बाद खेत में ढीली पराली बच जाती है, और कुछ ही सप्ताह में गेहूँ बोना होता है, इसलिए जलाना खेत साफ़ करने का सबसे तेज़ तरीका है; हैप्पी सीडर जैसी मशीनें इस दबाव को हटाने का लक्ष्य रखती हैं।"},
  {"id":"geo-soils-agriculture-123","question":"How many of these statements about plantation crops are correct? I. Coffee in India is usually grown under the shade of taller trees. II. Robusta coffee is generally grown at higher elevations than Arabica. III. Coffee is a field crop sown afresh every year with the monsoon. IV. Tea gardens need well-drained slopes, since waterlogging around the roots harms the bushes.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and IV are correct. Arabica prefers the higher, cooler slopes while Robusta tolerates warmer, lower ones, so II is wrong; coffee is a perennial shrub that bears for decades, not an annual crop, so III is wrong.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"रोपण फसलों के बारे में इनमें से कितने कथन सही हैं? I. भारत में कॉफी प्रायः ऊँचे वृक्षों की छाया में उगाई जाती है। II. रोबस्टा कॉफी सामान्यतः अरेबिका की तुलना में अधिक ऊँचाई पर उगाई जाती है। III. कॉफी एक खेत की फसल है जो हर वर्ष मानसून के साथ नए सिरे से बोई जाती है। IV. चाय के बागानों को अच्छी जल-निकासी वाले ढाल चाहिए, क्योंकि जड़ों के चारों ओर जलभराव से झाड़ियों को हानि होती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और IV सही हैं। अरेबिका ऊँचे, ठंडे ढाल पसंद करती है जबकि रोबस्टा अधिक गर्म, निचले क्षेत्र सह लेती है, इसलिए II गलत है; कॉफी बहुवर्षीय झाड़ी है जो दशकों तक फल देती है, वार्षिक फसल नहीं, इसलिए III गलत है।"},
  {"id":"geo-soils-agriculture-124","question":"Jute cultivation is concentrated in the Ganga–Brahmaputra delta mainly because the crop needs:","options":["well-drained laterite soils and a long dry season","flood-renewed alluvium, heat and water for retting","black soil that holds moisture through a dry winter","cool winters with frost to ripen and harden the fibre"],"answer":1,"explanation":"Jute grows fast in hot, humid conditions on flood-renewed alluvium, and the cut stalks must be soaked (retted) in water to free the fibre, which the delta's ponds and channels provide.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"जूट की खेती गंगा–ब्रह्मपुत्र डेल्टा में मुख्यतः इसलिए केंद्रित है क्योंकि इस फसल को चाहिए:","optionsHi":["अच्छी जल-निकासी वाली लेटराइट मृदाएँ और लंबा शुष्क मौसम","बाढ़ से नवीनीकृत जलोढ़ मृदा, गर्मी और सड़ाने (रेटिंग) के लिए जल","काली मृदा जो शुष्क शीत ऋतु में नमी बनाए रखे","रेशे को पकाने और कठोर करने के लिए पाले वाली ठंडी सर्दियाँ"],"explanationHi":"जूट गर्म, आर्द्र परिस्थितियों में बाढ़ से नवीनीकृत जलोढ़ मृदा पर तेज़ी से उगता है, और कटे डंठलों को रेशा अलग करने के लिए पानी में भिगोना (रेटिंग) पड़ता है, जिसके लिए डेल्टा के तालाब और जल-धाराएँ उपलब्ध हैं।"},
  {"id":"geo-soils-agriculture-125","question":"'Kari' soils, which are highly acidic and rich in organic matter, are found in:","options":["the tidal islands of the Sundarbans","the Rann of Kachchh","the Terai of Uttarakhand","the Kuttanad region of Kerala"],"answer":3,"explanation":"Kari soils are peaty, waterlogged soils of Kuttanad, where decaying vegetation under water has made them strongly acidic. The Rann is saline, not peaty.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"‘करी’ मृदाएँ, जो अत्यधिक अम्लीय और जैव पदार्थ से समृद्ध होती हैं, कहाँ पाई जाती हैं?","optionsHi":["सुंदरबन के ज्वारीय द्वीपों में","कच्छ के रण में","उत्तराखंड के तराई में","केरल के कुट्टनाड क्षेत्र में"],"explanationHi":"करी मृदाएँ कुट्टनाड की पीट युक्त, जलमग्न मृदाएँ हैं, जहाँ पानी के नीचे सड़ती वनस्पति ने उन्हें अत्यधिक अम्लीय बना दिया है। रण लवणीय है, पीट युक्त नहीं।"},
  {"id":"geo-soils-agriculture-126","question":"Two fields get the same rainfall. Field X has a sandy soil, and field Y a clay-loam rich in humus. Which statement is correct?","options":["X retains more water, because its large pores can store more of it","Both retain the same amount, since the rainfall on them is equal","Y retains more, as fine clay pores and humus hold water","X retains more water, because sand holds more organic matter"],"answer":2,"explanation":"Water drains quickly through the large pores of sand, while fine pores between clay particles and spongy humus hold it against gravity, giving Y a far higher water-holding capacity.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"दो खेतों में समान वर्षा होती है। खेत X की मृदा रेतीली है, और खेत Y की ह्यूमस से समृद्ध चिकनी दोमट है। कौन-सा कथन सही है?","optionsHi":["X अधिक जल रोकता है, क्योंकि उसके बड़े रंध्र अधिक जल संग्रहित कर सकते हैं","दोनों समान मात्रा में जल रोकते हैं, क्योंकि उन पर वर्षा समान है","Y अधिक जल रोकता है, क्योंकि चिकनी मिट्टी के महीन रंध्र और ह्यूमस जल को थामते हैं","X अधिक जल रोकता है, क्योंकि रेत में अधिक जैव पदार्थ होता है"],"explanationHi":"रेत के बड़े रंध्रों से जल तेज़ी से निकल जाता है, जबकि चिकनी मिट्टी के कणों के बीच के महीन रंध्र और स्पंजी ह्यूमस उसे गुरुत्व के विरुद्ध थामे रखते हैं, जिससे Y की जल-धारण क्षमता कहीं अधिक होती है।"},
  {"id":"geo-soils-agriculture-127","question":"A crop's area rises by 10% and its yield per hectare falls by 10% in a year. Its production:","options":["is unchanged","rises by 1%","falls by 10%","falls by 1%"],"answer":3,"explanation":"Production = area × yield = 1.10 × 0.90 = 0.99 of the earlier level, a fall of 1%. Adding the percentages (+10 − 10 = 0) ignores their interaction.","difficulty":"hard","source":"SSC CGL Tier 2","questionHi":"किसी फसल का क्षेत्रफल एक वर्ष में 10% बढ़ता है और उसकी प्रति हेक्टेयर उपज 10% घटती है। उसका उत्पादन:","optionsHi":["अपरिवर्तित रहता है","1% बढ़ता है","10% घटता है","1% घटता है"],"explanationHi":"उत्पादन = क्षेत्रफल × उपज = 1.10 × 0.90 = पहले के स्तर का 0.99, अर्थात 1% की कमी। प्रतिशतों को जोड़ना (+10 − 10 = 0) उनके पारस्परिक प्रभाव की उपेक्षा करता है।"},
  {"id":"geo-soils-agriculture-128","question":"The alluvial soils of the northern plains are generally:","options":["rich in phosphorus but poor in potash","rich in nitrogen and humus but poor in lime","rich in potash but poor in phosphorus","rich in iron and aluminium oxides but poor in potash"],"answer":2,"explanation":"NCERT notes that alluvial soils are generally rich in potash and poor in phosphorus. Iron and aluminium oxides characterise laterites.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"उत्तरी मैदानों की जलोढ़ मृदाएँ सामान्यतः कैसी होती हैं?","optionsHi":["फॉस्फोरस में समृद्ध पर पोटाश में निर्धन","नाइट्रोजन और ह्यूमस में समृद्ध पर चूने में निर्धन","पोटाश में समृद्ध पर फॉस्फोरस में निर्धन","आयरन और ऐलुमिनियम ऑक्साइड में समृद्ध पर पोटाश में निर्धन"],"explanationHi":"NCERT के अनुसार जलोढ़ मृदाएँ सामान्यतः पोटाश में समृद्ध और फॉस्फोरस में निर्धन होती हैं। आयरन और ऐलुमिनियम के ऑक्साइड लेटराइट की विशेषता हैं।"},
  {"id":"geo-soils-agriculture-129","question":"Match the traditional water-harvesting system with its region. A. Khadin  B. Ahar–pyne  C. Phad  D. Bamboo drip irrigation; 1. Meghalaya  2. South Bihar  3. Western Rajasthan (Jaisalmer)  4. Maharashtra","options":["A-2, B-3, C-4, D-1","A-3, B-2, C-4, D-1","A-3, B-4, C-2, D-1","A-3, B-2, C-1, D-4"],"answer":1,"explanation":"Khadins are run-off fields bunded on the low side in Jaisalmer; ahars (reservoirs) and pynes (channels) serve south Bihar; phads are community canal systems of north Maharashtra; bamboo pipes carry stream water in Meghalaya.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"पारंपरिक जल-संचयन प्रणाली का उसके क्षेत्र से मिलान कीजिए। A. खड़ीन  B. आहर–पइन  C. फड़  D. बाँस ड्रिप सिंचाई; 1. मेघालय  2. दक्षिण बिहार  3. पश्चिमी राजस्थान (जैसलमेर)  4. महाराष्ट्र","optionsHi":["A-2, B-3, C-4, D-1","A-3, B-2, C-4, D-1","A-3, B-4, C-2, D-1","A-3, B-2, C-1, D-4"],"explanationHi":"खड़ीन जैसलमेर में निचली ओर बाँध वाले अपवाह-खेत हैं; आहर (जलाशय) और पइन (नालियाँ) दक्षिण बिहार में काम आते हैं; फड़ उत्तरी महाराष्ट्र की सामुदायिक नहर प्रणालियाँ हैं; और बाँस की नलिकाएँ मेघालय में झरने का पानी ले जाती हैं।"},
  {"id":"geo-soils-agriculture-130","question":"Match the fertiliser with the main nutrient(s) it supplies. A. Urea  B. Diammonium phosphate (DAP)  C. Muriate of potash (MOP)  D. Single superphosphate (SSP); 1. Potassium  2. Nitrogen only  3. Phosphorus, with sulphur and calcium  4. Nitrogen and phosphorus","options":["A-4, B-2, C-1, D-3","A-2, B-3, C-1, D-4","A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3"],"answer":3,"explanation":"Urea is about 46% N; DAP carries both N and P; MOP is potassium chloride; SSP gives phosphorus along with sulphur and calcium from its gypsum content.","difficulty":"hard","source":"SSC CGL Tier 2","questionHi":"उर्वरक का मिलान उस प्रमुख पोषक तत्व से कीजिए जो वह प्रदान करता है। A. यूरिया  B. डाइअमोनियम फॉस्फेट (DAP)  C. म्यूरिएट ऑफ पोटाश (MOP)  D. सिंगल सुपरफॉस्फेट (SSP); 1. पोटैशियम  2. केवल नाइट्रोजन  3. फॉस्फोरस, सल्फर और कैल्शियम के साथ  4. नाइट्रोजन और फॉस्फोरस","optionsHi":["A-4, B-2, C-1, D-3","A-2, B-3, C-1, D-4","A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3"],"explanationHi":"यूरिया में लगभग 46% N होती है; DAP में N और P दोनों होते हैं; MOP पोटैशियम क्लोराइड है; SSP अपनी जिप्सम सामग्री से सल्फर और कैल्शियम के साथ फॉस्फोरस देता है।"},
  {"id":"geo-soils-agriculture-131","question":"Assertion (A): The early gains of the Green Revolution were concentrated in Punjab, Haryana and western Uttar Pradesh. Reason (R): These states have the most extensive black soils in India.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"These states lie on alluvium, not black soil; their advantage was assured canal and tube-well irrigation, which the high-yielding wheat varieties and heavy fertiliser doses needed.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): हरित क्रांति के प्रारंभिक लाभ पंजाब, हरियाणा और पश्चिमी उत्तर प्रदेश में केंद्रित थे। कारण (R): इन राज्यों में भारत की सबसे व्यापक काली मृदाएँ हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"ये राज्य जलोढ़ मृदा पर स्थित हैं, काली मृदा पर नहीं; इनका लाभ नहरों और नलकूपों की सुनिश्चित सिंचाई थी, जिसकी उच्च उपज वाली गेहूँ किस्मों और भारी उर्वरक मात्रा को आवश्यकता थी।"},
  {"id":"geo-soils-agriculture-132","question":"Match the livestock breed with its description. A. Gir  B. Sahiwal  C. Tharparkar  D. Murrah; 1. Buffalo breed of Haryana  2. Cattle breed from the Gir forest region of Gujarat  3. Cattle breed of the Thar desert region  4. Cattle breed named after a district of Punjab, now in Pakistan","options":["A-2, B-3, C-4, D-1","A-2, B-4, C-3, D-1","A-4, B-2, C-3, D-1","A-2, B-4, C-1, D-3"],"answer":1,"explanation":"Gir, Sahiwal and Tharparkar are indigenous milch cattle breeds, while Murrah, the best-known Indian dairy buffalo, comes from Haryana. Mixing up buffalo and cattle breeds is the usual trap.","difficulty":"very-hard","source":"SSC CGL Tier 2","questionHi":"पशु नस्ल का मिलान उसके विवरण से कीजिए। A. गिर  B. साहीवाल  C. थारपारकर  D. मुर्रा; 1. हरियाणा की भैंस की नस्ल  2. गुजरात के गिर वन क्षेत्र की गाय की नस्ल  3. थार मरुस्थल क्षेत्र की गाय की नस्ल  4. पंजाब के एक ज़िले के नाम पर रखी गई गाय की नस्ल, जो अब पाकिस्तान में है","optionsHi":["A-2, B-3, C-4, D-1","A-2, B-4, C-3, D-1","A-4, B-2, C-3, D-1","A-2, B-4, C-1, D-3"],"explanationHi":"गिर, साहीवाल और थारपारकर देशी दुधारू गाय की नस्लें हैं, जबकि मुर्रा, भारत की सबसे प्रसिद्ध दुधारू भैंस, हरियाणा की है। भैंस और गाय की नस्लों को आपस में मिला देना सामान्य भ्रम है।"},
  {"id":"geo-soils-agriculture-133","question":"Match the soil-forming process with the setting where it dominates. A. Laterisation  B. Calcification  C. Podzolisation  D. Salinisation; 1. Cool, humid coniferous forests of the high Himalaya  2. Poorly drained arid areas or over-irrigated canal tracts  3. Hot, humid tropics with heavy rain  4. Semi-arid and arid regions where evaporation exceeds rainfall","options":["A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-4, C-2, D-1"],"answer":2,"explanation":"Heavy rain and heat leach silica (laterisation); low rain leaves calcium carbonate in the profile (calcification); acidic leaching under conifers gives podzols; capillary rise and evaporation concentrate salts (salinisation).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"मृदा-निर्माण प्रक्रिया का मिलान उस परिवेश से कीजिए जहाँ वह प्रमुख होती है। A. लेटराइटीकरण  B. कैल्सीकरण  C. पॉडज़ोलीकरण  D. लवणीकरण; 1. उच्च हिमालय के ठंडे, आर्द्र शंकुधारी वन  2. खराब जल-निकासी वाले शुष्क क्षेत्र या अत्यधिक सिंचित नहर क्षेत्र  3. भारी वर्षा वाले गर्म, आर्द्र उष्णकटिबंध  4. अर्ध-शुष्क और शुष्क क्षेत्र जहाँ वाष्पीकरण वर्षा से अधिक होता है","optionsHi":["A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-4, C-2, D-1"],"explanationHi":"भारी वर्षा और गर्मी सिलिका को बहा ले जाती है (लेटराइटीकरण); कम वर्षा कैल्शियम कार्बोनेट को परिच्छेदिका में छोड़ देती है (कैल्सीकरण); शंकुधारी वृक्षों के नीचे अम्लीय निक्षालन से पॉडज़ॉल बनते हैं; केशिका आरोहण और वाष्पीकरण लवणों को संकेंद्रित करते हैं (लवणीकरण)।"},
  {"id":"geo-soils-agriculture-134","question":"Tube-well irrigation is far more widespread in the northern plains than on the Deccan plateau mainly because:","options":["the plains receive more rain than any part of the plateau","porous alluvium stores much groundwater; hard rock holds little","peninsular rivers are perennial, so wells are unnecessary there","the black soils of the plateau are too sandy to hold any water"],"answer":1,"explanation":"Thick, porous alluvium forms vast aquifers that are easy to tap, whereas groundwater in the hard rocks of the plateau is confined to cracks, so the peninsula relies more on tanks.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"उत्तरी मैदानों में नलकूप सिंचाई दक्कन पठार की तुलना में कहीं अधिक व्यापक है, इसका मुख्य कारण है:","optionsHi":["मैदानों में पठार के किसी भी भाग से अधिक वर्षा होती है","रंध्रयुक्त जलोढ़ में बहुत भूजल संचित होता है; कठोर चट्टान में कम","प्रायद्वीपीय नदियाँ सदानीरा हैं, इसलिए वहाँ कुओं की आवश्यकता नहीं","पठार की काली मृदाएँ इतनी रेतीली हैं कि पानी नहीं रोक सकतीं"],"explanationHi":"मोटी, रंध्रयुक्त जलोढ़ विशाल जलभृत बनाती है जिन्हें दोहना आसान है, जबकि पठार की कठोर चट्टानों में भूजल दरारों तक सीमित है, इसलिए प्रायद्वीप तालाबों पर अधिक निर्भर है।"},
  {"id":"geo-soils-agriculture-135","question":"Match the cause of land degradation with the states where NCERT says it is a major problem. A. Deforestation due to mining  B. Overgrazing  C. Over-irrigation; 1. Punjab, Haryana and western Uttar Pradesh  2. Jharkhand, Chhattisgarh, Madhya Pradesh and Odisha  3. Gujarat, Rajasthan, Madhya Pradesh and Maharashtra","options":["A-2, B-3, C-1","A-3, B-2, C-1","A-2, B-1, C-3","A-1, B-3, C-2"],"answer":0,"explanation":"Mining in the mineral-rich states strips forests; pastoral dry regions suffer overgrazing; and over-irrigation in the Green Revolution belt causes waterlogging, salinity and alkalinity.","difficulty":"hard","source":"SSC CGL Tier 2","questionHi":"भूमि क्षरण के कारण का मिलान उन राज्यों से कीजिए जहाँ NCERT के अनुसार वह प्रमुख समस्या है। A. खनन के कारण वनोन्मूलन  B. अतिचारण  C. अत्यधिक सिंचाई; 1. पंजाब, हरियाणा और पश्चिमी उत्तर प्रदेश  2. झारखंड, छत्तीसगढ़, मध्य प्रदेश और ओडिशा  3. गुजरात, राजस्थान, मध्य प्रदेश और महाराष्ट्र","optionsHi":["A-2, B-3, C-1","A-3, B-2, C-1","A-2, B-1, C-3","A-1, B-3, C-2"],"explanationHi":"खनिज-समृद्ध राज्यों में खनन वनों को नष्ट करता है; पशुचारी शुष्क क्षेत्र अतिचारण से ग्रस्त हैं; और हरित क्रांति पट्टी में अत्यधिक सिंचाई से जलभराव, लवणता और क्षारीयता उत्पन्न होती है।"},
  {"id":"geo-soils-agriculture-136","question":"Match the form of water erosion with its description. A. Sheet erosion  B. Rill erosion  C. Gully erosion  D. Ravines (badlands); 1. Many small finger-like channels cut by runoff  2. Uniform removal of a thin layer of topsoil over a large area  3. Deep channels that cannot be crossed by a plough  4. Land so cut up by deep gullies that it is unfit for cultivation, as along the Chambal","options":["A-2, B-1, C-3, D-4","A-1, B-2, C-3, D-4","A-2, B-3, C-1, D-4","A-2, B-1, C-4, D-3"],"answer":0,"explanation":"Erosion progresses from almost invisible sheet wash, to rills, to gullies, to a network of ravines. Sheet erosion is the most dangerous early stage because it goes unnoticed.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"जल अपरदन के रूप का मिलान उसके विवरण से कीजिए। A. परत अपरदन  B. क्षुद्र नालिका (रिल) अपरदन  C. अवनालिका (गली) अपरदन  D. उत्खात भूमि (बैडलैंड); 1. अपवाह द्वारा काटी गई अनेक छोटी, उँगली जैसी नालियाँ  2. बड़े क्षेत्र से ऊपरी मृदा की पतली परत का समान रूप से हट जाना  3. गहरी नालियाँ जिन्हें हल पार नहीं कर सकता  4. गहरी अवनालिकाओं से इतनी कटी-फटी भूमि कि खेती के अयोग्य हो, जैसे चंबल के किनारे","optionsHi":["A-2, B-1, C-3, D-4","A-1, B-2, C-3, D-4","A-2, B-3, C-1, D-4","A-2, B-1, C-4, D-3"],"explanationHi":"अपरदन लगभग अदृश्य परत-प्रवाह से क्षुद्र नालिकाओं, फिर अवनालिकाओं और अंततः उत्खात भूमि के जाल तक बढ़ता है। परत अपरदन सबसे खतरनाक प्रारंभिक अवस्था है क्योंकि यह अनदेखा रह जाता है।"},
  {"id":"geo-soils-agriculture-137","question":"Which of these crops grows best on distinctly acidic soils, so that heavy liming of its fields would harm it?","options":["Cotton","Sugarcane","Barley","Tea"],"answer":3,"explanation":"Tea prefers acidic soils of about pH 4.5–5.5, which is why it thrives on the leached hill soils of Assam and Darjeeling. Barley is notable for tolerating saline, alkaline conditions.","difficulty":"hard","source":"SSC CGL Tier 2","questionHi":"इनमें से कौन-सी फसल स्पष्ट रूप से अम्लीय मृदाओं में सबसे अच्छी उगती है, जिससे उसके खेतों में भारी मात्रा में चूना डालना उसे हानि पहुँचाएगा?","optionsHi":["कपास","गन्ना","जौ","चाय"],"explanationHi":"चाय लगभग pH 4.5–5.5 की अम्लीय मृदाओं को पसंद करती है, इसीलिए यह असम और दार्जिलिंग की निक्षालित पहाड़ी मृदाओं में फलती-फूलती है। जौ लवणीय, क्षारीय परिस्थितियाँ सहने के लिए जाना जाता है।"},
  {"id":"geo-soils-agriculture-138","question":"'Khaira' disease of rice, with rusty brown patches on the leaves and stunted growth, is caused by a deficiency of:","options":["iron","nitrogen","zinc","boron"],"answer":2,"explanation":"Khaira was identified in the Tarai of Uttar Pradesh as zinc deficiency in flooded rice and is corrected with zinc sulphate. It is a classic example of a micronutrient disorder.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"चावल का ‘खैरा’ रोग, जिसमें पत्तियों पर जंग जैसे भूरे धब्बे और अवरुद्ध वृद्धि होती है, किसकी कमी से होता है?","optionsHi":["आयरन","नाइट्रोजन","जिंक","बोरॉन"],"explanationHi":"खैरा की पहचान उत्तर प्रदेश के तराई में जलमग्न चावल में जिंक की कमी के रूप में हुई थी, और इसे जिंक सल्फेट से ठीक किया जाता है। यह सूक्ष्म पोषक तत्व विकार का एक क्लासिक उदाहरण है।"},
  {"id":"geo-soils-agriculture-139","question":"Which of these crops was NOT brought to India from the Americas?","options":["Maize","Chilli pepper","Potato","Sugarcane"],"answer":3,"explanation":"Maize, chilli and potato are New World crops introduced after 1500, largely through the Portuguese. Sugarcane was cultivated in India since ancient times, which is why the word 'sugar' traces back to Sanskrit 'sharkara'.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कौन-सी फसल अमेरिका महाद्वीपों से भारत नहीं लाई गई?","optionsHi":["मक्का","मिर्च","आलू","गन्ना"],"explanationHi":"मक्का, मिर्च और आलू 1500 के बाद, मुख्यतः पुर्तगालियों के माध्यम से, लाई गई नई दुनिया की फसलें हैं। भारत में गन्ने की खेती प्राचीन काल से होती रही है, इसीलिए ‘शुगर’ शब्द का मूल संस्कृत ‘शर्करा’ में मिलता है।"},
  {"id":"geo-soils-agriculture-140","question":"The sub-division and fragmentation of farm holdings in India is caused mainly by:","options":["equal division of land among heirs","the Green Revolution demand for large farms","the consolidation of holdings (chakbandi)","shifting cultivation in the plains"],"answer":0,"explanation":"Each generation divides land among heirs, often plot by plot, creating small scattered fields. Consolidation (chakbandi) is the remedy, not the cause.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"भारत में कृषि जोतों का उप-विभाजन और विखंडन मुख्यतः किस कारण होता है?","optionsHi":["वारिसों में भूमि का समान बँटवारा","बड़े खेतों की हरित क्रांति की माँग","जोतों की चकबंदी","मैदानों में स्थानांतरित कृषि"],"explanationHi":"हर पीढ़ी वारिसों में भूमि बाँटती है, प्रायः भूखंड-दर-भूखंड, जिससे छोटे बिखरे खेत बनते हैं। चकबंदी इसका उपाय है, कारण नहीं।"},
  {"id":"geo-soils-agriculture-141","question":"Berseem (Egyptian clover), widely grown in north India, is best described as a:","options":["kharif fodder grass grown with maize","rabi fodder legume that fixes nitrogen","perennial plantation crop of the hills","kharif oilseed of the dry Deccan"],"answer":1,"explanation":"Berseem is sown in October–November and cut several times through winter, giving protein-rich green fodder; being a legume, it also fixes nitrogen, so it fits well before kharif crops.","difficulty":"hard","source":"SSC CGL Tier 2","questionHi":"बरसीम (मिस्री तिपतिया), जो उत्तर भारत में व्यापक रूप से उगाई जाती है, का सबसे सही वर्णन है:","optionsHi":["मक्का के साथ उगाई जाने वाली खरीफ चारा घास","नाइट्रोजन स्थिर करने वाली रबी चारा दलहन","पहाड़ियों की बहुवर्षीय रोपण फसल","शुष्क दक्कन की खरीफ तिलहन"],"explanationHi":"बरसीम अक्टूबर–नवंबर में बोई जाती है और सर्दियों भर कई बार काटी जाती है, जिससे प्रोटीन-समृद्ध हरा चारा मिलता है; दलहन होने के कारण यह नाइट्रोजन भी स्थिर करती है, इसलिए खरीफ फसलों से पहले यह अच्छी बैठती है।"},
  {"id":"geo-soils-agriculture-142","question":"Which of these is NOT counted under 'foodgrains' in Indian agricultural statistics?","options":["Gram (chana)","Bajra","Barley","Groundnut"],"answer":3,"explanation":"Foodgrains comprise cereals (rice, wheat, coarse cereals such as bajra and barley) and pulses such as gram. Groundnut is an oilseed and is reported separately.","difficulty":"very-hard","source":"SSC CGL Tier 2","questionHi":"इनमें से कौन-सी भारतीय कृषि सांख्यिकी में ‘खाद्यान्न’ में नहीं गिनी जाती?","optionsHi":["चना","बाजरा","जौ","मूँगफली"],"explanationHi":"खाद्यान्न में अनाज (चावल, गेहूँ, बाजरा और जौ जैसे मोटे अनाज) और चना जैसी दलहनें आती हैं। मूँगफली तिलहन है और अलग से दर्ज की जाती है।"},
  {"id":"geo-soils-agriculture-143","question":"In Indian agricultural statistics, the agricultural year runs from:","options":["January to December","April to March","July to June","October to September"],"answer":2,"explanation":"The agricultural year starts in July with kharif sowing and ends in June after the rabi harvest. April–March is the financial year, which is the usual trap.","difficulty":"hard","source":"SSC CGL Tier 2","questionHi":"भारतीय कृषि सांख्यिकी में कृषि वर्ष किस अवधि का होता है?","optionsHi":["जनवरी से दिसंबर","अप्रैल से मार्च","जुलाई से जून","अक्टूबर से सितंबर"],"explanationHi":"कृषि वर्ष जुलाई में खरीफ की बुआई से शुरू होता है और रबी की कटाई के बाद जून में समाप्त होता है। अप्रैल–मार्च वित्तीय वर्ष है, जो सामान्य भ्रम है।"},
  {"id":"geo-soils-agriculture-144","question":"The A2+FL cost of producing wheat is ₹1,240 per quintal and the full C2 cost is ₹1,500 per quintal. Under the policy of fixing the Minimum Support Price at least 50% above the A2+FL cost, the lowest MSP is:","options":["₹1,860 per quintal","₹1,488 per quintal","₹1,364 per quintal","₹2,250 per quintal"],"answer":0,"explanation":"MSP = 1.5 x A2+FL = 1.5 x 1,240 = ₹1,860. The figure ₹2,250 wrongly applies 50% to the C2 cost, ₹1,488 applies only 20%, and ₹1,364 only 10%.","difficulty":"hard","questionHi":"गेहूँ के उत्पादन की A2+FL लागत ₹1,240 प्रति क्विंटल और पूर्ण C2 लागत ₹1,500 प्रति क्विंटल है। न्यूनतम समर्थन मूल्य को A2+FL लागत से कम से कम 50% अधिक रखने की नीति के अंतर्गत सबसे कम MSP है:","optionsHi":["₹1,860 प्रति क्विंटल","₹1,488 प्रति क्विंटल","₹1,364 प्रति क्विंटल","₹2,250 प्रति क्विंटल"],"explanationHi":"MSP = 1.5 x A2+FL = 1.5 x 1,240 = ₹1,860। ₹2,250 में 50% गलती से C2 लागत पर लगाया गया है, ₹1,488 में केवल 20% और ₹1,364 में केवल 10%।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-soils-agriculture-145","question":"A crop is recommended 120 kg of nitrogen per hectare, to be supplied only through urea containing 46% N. The urea needed per hectare is about:","options":["120 kg","261 kg","55 kg","217 kg"],"answer":1,"explanation":"Urea needed = 120 / 0.46 = about 261 kg. Multiplying instead (120 x 0.46 = 55 kg) is the common slip, and 217 kg uses 55% as the nitrogen share.","difficulty":"moderate","questionHi":"किसी फसल के लिए प्रति हेक्टेयर 120 kg नाइट्रोजन की अनुशंसा है, जो केवल 46% N वाले यूरिया से देनी है। प्रति हेक्टेयर आवश्यक यूरिया लगभग है:","optionsHi":["120 kg","261 kg","55 kg","217 kg"],"explanationHi":"आवश्यक यूरिया = 120 / 0.46 = लगभग 261 kg। इसके बजाय गुणा (120 x 0.46 = 55 kg) करना आम भूल है, और 217 kg में नाइट्रोजन का अंश 55% लिया गया है।","source":"SSC CGL · State PCS"},
  {"id":"geo-soils-agriculture-146","question":"A crop needs 120 kg N and 60 kg P2O5 per hectare. The phosphorus is supplied by diammonium phosphate (18% N, 46% P2O5) and the rest of the nitrogen by urea (46% N). The urea needed per hectare is about:","options":["261 kg","237 kg","210 kg","130 kg"],"answer":2,"explanation":"DAP needed = 60/0.46 = 130.4 kg, which also gives 130.4 x 0.18 = 23.5 kg N. The balance 120 - 23.5 = 96.5 kg N needs 96.5/0.46 = about 210 kg urea. Ignoring the DAP nitrogen gives 261 kg.","difficulty":"very-hard","questionHi":"किसी फसल को प्रति हेक्टेयर 120 kg N और 60 kg P2O5 चाहिए। फॉस्फोरस डाइअमोनियम फॉस्फेट (18% N, 46% P2O5) से और शेष नाइट्रोजन यूरिया (46% N) से दी जाती है। प्रति हेक्टेयर आवश्यक यूरिया लगभग है:","optionsHi":["261 kg","237 kg","210 kg","130 kg"],"explanationHi":"आवश्यक DAP = 60/0.46 = 130.4 kg, जिससे 130.4 x 0.18 = 23.5 kg N भी मिलती है। शेष 120 - 23.5 = 96.5 kg N के लिए 96.5/0.46 = लगभग 210 kg यूरिया चाहिए। DAP की नाइट्रोजन छोड़ने पर 261 kg आता है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-soils-agriculture-147","question":"A crop needs 600 mm of water at the root zone. Flood irrigation has an efficiency of 40% and drip irrigation 90%. The water saved per hectare by switching to drip, in depth, is about:","options":["560 mm","667 mm","900 mm","833 mm"],"answer":3,"explanation":"Flood needs 600/0.40 = 1,500 mm and drip 600/0.90 = 667 mm, so the saving is 1,500 - 667 = 833 mm. The 900 mm option subtracts 600 from 1,500, and 667 mm is the drip requirement alone.","difficulty":"hard","questionHi":"किसी फसल को जड़ क्षेत्र में 600 mm जल चाहिए। बाढ़ सिंचाई की दक्षता 40% और ड्रिप सिंचाई की 90% है। ड्रिप अपनाने से प्रति हेक्टेयर गहराई के रूप में बचा जल लगभग है:","optionsHi":["560 mm","667 mm","900 mm","833 mm"],"explanationHi":"बाढ़ सिंचाई में 600/0.40 = 1,500 mm और ड्रिप में 600/0.90 = 667 mm चाहिए, इसलिए बचत 1,500 - 667 = 833 mm है। 900 mm वाला विकल्प 1,500 में से 600 घटाता है और 667 mm केवल ड्रिप की आवश्यकता है।","source":"UPSC Prelims · SSC JE"},
  {"id":"geo-soils-agriculture-148","question":"A soil analysis gives 0.75% organic carbon. Using the conventional factor of 1.724 to convert organic carbon into organic matter, the organic matter content is about:","options":["1.29%","1.50%","0.43%","0.58%"],"answer":0,"explanation":"Organic matter = organic carbon x 1.724 = 0.75 x 1.724 = 1.29%. Dividing by 1.724 (0.43%) is the usual wrong direction, since organic matter is about 58% carbon.","difficulty":"very-hard","questionHi":"एक मृदा विश्लेषण में 0.75% कार्बनिक कार्बन मिलता है। कार्बनिक कार्बन को कार्बनिक पदार्थ में बदलने के प्रचलित गुणक 1.724 का उपयोग करने पर कार्बनिक पदार्थ की मात्रा लगभग है:","optionsHi":["1.29%","1.50%","0.43%","0.58%"],"explanationHi":"कार्बनिक पदार्थ = कार्बनिक कार्बन x 1.724 = 0.75 x 1.724 = 1.29%। 1.724 से भाग देना (0.43%) आम उलटी दिशा की भूल है, क्योंकि कार्बनिक पदार्थ में लगभग 58% कार्बन होता है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-soils-agriculture-149","question":"Wheat has a 1,000-grain weight of 40 g. A seed rate of 100 kg per hectare is used, and 80% of the seeds emerge. The number of plants per square metre is about:","options":["250","200","160","320"],"answer":1,"explanation":"100 kg / 0.040 kg per 1,000 seeds = 2.5 million seeds per hectare = 250 per sq m. At 80% emergence this is 200 plants per sq m. The 250 figure forgets the emergence loss.","difficulty":"hard","questionHi":"गेहूँ के 1,000 दानों का भार 40 g है। प्रति हेक्टेयर 100 kg बीज दर प्रयोग की जाती है और 80% बीज अंकुरित होते हैं। प्रति वर्ग मीटर पौधों की संख्या लगभग है:","optionsHi":["250","200","160","320"],"explanationHi":"100 kg / 0.040 kg प्रति 1,000 बीज = प्रति हेक्टेयर 25 लाख बीज = प्रति वर्ग मीटर 250। 80% अंकुरण पर यह प्रति वर्ग मीटर 200 पौधे होते हैं। 250 का आँकड़ा अंकुरण की हानि भूल जाता है।","source":"UPSC Prelims · SSC JE"},
  {"id":"geo-soils-agriculture-150","question":"A soil has a bulk density of 1.4 g per cubic cm and a particle density of 2.65 g per cubic cm. Its total porosity is about:","options":["35%","62%","47%","53%"],"answer":2,"explanation":"Porosity = 1 - (bulk density / particle density) = 1 - 1.4/2.65 = 0.472, about 47%. The 53% option is the ratio itself, which is the solid fraction.","difficulty":"hard","questionHi":"एक मृदा का आयतन घनत्व 1.4 g प्रति घन cm और कण घनत्व 2.65 g प्रति घन cm है। इसकी कुल सरंध्रता लगभग है:","optionsHi":["35%","62%","47%","53%"],"explanationHi":"सरंध्रता = 1 - (आयतन घनत्व / कण घनत्व) = 1 - 1.4/2.65 = 0.472, यानी लगभग 47%। 53% वाला विकल्प स्वयं अनुपात है, जो ठोस अंश है।","source":"UPSC Prelims · SSC JE"},
  {"id":"geo-soils-agriculture-151","question":"A tube-well discharges 20 litres per second. The time needed to apply a 6 cm depth of water over 1 hectare is about:","options":["83 h 20 min","4 h 10 min","16 h 40 min","8 h 20 min"],"answer":3,"explanation":"Volume = 0.06 m x 10,000 sq m = 600 cubic m = 600,000 L. At 20 L/s this takes 30,000 s = 8 h 20 min. Dividing by 40 L/s or using 2 L/s gives the other options.","difficulty":"very-hard","questionHi":"एक नलकूप प्रति सेकंड 20 लीटर जल देता है। 1 हेक्टेयर पर 6 cm गहराई का जल देने में लगने वाला समय लगभग है:","optionsHi":["83 घंटे 20 मिनट","4 घंटे 10 मिनट","16 घंटे 40 मिनट","8 घंटे 20 मिनट"],"explanationHi":"आयतन = 0.06 m x 10,000 वर्ग m = 600 घन m = 600,000 L। 20 L/s पर इसमें 30,000 s = 8 घंटे 20 मिनट लगते हैं। 40 L/s से भाग देने या 2 L/s लेने पर अन्य विकल्प आते हैं।","source":"UPSC Prelims · SSC JE"},
  {"id":"geo-soils-agriculture-152","question":"The crop coefficient (Kc) of a crop at mid-season is 1.15 and the reference evapotranspiration is 6 mm per day. Its water use over 30 such days is about:","options":["207 mm","180 mm","230 mm","157 mm"],"answer":0,"explanation":"Crop evapotranspiration = Kc x ETo = 1.15 x 6 = 6.9 mm a day, and 6.9 x 30 = 207 mm. Using ETo alone gives 180 mm, and dividing by Kc gives 157 mm.","difficulty":"hard","questionHi":"किसी फसल का मध्य-ऋतु फसल गुणांक (Kc) 1.15 और संदर्भ वाष्पोत्सर्जन 6 mm प्रतिदिन है। ऐसे 30 दिनों में उसका जल उपयोग लगभग है:","optionsHi":["207 mm","180 mm","230 mm","157 mm"],"explanationHi":"फसल वाष्पोत्सर्जन = Kc x ETo = 1.15 x 6 = 6.9 mm प्रतिदिन, और 6.9 x 30 = 207 mm। केवल ETo लेने पर 180 mm आता है और Kc से भाग देने पर 157 mm।","source":"UPSC Prelims · SSC JE"},
  {"id":"geo-soils-agriculture-153","question":"Which soil texture has the highest available water capacity, meaning the largest gap between field capacity and permanent wilting point?","options":["Sandy loam","Silt loam","Clay","Sand"],"answer":1,"explanation":"Silt loam holds a lot of water at field capacity and gives most of it up before wilting. Sand drains too freely, and clay holds plenty but retains much of it too tightly to be used, so its available range is smaller.","difficulty":"very-hard","questionHi":"किस मृदा गठन की उपलब्ध जल धारण क्षमता सबसे अधिक है, अर्थात क्षेत्र क्षमता और स्थायी म्लानि बिंदु के बीच सबसे बड़ा अंतर?","optionsHi":["बलुई दोमट","गाद दोमट","चिकनी मिट्टी","बालू"],"explanationHi":"गाद दोमट क्षेत्र क्षमता पर बहुत जल रखती है और म्लानि से पहले उसका अधिकांश छोड़ देती है। बालू से जल बहुत आसानी से निकल जाता है, और चिकनी मिट्टी बहुत जल रखती है पर उसका बड़ा भाग इतना कसकर पकड़ती है कि उपयोग नहीं हो पाता, इसलिए उसका उपलब्ध परास कम है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-soils-agriculture-154","question":"The swelling and deep cracking of black cotton soils is mainly due to which clay mineral?","options":["Illite (mica-type clay)","Kaolinite (1:1 clay)","Montmorillonite (smectite)","Gibbsite (aluminium oxide)"],"answer":2,"explanation":"Montmorillonite is a 2:1 expanding clay that takes in water between its layers, swelling when wet and shrinking into wide cracks when dry. Kaolinite, typical of red and laterite soils, is non-expanding, and gibbsite is an aluminium oxide of highly weathered soils.","difficulty":"hard","questionHi":"काली कपास मिट्टी का फूलना और गहरी दरारें पड़ना मुख्यतः किस मृत्तिका खनिज के कारण है?","optionsHi":["इलाइट (अभ्रक-प्रकार की मृत्तिका)","काओलिनाइट (1:1 मृत्तिका)","मॉन्टमोरिलोनाइट (स्मेक्टाइट)","गिब्साइट (एल्युमिनियम ऑक्साइड)"],"explanationHi":"मॉन्टमोरिलोनाइट 2:1 प्रसारी मृत्तिका है जो अपनी परतों के बीच जल ले लेती है, गीली होने पर फूलती है और सूखने पर सिकुड़कर चौड़ी दरारें बनाती है। लाल और लैटेराइट मिट्टियों का काओलिनाइट अप्रसारी है और गिब्साइट अत्यधिक अपक्षयित मिट्टियों का एल्युमिनियम ऑक्साइड है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-soils-agriculture-155","question":"Match the Indian soil with its USDA soil order. A. Black soil  B. Red soil  C. Desert (arid) soil  D. Laterite soil. 1. Aridisols  2. Vertisols  3. Alfisols  4. Ultisols and Oxisols","options":["A-2, B-1, C-3, D-4","A-3, B-2, C-1, D-4","A-2, B-3, C-4, D-1","A-2, B-3, C-1, D-4"],"answer":3,"explanation":"Black cotton soils with their swelling clays are Vertisols, red soils are mostly Alfisols, desert soils are Aridisols, and the strongly weathered laterites are Ultisols and Oxisols.","difficulty":"very-hard","questionHi":"भारतीय मृदा का उसके USDA मृदा गण से मिलान कीजिए। A. काली मिट्टी  B. लाल मिट्टी  C. मरुस्थलीय (शुष्क) मिट्टी  D. लैटेराइट मिट्टी। 1. एरिडिसोल  2. वर्टिसोल  3. एल्फिसोल  4. अल्टिसोल और ऑक्सीसोल","optionsHi":["A-2, B-1, C-3, D-4","A-3, B-2, C-1, D-4","A-2, B-3, C-4, D-1","A-2, B-3, C-1, D-4"],"explanationHi":"फूलने वाली मृत्तिकाओं वाली काली कपास मिट्टियाँ वर्टिसोल हैं, लाल मिट्टियाँ अधिकांशतः एल्फिसोल हैं, मरुस्थलीय मिट्टियाँ एरिडिसोल हैं, और अत्यधिक अपक्षयित लैटेराइट अल्टिसोल तथा ऑक्सीसोल हैं।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-soils-agriculture-156","question":"Which statement correctly separates sodic (alkali) soils from saline soils?","options":["Sodic soils have an exchangeable sodium percentage above 15 and pH above 8.5, whereas saline soils have high conductivity and usually pH below 8.5","Sodic soils have a pH below 6 and a high aluminium content, whereas saline soils have a high pH","Both are defined only by a conductivity above 4 dS per m, and they differ in colour alone","Saline soils have an exchangeable sodium percentage above 15 and pH above 8.5, whereas sodic soils have a high conductivity and usually pH below 8.5"],"answer":0,"explanation":"Saline soils have an electrical conductivity above 4 dS/m with pH normally below 8.5. Sodic soils have more than 15% exchangeable sodium and pH above 8.5, with poor structure, so they are treated with gypsum, while saline soils need leaching.","difficulty":"very-hard","questionHi":"कौन-सा कथन सोडिक (क्षारीय) मृदा को लवणीय मृदा से सही ढंग से अलग करता है?","optionsHi":["सोडिक मृदा में विनिमेय सोडियम प्रतिशत 15 से अधिक और pH 8.5 से अधिक होता है, जबकि लवणीय मृदा में विद्युत चालकता अधिक और प्रायः pH 8.5 से कम होता है","सोडिक मृदा का pH 6 से कम और एल्युमिनियम अधिक होता है, जबकि लवणीय मृदा का pH अधिक होता है","दोनों केवल 4 dS प्रति m से अधिक चालकता से परिभाषित होती हैं और केवल रंग में भिन्न हैं","लवणीय मृदा में विनिमेय सोडियम प्रतिशत 15 से अधिक और pH 8.5 से अधिक होता है, जबकि सोडिक मृदा में चालकता अधिक और pH 8.5 से कम होता है"],"explanationHi":"लवणीय मृदाओं की विद्युत चालकता 4 dS/m से अधिक और pH सामान्यतः 8.5 से कम होता है। सोडिक मृदाओं में 15% से अधिक विनिमेय सोडियम और pH 8.5 से अधिक होता है, संरचना खराब होती है, इसलिए उनका जिप्सम से उपचार किया जाता है, जबकि लवणीय मृदाओं को निक्षालन चाहिए।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-soils-agriculture-157","question":"Soil colour is described in the field and in soil surveys using the:","options":["Richter scale, with logarithmic magnitude","Munsell colour chart, with hue, value and chroma","Beaufort scale, with force and wind speed","Mohs scale, with relative hardness"],"answer":1,"explanation":"The Munsell chart notes colour as hue (the spectral colour), value (lightness) and chroma (strength), such as 10YR 4/3 for a brown soil. Beaufort, Mohs and Richter measure wind, mineral hardness and earthquakes.","difficulty":"moderate","questionHi":"क्षेत्र में और मृदा सर्वेक्षणों में मृदा का रंग किसके द्वारा वर्णित किया जाता है?","optionsHi":["रिक्टर पैमाना, जिसमें लघुगणकीय परिमाण होता है","मंसेल रंग चार्ट, जिसमें ह्यू, वैल्यू और क्रोमा होते हैं","ब्यूफोर्ट पैमाना, जिसमें बल और पवन गति होती है","मोह्स पैमाना, जिसमें सापेक्ष कठोरता होती है"],"explanationHi":"मंसेल चार्ट रंग को ह्यू (वर्णक्रमीय रंग), वैल्यू (चमक) और क्रोमा (प्रबलता) में लिखता है, जैसे भूरी मृदा के लिए 10YR 4/3। ब्यूफोर्ट, मोह्स और रिक्टर पवन, खनिज कठोरता और भूकंप को मापते हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-soils-agriculture-158","question":"In Jenny's model of soil formation, which of these is a PASSIVE factor, one that supplies the material or the time rather than actively changing it?","options":["Climate, acting through rainfall and temperature","Rainfall and temperature, acting on the parent rock","Parent material, together with relief and time","Living organisms, such as vegetation and microbes"],"answer":2,"explanation":"Jenny's five factors are climate, organisms, relief, parent material and time. The active ones (climate, organisms) drive the changes, and the passive ones (parent material, relief, time) provide the base material, the setting and the duration.","difficulty":"very-hard","questionHi":"जेनी के मृदा निर्माण प्रतिरूप में इनमें से कौन-सा एक निष्क्रिय कारक है, जो सामग्री या समय देता है, न कि उसे सक्रिय रूप से बदलता है?","optionsHi":["जलवायु, जो वर्षा और तापमान के माध्यम से कार्य करती है","वर्षा और तापमान, जो मूल चट्टान पर कार्य करते हैं","मूल पदार्थ, साथ में उच्चावच और समय","जीवित जीव, जैसे वनस्पति और सूक्ष्मजीव"],"explanationHi":"जेनी के पाँच कारक जलवायु, जीव, उच्चावच, मूल पदार्थ और समय हैं। सक्रिय कारक (जलवायु, जीव) परिवर्तन चलाते हैं, और निष्क्रिय कारक (मूल पदार्थ, उच्चावच, समय) आधार सामग्री, स्थिति और अवधि देते हैं।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-soils-agriculture-159","question":"Illuviation, the accumulation of clay and iron compounds washed down from above, occurs mainly in the:","options":["O horizon","E horizon","A horizon","B horizon"],"answer":3,"explanation":"Water leaches (eluviates) clay, iron and aluminium out of the upper A and E horizons and deposits them in the B horizon, the zone of illuviation. The O horizon is the surface layer of organic matter.","difficulty":"hard","questionHi":"निक्षेपण (इल्यूवियेशन), अर्थात ऊपर से धुलकर आई मृत्तिका और लौह यौगिकों का जमाव, मुख्यतः किस संस्तर में होता है?","optionsHi":["O संस्तर","E संस्तर","A संस्तर","B संस्तर"],"explanationHi":"जल ऊपरी A और E संस्तरों से मृत्तिका, लोहा और एल्युमिनियम को बहा ले जाता है (निक्षालन) और B संस्तर में जमा करता है, जो निक्षेपण का क्षेत्र है। O संस्तर कार्बनिक पदार्थ की सतही परत है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-soils-agriculture-160","question":"Which form of soil water is the main source of water for plants?","options":["Capillary water held in the micropores","Hygroscopic water held tightly as a film on soil particles","Gravitational water that drains below the roots in a day or two","Chemically combined water in the crystal structure of clay"],"answer":0,"explanation":"Plants draw mostly on capillary water between field capacity and wilting point. Gravitational water drains away quickly, and hygroscopic and combined water are held too strongly for roots to take up.","difficulty":"moderate","questionHi":"मृदा जल का कौन-सा रूप पौधों के लिए जल का मुख्य स्रोत है?","optionsHi":["सूक्ष्म छिद्रों में रुका केशिका जल","आर्द्रताग्राही जल जो मृदा कणों पर परत के रूप में कसकर बँधा रहता है","गुरुत्वीय जल जो एक-दो दिन में जड़ों के नीचे बह जाता है","मृत्तिका की क्रिस्टल संरचना में रासायनिक रूप से संयुक्त जल"],"explanationHi":"पौधे मुख्यतः क्षेत्र क्षमता और म्लानि बिंदु के बीच के केशिका जल पर निर्भर रहते हैं। गुरुत्वीय जल जल्दी बह जाता है, और आर्द्रताग्राही तथा संयुक्त जल इतनी दृढ़ता से बँधे होते हैं कि जड़ें उन्हें नहीं ले पातीं।","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-soils-agriculture-161","question":"The permanent wilting point is conventionally taken as the soil moisture content held at a tension of about:","options":["0.33 bar (one-third atmosphere)","15 bar (atmospheres)","1 bar","50 bar"],"answer":1,"explanation":"Field capacity corresponds to roughly one-third bar tension, and the permanent wilting point to about 15 bar, beyond which most crop roots cannot extract water. Available water is the moisture held between these two limits.","difficulty":"hard","questionHi":"स्थायी म्लानि बिंदु को परंपरागत रूप से लगभग किस तनाव पर रुकी मृदा नमी के रूप में लिया जाता है?","optionsHi":["0.33 बार (एक-तिहाई वायुमंडल)","15 बार (वायुमंडल)","1 बार","50 बार"],"explanationHi":"क्षेत्र क्षमता लगभग एक-तिहाई बार तनाव के संगत है और स्थायी म्लानि बिंदु लगभग 15 बार के, जिसके आगे अधिकांश फसलों की जड़ें जल नहीं खींच पातीं। उपलब्ध जल इन्हीं दोनों सीमाओं के बीच रुकी नमी है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-soils-agriculture-162","question":"Winter wheat varieties flower properly only after the young plants have been exposed to a spell of low temperature. This requirement is called:","options":["Stratification","Etiolation","Vernalisation","Photoperiodism"],"answer":2,"explanation":"Vernalisation is the chilling of seeds or seedlings that makes a plant ready to flower, as with winter wheat sown in autumn. Photoperiodism is the response to day length, and stratification chills seeds to break dormancy.","difficulty":"hard","questionHi":"शीतकालीन गेहूँ की किस्में तभी ठीक से फूलती हैं जब नन्हे पौधे कुछ समय निम्न तापमान के संपर्क में आ चुके हों। इस आवश्यकता को कहते हैं:","optionsHi":["स्तरीकरण","पांडुरता (एटिओलेशन)","बसंतीकरण (वर्नलीकरण)","प्रकाशकालिता"],"explanationHi":"बसंतीकरण बीजों या अंकुरों को ठंडा करना है जिससे पौधा फूलने योग्य बनता है, जैसे शरद में बोया जाने वाला शीतकालीन गेहूँ। प्रकाशकालिता दिन की लंबाई की प्रतिक्रिया है और स्तरीकरण बीजों की सुषुप्ति तोड़ने के लिए उन्हें ठंडा करना है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-soils-agriculture-163","question":"Which of these crops is a long-day plant, flowering when the day is longer than a critical length?","options":["Sorghum","Rice (photoperiod-sensitive varieties)","Soybean","Wheat"],"answer":3,"explanation":"Wheat and barley are long-day plants, flowering as days lengthen in spring. Photoperiod-sensitive rice, soybean and sorghum are short-day plants, which is why many are sown in kharif and flower as days shorten.","difficulty":"hard","questionHi":"इनमें से कौन-सी फसल दीर्घ-दिवस पौधा है, जो दिन की लंबाई एक क्रांतिक सीमा से अधिक होने पर फूलती है?","optionsHi":["ज्वार","चावल (प्रकाशकाल-संवेदी किस्में)","सोयाबीन","गेहूँ"],"explanationHi":"गेहूँ और जौ दीर्घ-दिवस पौधे हैं, जो वसंत में दिन लंबे होने पर फूलते हैं। प्रकाशकाल-संवेदी चावल, सोयाबीन और ज्वार लघु-दिवस पौधे हैं, इसीलिए इनमें से कई खरीफ में बोए जाते हैं और दिन छोटे होने पर फूलते हैं।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-soils-agriculture-164","question":"Which group of crops consists only of C4 plants?","options":["Sugarcane, sorghum and pearl millet","Wheat, rice, barley, oats, rye and gram","Maize, groundnut, soybean and cotton","Rice, maize, sugarcane and finger millet"],"answer":0,"explanation":"Sugarcane, sorghum, pearl millet and maize use the C4 pathway, which suits hot, bright conditions. Wheat, rice, barley, groundnut and soybean are C3 plants, so the mixed groups each include at least one C3 crop.","difficulty":"very-hard","questionHi":"फसलों के किस समूह में केवल C4 पौधे हैं?","optionsHi":["गन्ना, ज्वार और बाजरा","गेहूँ, चावल, जौ, जई, राई और चना","मक्का, मूँगफली, सोयाबीन और कपास","चावल, मक्का, गन्ना और रागी"],"explanationHi":"गन्ना, ज्वार, बाजरा और मक्का C4 पथ अपनाते हैं, जो गर्म और तेज़ धूप की स्थितियों के अनुकूल है। गेहूँ, चावल, जौ, मूँगफली और सोयाबीन C3 पौधे हैं, इसलिए मिश्रित समूहों में कम से कम एक C3 फसल है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-soils-agriculture-165","question":"Which of these is a micronutrient for plants rather than a primary or secondary nutrient?","options":["Magnesium","Zinc","Calcium","Sulphur"],"answer":1,"explanation":"Zinc, with iron, manganese, copper, boron, molybdenum and chlorine, is a micronutrient needed in tiny amounts. Nitrogen, phosphorus and potassium are primary nutrients, and calcium, magnesium and sulphur are secondary.","difficulty":"moderate","questionHi":"इनमें से कौन-सा पौधों के लिए सूक्ष्म पोषक तत्व है, न कि प्राथमिक या द्वितीयक पोषक तत्व?","optionsHi":["मैग्नीशियम","जिंक","कैल्शियम","सल्फर"],"explanationHi":"जिंक, लोहा, मैंगनीज, तांबा, बोरॉन, मॉलिब्डेनम और क्लोरीन के साथ, सूक्ष्म पोषक तत्व है जो बहुत कम मात्रा में चाहिए। नाइट्रोजन, फॉस्फोरस और पोटैशियम प्राथमिक तथा कैल्शियम, मैग्नीशियम और सल्फर द्वितीयक पोषक तत्व हैं।","source":"SSC CGL · State PCS"},
  {"id":"geo-soils-agriculture-166","question":"Match the disorder with the nutrient deficiency that causes it. A. Whiptail of cauliflower  B. Little leaf of brinjal  C. Heart rot of sugar beet  D. Iron-deficiency chlorosis. 1. Boron  2. Molybdenum  3. Zinc  4. Interveinal yellowing of young leaves","options":["A-2, B-1, C-3, D-4","A-3, B-2, C-1, D-4","A-2, B-3, C-1, D-4","A-2, B-3, C-4, D-1"],"answer":2,"explanation":"Whiptail (narrow, strap-like leaves) comes from molybdenum shortage, little leaf from zinc, and heart rot of beet from boron. Iron deficiency shows as yellowing between the veins of the youngest leaves.","difficulty":"very-hard","questionHi":"विकार का उसके कारण पोषक तत्व की कमी से मिलान कीजिए। A. फूलगोभी का व्हिपटेल  B. बैंगन का छोटी पत्ती रोग  C. चुकंदर का हार्ट रॉट  D. लौह-अल्पता से हरिमाहीनता। 1. बोरॉन  2. मॉलिब्डेनम  3. जिंक  4. नई पत्तियों की शिराओं के बीच पीलापन","optionsHi":["A-2, B-1, C-3, D-4","A-3, B-2, C-1, D-4","A-2, B-3, C-1, D-4","A-2, B-3, C-4, D-1"],"explanationHi":"व्हिपटेल (संकरी, पट्टी जैसी पत्तियाँ) मॉलिब्डेनम की कमी से, छोटी पत्ती रोग जिंक से और चुकंदर का हार्ट रॉट बोरॉन से होता है। लौह की कमी सबसे नई पत्तियों की शिराओं के बीच पीलेपन के रूप में दिखती है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-soils-agriculture-167","question":"After urea is applied to a well-drained field, which bacteria convert the nitrite formed by Nitrosomonas into nitrate?","options":["Azotobacter","Rhizobium","Pseudomonas","Nitrobacter"],"answer":3,"explanation":"Urea is hydrolysed to ammonium, Nitrosomonas oxidises ammonium to nitrite, and Nitrobacter completes nitrification by oxidising nitrite to nitrate, the form most readily taken up and also leached. Azotobacter and Rhizobium fix nitrogen.","difficulty":"hard","questionHi":"अच्छे जल निकास वाले खेत में यूरिया डालने के बाद, नाइट्रोसोमोनास द्वारा बने नाइट्राइट को कौन-से जीवाणु नाइट्रेट में बदलते हैं?","optionsHi":["एज़ोटोबैक्टर","राइज़ोबियम","स्यूडोमोनास","नाइट्रोबैक्टर"],"explanationHi":"यूरिया का जल-अपघटन होकर अमोनियम बनता है, नाइट्रोसोमोनास अमोनियम को नाइट्राइट में ऑक्सीकृत करता है, और नाइट्रोबैक्टर नाइट्राइट को नाइट्रेट में ऑक्सीकृत कर नाइट्रीकरण पूरा करता है, जो सबसे आसानी से लिया जाने वाला और बहने वाला रूप है। एज़ोटोबैक्टर और राइज़ोबियम नाइट्रोजन स्थिरीकरण करते हैं।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-soils-agriculture-168","question":"Nitrate-based nitrogen fertilisers are a poor choice for standing water in transplanted paddy, mainly because in the waterlogged soil:","options":["Nitrate is lost as nitrogen gas by denitrification","Nitrate is converted into urea by soil enzymes","Nitrate becomes toxic to rice roots at neutral pH","Nitrate is locked up as insoluble iron phosphate"],"answer":0,"explanation":"In the oxygen-free puddled layer, denitrifying bacteria use nitrate and release nitrogen and nitrous oxide to the air. Ammonium or urea placed in the reduced layer is retained, which is why deep placement of urea briquettes works well in paddy.","difficulty":"very-hard","questionHi":"रोपित धान के खड़े पानी में नाइट्रेट-आधारित नाइट्रोजन उर्वरक एक खराब विकल्प हैं, मुख्यतः क्योंकि जलमग्न मृदा में:","optionsHi":["विनाइट्रीकरण से नाइट्रेट नाइट्रोजन गैस के रूप में नष्ट हो जाता है","मृदा एंज़ाइम नाइट्रेट को यूरिया में बदल देते हैं","उदासीन pH पर नाइट्रेट धान की जड़ों के लिए विषैला हो जाता है","नाइट्रेट अघुलनशील आयरन फॉस्फेट के रूप में बँध जाता है"],"explanationHi":"ऑक्सीजन-रहित कीचड़ की परत में विनाइट्रीकारी जीवाणु नाइट्रेट प्रयोग कर नाइट्रोजन और नाइट्रस ऑक्साइड हवा में छोड़ते हैं। अपचयित परत में रखा अमोनियम या यूरिया रुका रहता है, इसीलिए धान में यूरिया गुटिकाओं का गहरा स्थापन अच्छा काम करता है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-soils-agriculture-169","question":"Which measure is aimed mainly at controlling gully erosion, rather than sheet erosion, in ravine-prone land?","options":["Strip cropping with alternate grass strips on gentle slopes","Check dams built of stone or brushwood across the gully","Contour ploughing across the slope of the cultivated fields","Mulching the soil surface with a layer of crop residue and straw"],"answer":1,"explanation":"Check dams slow the water running in the gully and trap silt, healing the channel itself. Contour ploughing, mulching and strip cropping protect open fields from sheet and rill erosion by reducing the surface flow.","difficulty":"hard","questionHi":"बीहड़-प्रवण भूमि में कौन-सा उपाय मुख्यतः चादर अपरदन के बजाय अवनालिका अपरदन को रोकने के लिए है?","optionsHi":["मंद ढालों पर पट्टीदार खेती","अवनालिका के आर-पार पत्थर या झाड़ियों से बने रोक बाँध","ढाल के आर-पार समोच्च जुताई","फसल अवशेष से मृदा सतह को ढकना (पलवार)"],"explanationHi":"रोक बाँध अवनालिका में बहता जल धीमा करते हैं और गाद रोकते हैं, जिससे नाली स्वयं भर जाती है। समोच्च जुताई, पलवार और पट्टीदार खेती सतही प्रवाह घटाकर खुले खेतों को चादर और धारा अपरदन से बचाती हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-soils-agriculture-170","question":"Conservation agriculture rests on three linked principles. Which of these lists them correctly?","options":["Deep ploughing every season, clean fallow, and monoculture with heavy fertiliser doses","Contour bunding, terracing on slopes, and shifting cultivation in the hill regions with long fallow","Minimum soil disturbance, permanent soil cover, and crop rotation or diversification","Flood irrigation every week, burning of crop residue, and continuous cropping of a single crop"],"answer":2,"explanation":"FAO's conservation agriculture combines minimum tillage or no-till, a permanent mulch of crop residue, and diversified rotations, as in zero-till wheat sown into rice stubble. Residue burning and clean fallow are the opposite.","difficulty":"hard","questionHi":"संरक्षण कृषि तीन परस्पर जुड़े सिद्धांतों पर आधारित है। इनमें से कौन-सी सूची उन्हें सही बताती है?","optionsHi":["गहरी जुताई, स्वच्छ परती, और भारी उर्वरक के साथ एकल फसल","समोच्च मेड़बंदी, सीढ़ीदार खेत, और स्थानांतरी कृषि","न्यूनतम मृदा विक्षोभ, स्थायी मृदा आवरण, और फसल चक्र या विविधीकरण","बाढ़ सिंचाई, अवशेष जलाना, और निरंतर फसल लेना"],"explanationHi":"FAO की संरक्षण कृषि न्यूनतम जुताई या शून्य जुताई, फसल अवशेष की स्थायी पलवार और विविध फसल चक्र को जोड़ती है, जैसे धान के ठूँठ में बोया गया शून्य जुताई गेहूँ। अवशेष जलाना और स्वच्छ परती इसके उलट हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-soils-agriculture-171","question":"Match the world soil with the region or setting where it is typical. A. Chernozem  B. Podzol  C. Terra rossa  D. Laterite. 1. Mediterranean limestone lands  2. Humid tropics with heavy leaching  3. Temperate grasslands such as the Ukrainian steppe  4. Cool coniferous (taiga) forests","options":["A-3, B-1, C-4, D-2","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-4, C-1, D-2"],"answer":3,"explanation":"Chernozem, the dark humus-rich soil, belongs to temperate steppes, podzol to acidic taiga forests, terra rossa to red soils on Mediterranean limestone, and laterite to hot, humid tropical regions.","difficulty":"hard","questionHi":"विश्व की मृदा का उस क्षेत्र या परिवेश से मिलान कीजिए जहाँ वह विशिष्ट है। A. चर्नोज़म  B. पॉडज़ॉल  C. टेरा रोसा  D. लैटेराइट। 1. भूमध्यसागरीय चूना पत्थर वाली भूमि  2. भारी निक्षालन वाले आर्द्र उष्णकटिबंध  3. यूक्रेन के स्टेपी जैसे शीतोष्ण घास के मैदान  4. शीतल शंकुधारी (टैगा) वन","optionsHi":["A-3, B-1, C-4, D-2","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-4, C-1, D-2"],"explanationHi":"चर्नोज़म, गहरे ह्यूमस-समृद्ध रंग वाली मृदा, शीतोष्ण स्टेपी की है, पॉडज़ॉल अम्लीय टैगा वनों की, टेरा रोसा भूमध्यसागरीय चूना पत्थर पर लाल मृदा है, और लैटेराइट गर्म, आर्द्र उष्णकटिबंधीय क्षेत्रों की है।","source":"UPSC Prelims · UPSC Geography Optional"},
  {"id":"geo-soils-agriculture-172","question":"Relay cropping, as in the 'utera' or 'paira' practice in rice fields of eastern India, means:","options":["Sowing the next crop, such as lentil or lathyrus, in the standing rice before it is harvested","Growing the same crop on the same piece of land year after year without any rotation or break","Growing two different crops together in separate alternating rows during the very same season","Cutting a crop at the base and allowing the stubble to regrow to give a second full harvest later"],"answer":0,"explanation":"In relay cropping the second crop is sown into the standing first crop near its maturity, using the residual moisture, as with lentil or grass pea in rice. Intercropping is row-wise growing together, and ratooning is regrowth from stubble.","difficulty":"very-hard","questionHi":"रिले फसल (रिले क्रॉपिंग), जैसे पूर्वी भारत के धान के खेतों में 'उतेरा' या 'पैरा' पद्धति, का अर्थ है:","optionsHi":["खड़े धान में उसकी कटाई से पहले अगली फसल, जैसे मसूर या खेसारी, बो देना","एक ही भूमि पर कई वर्ष तक एक ही फसल उगाना","एक ही मौसम में अलग-अलग पंक्तियों में दो फसलें उगाना","फसल काटकर ठूँठ को दूसरी कटाई के लिए पुनः उगने देना"],"explanationHi":"रिले फसल में दूसरी फसल पहली खड़ी फसल में उसकी परिपक्वता के निकट बोई जाती है और अवशिष्ट नमी का उपयोग करती है, जैसे धान में मसूर या खेसारी। अंतःफसल एक साथ पंक्तियों में उगाना है और रैटूनिंग ठूँठ से पुनः उगना है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-soils-agriculture-173","question":"In north India, wheat sown very late, in late December, usually gives a lower yield mainly because:","options":["The seeds fail to germinate properly at the low winter temperatures of late December in the plains","Grain filling coincides with rising March temperatures, causing terminal heat stress","Frost kills most of the crop at the seedling stage in the coldest part of January every year","The crop receives far too much rain during flowering and grain setting in the month of March in most years"],"answer":1,"explanation":"Late-sown wheat has a shortened grain-filling period which meets the heat of March and April, so grains shrivel and yield falls. Seeds do germinate in winter, and rainfall in February-March is not the usual cause.","difficulty":"hard","questionHi":"उत्तर भारत में दिसंबर के अंत में बहुत देर से बोया गया गेहूँ प्रायः कम उपज देता है, मुख्यतः क्योंकि:","optionsHi":["निम्न शीतकालीन तापमान पर बीज अंकुरित नहीं हो पाते","दाना भरने का समय मार्च के बढ़ते तापमान से टकराता है, जिससे अंतिम अवस्था में ऊष्मा तनाव होता है","जनवरी में पाला अंकुर अवस्था में फसल को मार देता है","पुष्पन के समय फसल को बहुत अधिक वर्षा मिलती है"],"explanationHi":"देर से बोए गेहूँ में दाना भरने की अवधि छोटी हो जाती है और वह मार्च-अप्रैल की गर्मी से टकराती है, इसलिए दाने सिकुड़ते हैं और उपज घटती है। बीज शीत में अंकुरित होते हैं, और फरवरी-मार्च की वर्षा सामान्य कारण नहीं है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-soils-agriculture-174","question":"Match the crop with the way it is usually propagated. A. Sugarcane  B. Potato  C. Banana  D. Turmeric. 1. Suckers  2. Rhizomes  3. Stem cuttings (setts) with buds  4. Tubers","options":["A-3, B-4, C-2, D-1","A-3, B-2, C-1, D-4","A-3, B-4, C-1, D-2","A-4, B-3, C-2, D-1"],"answer":2,"explanation":"Sugarcane is planted as setts, stem pieces carrying buds, potato as tubers, banana as suckers from the mother plant, and turmeric as rhizomes. None of these is raised from seed commercially.","difficulty":"hard","questionHi":"फसल का उसकी सामान्य प्रवर्धन विधि से मिलान कीजिए। A. गन्ना  B. आलू  C. केला  D. हल्दी। 1. चूषक (सकर)  2. प्रकंद  3. कलिकाओं वाले तना कटिंग (सेट)  4. कंद","optionsHi":["A-3, B-4, C-2, D-1","A-3, B-2, C-1, D-4","A-3, B-4, C-1, D-2","A-4, B-3, C-2, D-1"],"explanationHi":"गन्ना कलिकाओं वाले तने के टुकड़ों (सेट) से, आलू कंदों से, केला मातृ पौधे के चूषकों से और हल्दी प्रकंदों से लगाई जाती है। इनमें से किसी को भी व्यावसायिक रूप से बीज से नहीं उगाया जाता।","source":"State PCS · SSC CGL"},
  {"id":"geo-soils-agriculture-175","question":"Match the Kerala paddy season with its timing. A. Virippu  B. Mundakan  C. Punja. 1. Sown in September-October and harvested in December-January  2. Sown in April-May and harvested in August-September  3. Sown in December-January and harvested in March-April","options":["A-3, B-1, C-2","A-1, B-2, C-3","A-2, B-3, C-1","A-2, B-1, C-3"],"answer":3,"explanation":"Virippu is the first or autumn crop, sown in April-May with the pre-monsoon showers; Mundakan is the second crop of the winter, sown in September-October; and Punja is the summer crop of Kuttanad, sown in December-January.","difficulty":"very-hard","questionHi":"केरल की धान ऋतु का उसके समय से मिलान कीजिए। A. विरिप्पु  B. मुंडकन  C. पुंजा। 1. सितंबर-अक्टूबर में बोई और दिसंबर-जनवरी में कटी  2. अप्रैल-मई में बोई और अगस्त-सितंबर में कटी  3. दिसंबर-जनवरी में बोई और मार्च-अप्रैल में कटी","optionsHi":["A-3, B-1, C-2","A-1, B-2, C-3","A-2, B-3, C-1","A-2, B-1, C-3"],"explanationHi":"विरिप्पु पहली या शरद की फसल है, जो मानसून पूर्व की बौछारों के साथ अप्रैल-मई में बोई जाती है; मुंडकन शीत की दूसरी फसल है, जो सितंबर-अक्टूबर में बोई जाती है; और पुंजा कुट्टनाड की ग्रीष्म फसल है, जो दिसंबर-जनवरी में बोई जाती है।","source":"State PCS · UPSC Prelims"},
  {"id":"geo-soils-agriculture-176","question":"In the Cauvery delta of Tamil Nadu, the short-duration paddy crop sown around June and harvested by September is called:","options":["Kuruvai","Samba","Navarai","Thaladi"],"answer":0,"explanation":"Kuruvai is the short-duration crop of June to September, Samba the main long-duration crop sown in August and harvested in January, and Thaladi a late crop following Kuruvai. Navarai belongs to a different winter-to-summer season.","difficulty":"very-hard","questionHi":"तमिलनाडु के कावेरी डेल्टा में जून के आसपास बोई और सितंबर तक कटने वाली अल्पावधि धान की फसल क्या कहलाती है?","optionsHi":["कुरुवै","सांबा","नवरै","थलादी"],"explanationHi":"कुरुवै जून से सितंबर की अल्पावधि फसल है, सांबा अगस्त में बोई और जनवरी में कटने वाली मुख्य दीर्घावधि फसल है, और थलादी कुरुवै के बाद की देर की फसल है। नवरै शीत से ग्रीष्म की एक अलग ऋतु से संबंधित है।","source":"State PCS · UPSC Prelims"},
  {"id":"geo-soils-agriculture-177","question":"The dwarfing genes that made the high-yielding wheat varieties of the Green Revolution short and resistant to lodging came from the Japanese variety:","options":["Lerma Rojo","Norin 10","Sonalika","Kalyan Sona"],"answer":1,"explanation":"Norin 10, a dwarf Japanese wheat, was crossed with Mexican lines by Norman Borlaug's team to give semi-dwarf varieties, which Indian breeders used for Sonalika and Kalyan Sona. Those two, and Lerma Rojo, are products of the programme, not the source of the genes.","difficulty":"very-hard","questionHi":"हरित क्रांति के उच्च उपज वाले गेहूँ की किस्मों को बौना और गिरने से प्रतिरोधी बनाने वाले बौनेपन के जीन किस जापानी किस्म से आए?","optionsHi":["लर्मा रोजो","नोरिन 10","सोनालिका","कल्याण सोना"],"explanationHi":"नोरिन 10, एक बौना जापानी गेहूँ, को नॉर्मन बोरलॉग की टीम ने मैक्सिको की किस्मों से संकरित कर अर्ध-बौनी किस्में बनाईं, जिन्हें भारतीय प्रजनकों ने सोनालिका और कल्याण सोना के लिए प्रयोग किया। वे दोनों और लर्मा रोजो कार्यक्रम की उपज हैं, जीनों के स्रोत नहीं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-soils-agriculture-178","question":"In India's seed certification system, which tag colour marks certified seed?","options":["Golden yellow","White","Azure blue","Opal green"],"answer":2,"explanation":"Breeder seed carries a golden yellow tag, foundation seed a white tag, and certified seed an azure blue tag. Truthfully labelled seed, which is not certified, carries an opal green tag.","difficulty":"hard","questionHi":"भारत की बीज प्रमाणीकरण प्रणाली में प्रमाणित बीज को किस रंग का टैग चिह्नित करता है?","optionsHi":["सुनहरा पीला","सफ़ेद","आसमानी नीला","ओपल हरा"],"explanationHi":"प्रजनक बीज पर सुनहरा पीला टैग, आधार बीज पर सफ़ेद टैग और प्रमाणित बीज पर आसमानी नीला टैग होता है। सत्य-चिह्नित बीज, जो प्रमाणित नहीं होता, पर ओपल हरा टैग होता है।","source":"State PCS · SSC CGL"},
  {"id":"geo-soils-agriculture-179","question":"Which of these fruits is climacteric, ripening further after harvest under the action of ethylene?","options":["Grape","Orange","Pineapple","Mango"],"answer":3,"explanation":"Mango, banana, apple, papaya and tomato are climacteric, with a burst of ethylene and respiration at ripening, so they can be harvested mature and ripened later. Grape, citrus and pineapple are non-climacteric and do not ripen after harvest.","difficulty":"hard","questionHi":"इनमें से कौन-सा फल क्लाइमैक्टेरिक है, जो इथाइलीन की क्रिया से तुड़ाई के बाद भी पकता है?","optionsHi":["अंगूर","संतरा","अनानास","आम"],"explanationHi":"आम, केला, सेब, पपीता और टमाटर क्लाइमैक्टेरिक हैं, जिनके पकने पर इथाइलीन और श्वसन में उछाल आता है, इसलिए उन्हें परिपक्व अवस्था में तोड़कर बाद में पकाया जा सकता है। अंगूर, नीबू-वर्गीय फल और अनानास अक्लाइमैक्टेरिक हैं और तुड़ाई के बाद नहीं पकते।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-soils-agriculture-180","question":"Match the ICAR institute with its location. A. Central Plantation Crops Research Institute  B. Central Rice Research Institute (National Rice Research Institute)  C. National Dairy Research Institute  D. Indian Institute of Spices Research. 1. Cuttack  2. Kozhikode  3. Karnal  4. Kasaragod","options":["A-4, B-1, C-3, D-2","A-1, B-4, C-3, D-2","A-4, B-3, C-1, D-2","A-4, B-1, C-2, D-3"],"answer":0,"explanation":"The plantation crops institute (coconut, arecanut, cocoa) is at Kasaragod in Kerala, the rice institute at Cuttack in Odisha, the dairy institute at Karnal in Haryana, and the spices institute at Kozhikode in Kerala. Kasaragod and Kozhikode are easily swapped.","difficulty":"hard","questionHi":"ICAR संस्थान का उसके स्थान से मिलान कीजिए। A. केंद्रीय रोपण फसल अनुसंधान संस्थान  B. केंद्रीय चावल अनुसंधान संस्थान (राष्ट्रीय चावल अनुसंधान संस्थान)  C. राष्ट्रीय डेयरी अनुसंधान संस्थान  D. भारतीय मसाला अनुसंधान संस्थान। 1. कटक  2. कोझिकोड  3. करनाल  4. कासरगोड","optionsHi":["A-4, B-1, C-3, D-2","A-1, B-4, C-3, D-2","A-4, B-3, C-1, D-2","A-4, B-1, C-2, D-3"],"explanationHi":"रोपण फसलों (नारियल, सुपारी, कोको) का संस्थान केरल के कासरगोड में, चावल संस्थान ओडिशा के कटक में, डेयरी संस्थान हरियाणा के करनाल में और मसाला संस्थान केरल के कोझिकोड में है। कासरगोड और कोझिकोड की अदला-बदली आसान है।","source":"State PCS · SSC CGL"},
  {"id":"geo-soils-agriculture-181","question":"The National Bureau of Soil Survey and Land Use Planning (Nagpur) has divided India into how many agro-ecological regions?","options":["60","20","15","8"],"answer":1,"explanation":"NBSS&LUP delineated 20 agro-ecological regions and 60 sub-regions, based on soil, climate, physiography and length of the growing period. The Planning Commission's separate scheme had 15 agro-climatic regions, and 8 is the number of major NCERT soil groups.","difficulty":"very-hard","questionHi":"राष्ट्रीय मृदा सर्वेक्षण एवं भू-उपयोग नियोजन ब्यूरो (नागपुर) ने भारत को कितने कृषि-पारिस्थितिक क्षेत्रों में बाँटा है?","optionsHi":["60","20","15","8"],"explanationHi":"NBSS&LUP ने मृदा, जलवायु, भू-आकृति और वर्धन अवधि के आधार पर 20 कृषि-पारिस्थितिक क्षेत्र और 60 उप-क्षेत्र निर्धारित किए। योजना आयोग की अलग योजना में 15 कृषि-जलवायु क्षेत्र थे, और 8 NCERT के प्रमुख मृदा समूहों की संख्या है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-soils-agriculture-182","question":"The Agricultural Prices Commission, forerunner of the Commission for Agricultural Costs and Prices that recommends Minimum Support Prices, was set up in:","options":["1951","1971","1965","1957"],"answer":2,"explanation":"The Agricultural Prices Commission was set up in January 1965, the same year as the Food Corporation of India, and it was renamed the Commission for Agricultural Costs and Prices in 1985.","difficulty":"hard","questionHi":"कृषि मूल्य आयोग, जो न्यूनतम समर्थन मूल्य की अनुशंसा करने वाले कृषि लागत एवं मूल्य आयोग का पूर्ववर्ती था, किस वर्ष स्थापित हुआ?","optionsHi":["1951","1971","1965","1957"],"explanationHi":"कृषि मूल्य आयोग जनवरी 1965 में बना, उसी वर्ष जब भारतीय खाद्य निगम बना, और 1985 में इसका नाम कृषि लागत एवं मूल्य आयोग रखा गया।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-soils-agriculture-183","question":"The Imperial Council of Agricultural Research, now the Indian Council of Agricultural Research, was set up in which year, following the recommendations of the Royal Commission on Agriculture?","options":["1936","1926","1905","1929"],"answer":3,"explanation":"The Royal Commission on Agriculture reported in 1928 after being appointed in 1926, and the Imperial Council of Agricultural Research was established in 1929. The Imperial Agricultural Research Institute at Pusa dates from 1905.","difficulty":"very-hard","questionHi":"इंपीरियल काउंसिल ऑफ एग्रीकल्चरल रिसर्च, जो अब भारतीय कृषि अनुसंधान परिषद है, कृषि पर रॉयल आयोग की सिफारिशों के बाद किस वर्ष स्थापित हुई?","optionsHi":["1936","1926","1905","1929"],"explanationHi":"कृषि पर रॉयल आयोग ने 1926 में नियुक्त होने के बाद 1928 में रिपोर्ट दी, और इंपीरियल काउंसिल ऑफ एग्रीकल्चरल रिसर्च 1929 में स्थापित हुई। पूसा का इंपीरियल कृषि अनुसंधान संस्थान 1905 का है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-soils-agriculture-184","question":"The Indian Agricultural Research Institute, founded at Pusa in Bihar in 1905, was moved to New Delhi in 1936 mainly because:","options":["The 1934 Bihar earthquake badly damaged its buildings","The capital moved from Calcutta to Delhi in 1911","Floods on the Gandak river repeatedly submerged the campus","A plague epidemic had emptied the Pusa estate"],"answer":0,"explanation":"The great Bihar-Nepal earthquake of January 1934 wrecked the Pusa buildings, and the Institute was relocated to Delhi in 1936. That is why it is still called the Pusa Institute and its varieties carry 'Pusa' names.","difficulty":"very-hard","questionHi":"भारतीय कृषि अनुसंधान संस्थान, जो 1905 में बिहार के पूसा में स्थापित हुआ, 1936 में नई दिल्ली क्यों स्थानांतरित किया गया?","optionsHi":["1934 के बिहार भूकंप ने उसकी इमारतों को बुरी तरह क्षतिग्रस्त कर दिया","1911 में राजधानी कलकत्ता से दिल्ली चली गई थी","गंडक नदी की बाढ़ ने परिसर को बार-बार डुबोया","प्लेग महामारी ने पूसा की जागीर को खाली कर दिया था"],"explanationHi":"जनवरी 1934 के महान बिहार–नेपाल भूकंप ने पूसा की इमारतें नष्ट कर दीं और संस्थान 1936 में दिल्ली ले जाया गया। इसीलिए इसे आज भी पूसा संस्थान कहते हैं और इसकी किस्मों के नाम 'पूसा' से शुरू होते हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-soils-agriculture-185","question":"India's first agricultural university, set up in 1960 on the land-grant model of the United States, is:","options":["Punjab Agricultural University at Ludhiana, set up in the early 1960s","G. B. Pant University of Agriculture and Technology, Pantnagar","Tamil Nadu Agricultural University at Coimbatore, set up in the early 1970s","Indian Agricultural Research Institute at Pusa, New Delhi, set up in 1905"],"answer":1,"explanation":"G. B. Pant University at Pantnagar (then in Uttar Pradesh, now in Uttarakhand) was India's first agricultural university, in 1960, and a model for those that followed. Punjab Agricultural University at Ludhiana came in 1962.","difficulty":"hard","questionHi":"भारत का पहला कृषि विश्वविद्यालय, जो 1960 में अमेरिका के भू-अनुदान प्रतिरूप पर बना, कौन-सा है?","optionsHi":["पंजाब कृषि विश्वविद्यालय, लुधियाना","गोविंद बल्लभ पंत कृषि एवं प्रौद्योगिकी विश्वविद्यालय, पंतनगर","तमिलनाडु कृषि विश्वविद्यालय, कोयंबटूर","भारतीय कृषि अनुसंधान संस्थान, नई दिल्ली"],"explanationHi":"पंतनगर (तब उत्तर प्रदेश में, अब उत्तराखंड में) का गोविंद बल्लभ पंत विश्वविद्यालय 1960 में भारत का पहला कृषि विश्वविद्यालय था और बाद के विश्वविद्यालयों के लिए आदर्श बना। लुधियाना का पंजाब कृषि विश्वविद्यालय 1962 में आया।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-soils-agriculture-186","question":"The first Krishi Vigyan Kendra, a farm science centre for training and on-farm testing, was set up in 1974 at:","options":["Pusa, Bihar","Anand, Gujarat","Puducherry","Ludhiana, Punjab"],"answer":2,"explanation":"The first KVK was established in 1974 at Puducherry under Tamil Nadu Agricultural University, following the Mohan Singh Mehta committee's recommendation. KVKs now exist in nearly every district.","difficulty":"hard","questionHi":"पहला कृषि विज्ञान केंद्र, जो प्रशिक्षण और खेत पर परीक्षण का कृषि विज्ञान केंद्र है, 1974 में कहाँ स्थापित हुआ?","optionsHi":["पूसा, बिहार","आनंद, गुजरात","पुडुचेरी","लुधियाना, पंजाब"],"explanationHi":"पहला KVK 1974 में तमिलनाडु कृषि विश्वविद्यालय के अधीन पुडुचेरी में स्थापित हुआ, मोहन सिंह मेहता समिति की सिफारिश के बाद। अब लगभग प्रत्येक जिले में KVK हैं।","source":"State PCS · UPSC Prelims"},
  {"id":"geo-soils-agriculture-187","question":"Arrange these events in chronological order: 1. NABARD is set up  2. The Kisan Credit Card scheme is launched  3. Operation Flood begins  4. The Agricultural Prices Commission is set up","options":["4, 1, 3, 2","3, 4, 1, 2","4, 3, 2, 1","4, 3, 1, 2"],"answer":3,"explanation":"The Agricultural Prices Commission came in 1965, Operation Flood began in 1970, NABARD was set up in 1982, and the Kisan Credit Card scheme was launched in 1998.","difficulty":"hard","questionHi":"इन घटनाओं को कालक्रम में व्यवस्थित कीजिए: 1. नाबार्ड की स्थापना  2. किसान क्रेडिट कार्ड योजना का शुभारंभ  3. ऑपरेशन फ्लड का आरंभ  4. कृषि मूल्य आयोग की स्थापना","optionsHi":["4, 1, 3, 2","3, 4, 1, 2","4, 3, 2, 1","4, 3, 1, 2"],"explanationHi":"कृषि मूल्य आयोग 1965 में आया, ऑपरेशन फ्लड 1970 में शुरू हुआ, नाबार्ड 1982 में बना और किसान क्रेडिट कार्ड योजना 1998 में आरंभ हुई।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-soils-agriculture-188","question":"Arrange these canals in the order in which they were built, earliest first: 1. Upper Ganga Canal  2. Western Yamuna Canal  3. Gang Canal  4. Sirhind Canal","options":["2, 1, 4, 3","1, 2, 4, 3","2, 4, 1, 3","2, 1, 3, 4"],"answer":0,"explanation":"The Western Yamuna Canal goes back to Firoz Shah Tughlaq in the fourteenth century, the Upper Ganga Canal opened in 1854, the Sirhind Canal in 1882, and the Gang Canal of Bikaner in 1927.","difficulty":"very-hard","questionHi":"इन नहरों को उनके निर्माण के क्रम में, सबसे पहले वाली से, व्यवस्थित कीजिए: 1. ऊपरी गंगा नहर  2. पश्चिमी यमुना नहर  3. गंग नहर  4. सरहिंद नहर","optionsHi":["2, 1, 4, 3","1, 2, 4, 3","2, 4, 1, 3","2, 1, 3, 4"],"explanationHi":"पश्चिमी यमुना नहर चौदहवीं सदी में फ़िरोज़ शाह तुगलक के समय की है, ऊपरी गंगा नहर 1854 में खुली, सरहिंद नहर 1882 में और बीकानेर की गंग नहर 1927 में।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-soils-agriculture-189","question":"Match the traditional farming or water system with its State. A. Zabo  B. Apatani paddy-cum-fish farming  C. Bamboo drip irrigation  D. Johad. 1. Meghalaya  2. Nagaland  3. Arunachal Pradesh  4. Rajasthan","options":["A-2, B-3, C-4, D-1","A-2, B-3, C-1, D-4","A-2, B-1, C-3, D-4","A-3, B-2, C-1, D-4"],"answer":1,"explanation":"Zabo, a system combining forest, water harvesting and paddy, is Nagaland's; the Apatani of the Ziro valley rear fish in terraced paddy in Arunachal Pradesh; bamboo drip irrigation (used for pepper and areca) is Meghalaya's; and johads, earthen check dams, are in Rajasthan.","difficulty":"very-hard","questionHi":"पारंपरिक कृषि या जल प्रणाली का उसके राज्य से मिलान कीजिए। A. ज़ाबो  B. आपातानी धान-सह-मत्स्य पालन  C. बाँस ड्रिप सिंचाई  D. जोहड़। 1. मेघालय  2. नागालैंड  3. अरुणाचल प्रदेश  4. राजस्थान","optionsHi":["A-2, B-3, C-4, D-1","A-2, B-3, C-1, D-4","A-2, B-1, C-3, D-4","A-3, B-2, C-1, D-4"],"explanationHi":"वन, जल संचयन और धान को जोड़ने वाली प्रणाली ज़ाबो नागालैंड की है; ज़ीरो घाटी के आपातानी अरुणाचल प्रदेश में सीढ़ीदार धान में मछली पालते हैं; बाँस ड्रिप सिंचाई (काली मिर्च और सुपारी के लिए) मेघालय की है; और जोहड़, मिट्टी के रोक बाँध, राजस्थान में हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-soils-agriculture-190","question":"Match the water-conservation initiative described by NCERT with its State. A. Neeru-Meeru  B. Arvary Pani Sansad  C. Gendathur village rainwater harvesting  D. Compulsory rooftop rainwater harvesting in all houses. 1. Tamil Nadu  2. Karnataka  3. Rajasthan  4. Andhra Pradesh","options":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-4, B-2, C-3, D-1"],"answer":2,"explanation":"Neeru-Meeru (Water and You) is a watershed programme of Andhra Pradesh, Arvary Pani Sansad a community water parliament in Alwar, Rajasthan, Gendathur a model village near Mysuru in Karnataka, and Tamil Nadu made rooftop rainwater harvesting compulsory.","difficulty":"very-hard","questionHi":"NCERT में वर्णित जल संरक्षण पहल का उसके राज्य से मिलान कीजिए। A. नीरू–मीरू  B. अरवरी पानी संसद  C. गेंडाथुर गाँव का वर्षा जल संचयन  D. सभी घरों में अनिवार्य छत वर्षा जल संचयन। 1. तमिलनाडु  2. कर्नाटक  3. राजस्थान  4. आंध्र प्रदेश","optionsHi":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-4, B-2, C-3, D-1"],"explanationHi":"नीरू–मीरू (जल और आप) आंध्र प्रदेश का जलग्रहण कार्यक्रम है, अरवरी पानी संसद राजस्थान के अलवर में सामुदायिक जल संसद है, गेंडाथुर कर्नाटक में मैसूरु के पास का एक आदर्श गाँव है, और तमिलनाडु ने छत वर्षा जल संचयन अनिवार्य किया।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-soils-agriculture-191","question":"'Operation Barga', launched in 1978, was a land reform programme to record the names of sharecroppers (bargadars) and secure their tenancy in:","options":["Kerala","Bihar","Andhra Pradesh","West Bengal"],"answer":3,"explanation":"Operation Barga in West Bengal registered sharecroppers, giving them heritable tenancy rights and a fixed share of the crop. Kerala's land reform of the late 1960s was a different measure that gave tenants ownership.","difficulty":"hard","questionHi":"'ऑपरेशन बर्गा', जो 1978 में आरंभ हुआ, बटाईदारों (बर्गादारों) के नाम दर्ज कर उनकी काश्त को सुरक्षित करने वाला भूमि सुधार कार्यक्रम किस राज्य में था?","optionsHi":["केरल","बिहार","आंध्र प्रदेश","पश्चिम बंगाल"],"explanationHi":"पश्चिम बंगाल के ऑपरेशन बर्गा ने बटाईदारों को पंजीकृत किया, जिससे उन्हें वंशानुगत काश्त अधिकार और फसल का निश्चित हिस्सा मिला। केरल का 1960 के दशक के अंत का भूमि सुधार एक भिन्न उपाय था जिसने काश्तकारों को स्वामित्व दिया।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-soils-agriculture-192","question":"Phalaris minor, locally called 'gulli danda', is a serious weed of which crop in the rice-wheat belt of north-west India?","options":["Wheat","Sugarcane","Mustard","Rice"],"answer":0,"explanation":"Phalaris minor is a grassy weed that looks like wheat at the seedling stage and became resistant to the herbicide isoproturon in the Indo-Gangetic plain, causing big losses in wheat after rice.","difficulty":"hard","questionHi":"फैलैरिस माइनर, जिसे स्थानीय रूप से 'गुल्ली डंडा' कहते हैं, उत्तर-पश्चिम भारत की धान-गेहूँ पट्टी में किस फसल का गंभीर खरपतवार है?","optionsHi":["गेहूँ","गन्ना","सरसों","धान"],"explanationHi":"फैलैरिस माइनर घास जैसा खरपतवार है जो अंकुर अवस्था में गेहूँ जैसा दिखता है और इंडो-गंगा मैदान में शाकनाशी आइसोप्रोट्यूरॉन के प्रति प्रतिरोधी हो गया, जिससे धान के बाद गेहूँ में बड़ी हानि होती है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-soils-agriculture-193","question":"Which aquatic weed, introduced as an ornamental plant, has been called the 'Terror of Bengal' because it chokes ponds and canals?","options":["Parthenium (congress grass)","Water hyacinth","Salvinia (giant salvinia)","Lantana (wild sage)"],"answer":1,"explanation":"Water hyacinth (Eichhornia crassipes), a native of South America, spreads rapidly, depletes oxygen and blocks waterways in Bengal. Salvinia is another floating weed, while lantana and parthenium are terrestrial weeds.","difficulty":"hard","questionHi":"किस जलीय खरपतवार को, जो शोभाकारी पौधे के रूप में लाया गया था, 'बंगाल का आतंक' कहा गया है क्योंकि वह तालाबों और नहरों को अवरुद्ध कर देता है?","optionsHi":["पार्थेनियम (गाजर घास)","जलकुंभी","साल्विनिया (विशाल साल्विनिया)","लैंटाना (पंचफूली)"],"explanationHi":"जलकुंभी (आइकोर्निया क्रैसिपीज़), जो दक्षिण अमेरिका की मूल निवासी है, तेज़ी से फैलती है, ऑक्सीजन घटाती है और बंगाल में जलमार्गों को रोक देती है। साल्विनिया एक अन्य तैरता खरपतवार है, जबकि लैंटाना और पार्थेनियम स्थलीय खरपतवार हैं।","source":"State PCS · UPSC Prelims"},
  {"id":"geo-soils-agriculture-194","question":"Parthenium (congress grass), a widespread weed in India, is believed to have entered the country mainly with:","options":["Cotton seed brought from Egypt in the 1930s for the textile mills of Gujarat","Jute seed imported from Bangladesh after 1971 for the Bengal jute mills","Wheat imported from the USA under PL-480 in the 1950s-60s","Rice varieties supplied by the IRRI in 1966 for the Green Revolution"],"answer":2,"explanation":"Parthenium hysterophorus, a native of tropical America, is widely thought to have arrived as a contaminant in PL-480 wheat grain from the USA in the 1950s. It causes allergies and can suppress other plants by allelopathy.","difficulty":"very-hard","questionHi":"पार्थेनियम (गाजर घास), जो भारत में व्यापक खरपतवार है, माना जाता है कि देश में मुख्यतः किसके साथ आया?","optionsHi":["1930 के दशक में मिस्र से लाए गए कपास बीज के साथ","1971 के बाद बांग्लादेश से आयातित जूट बीज के साथ","1950-60 के दशकों में PL-480 के अंतर्गत अमेरिका से आयातित गेहूँ के साथ","1966 में IRRI द्वारा दी गई धान किस्मों के साथ"],"explanationHi":"उष्णकटिबंधीय अमेरिका का मूल पार्थेनियम हिस्टेरोफोरस, व्यापक रूप से माना जाता है कि 1950 के दशक में अमेरिका से PL-480 गेहूँ के अनाज में मिलावट के रूप में आया। यह एलर्जी करता है और एलीलोपैथी से अन्य पौधों को दबा सकता है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-soils-agriculture-195","question":"Match the plant disease with its causal organism. A. Late blight of potato  B. Red rot of sugarcane  C. Stem rust of wheat  D. Blast of rice. 1. Magnaporthe oryzae  2. Colletotrichum falcatum  3. Puccinia graminis tritici  4. Phytophthora infestans","options":["A-4, B-3, C-2, D-1","A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1","A-4, B-2, C-3, D-1"],"answer":3,"explanation":"Late blight is caused by the oomycete Phytophthora infestans (the Irish famine disease), red rot by the fungus Colletotrichum falcatum, stem rust by Puccinia graminis tritici, and rice blast by Magnaporthe oryzae.","difficulty":"very-hard","questionHi":"पादप रोग का उसके कारक जीव से मिलान कीजिए। A. आलू का पछेता झुलसा  B. गन्ने का लाल सड़न  C. गेहूँ का तना रतुआ  D. धान का झोंका (ब्लास्ट)। 1. मैग्नापोर्थे ओराइज़े  2. कोलेटोट्राइकम फैल्केटम  3. पक्सिनिया ग्रैमिनिस ट्रिटिकी  4. फाइटोफ्थोरा इन्फेस्टैंस","optionsHi":["A-4, B-3, C-2, D-1","A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1","A-4, B-2, C-3, D-1"],"explanationHi":"पछेता झुलसा अंडकवक फाइटोफ्थोरा इन्फेस्टैंस (आयरिश अकाल का रोग) से, लाल सड़न कवक कोलेटोट्राइकम फैल्केटम से, तना रतुआ पक्सिनिया ग्रैमिनिस ट्रिटिकी से और धान का ब्लास्ट मैग्नापोर्थे ओराइज़े से होता है।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-soils-agriculture-196","question":"The synthetic auxin 2,4-D is widely used in cereal fields as:","options":["A selective weedkiller that controls broad-leaved weeds","A fertiliser that supplies nitrogen to the crop","A hormone to hasten the ripening of fruits","A fungicide against rusts and smuts"],"answer":0,"explanation":"2,4-D mimics the plant hormone auxin and kills broad-leaved (dicot) weeds by overstimulating growth, while grasses like wheat and rice tolerate it. Ethephon, not 2,4-D, is used to hasten ripening.","difficulty":"hard","questionHi":"कृत्रिम ऑक्सिन 2,4-D अनाज के खेतों में व्यापक रूप से किस रूप में प्रयुक्त होता है?","optionsHi":["चयनात्मक शाकनाशी जो चौड़ी पत्ती वाले खरपतवार नियंत्रित करता है","फसल को नाइट्रोजन देने वाला उर्वरक","फलों के पकने को तेज़ करने वाला हार्मोन","रतुआ और कंडुआ के विरुद्ध कवकनाशी"],"explanationHi":"2,4-D पादप हार्मोन ऑक्सिन की नकल करता है और वृद्धि को अति-उद्दीप्त करके चौड़ी पत्ती (द्विबीजपत्री) खरपतवारों को मारता है, जबकि गेहूँ और धान जैसी घासें इसे सह लेती हैं। फल पकाने के लिए एथेफॉन प्रयुक्त होता है, 2,4-D नहीं।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-soils-agriculture-197","question":"Trichogramma, widely reared and released in sugarcane and cotton fields, is used in biological control as:","options":["A soil fungus that traps and kills the nematodes feeding on the roots of crops","An egg parasitoid wasp that destroys the eggs of stem borers and bollworms","A bacterium that makes a crystal toxin which kills the feeding caterpillars of moths","A predatory ladybird beetle that feeds on aphids, scales and mealybugs on plants"],"answer":1,"explanation":"Trichogramma is a tiny wasp that lays its eggs inside the eggs of moths such as sugarcane borers and bollworms, so the pest never hatches. The bacterium Bacillus thuringiensis is the caterpillar toxin source, and ladybird beetles eat aphids.","difficulty":"hard","questionHi":"गन्ने और कपास के खेतों में बड़े पैमाने पर पाला और छोड़ा जाने वाला ट्राइकोग्रामा जैव नियंत्रण में किस रूप में प्रयुक्त होता है?","optionsHi":["कवक जो मृदा सूत्रकृमि को मारता है","अंड परजीवी ततैया जो तना छेदकों और बॉलवर्म के अंडे नष्ट करती है","जीवाणु जो इल्लियों के विरुद्ध विष बनाता है","परभक्षी भृंग जो माहू खाता है"],"explanationHi":"ट्राइकोग्रामा छोटी ततैया है जो गन्ना छेदक और बॉलवर्म जैसे पतंगों के अंडों के भीतर अपने अंडे देती है, इसलिए कीट कभी नहीं निकलता। इल्लियों के विष का स्रोत जीवाणु बैसिलस थुरिंजिएंसिस है और लेडी बर्ड भृंग माहू खाते हैं।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-soils-agriculture-198","question":"Under the Pradhan Mantri Krishi Sinchayee Yojana, the 'Per Drop More Crop' component mainly promotes:","options":["Watershed development in rain-fed areas through check dams and farm ponds on slopes","Connecting river basins through long inter-linking canals to transfer surplus water","Micro-irrigation, such as drip and sprinklers, to raise water-use efficiency","Construction of large dams, barrages and canal networks for major irrigation projects"],"answer":2,"explanation":"PMKSY has four parts: AIBP for large projects, 'Har Khet Ko Pani' for source creation, watershed development, and 'Per Drop More Crop', which subsidises drip and sprinkler systems to raise efficiency.","difficulty":"hard","questionHi":"प्रधानमंत्री कृषि सिंचाई योजना के अंतर्गत 'प्रति बूँद अधिक फसल' घटक मुख्यतः किसे बढ़ावा देता है?","optionsHi":["वर्षा-सिंचित क्षेत्रों में रोक बाँधों से जलग्रहण विकास","नदियों को अंतर-संयोजन नहरों से जोड़ना","जल उपयोग दक्षता बढ़ाने के लिए सूक्ष्म सिंचाई, जैसे ड्रिप और स्प्रिंकलर","बड़े बाँधों और नहर जालों का निर्माण"],"explanationHi":"PMKSY के चार भाग हैं: बड़ी परियोजनाओं के लिए AIBP, स्रोत सृजन के लिए 'हर खेत को पानी', जलग्रहण विकास, और 'प्रति बूँद अधिक फसल', जो दक्षता बढ़ाने के लिए ड्रिप और स्प्रिंकलर प्रणालियों पर सब्सिडी देता है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-soils-agriculture-199","question":"Under the Pradhan Mantri Fasal Bima Yojana, the premium to be paid by farmers is capped at:","options":["10% for all crops, with the rest paid by the State","5% for kharif foodgrains, 2% for rabi, and 1.5% for commercial and horticultural crops","1.5% for kharif foodgrains, 5% for rabi, and 2% for commercial and horticultural crops","2% for kharif foodgrains and oilseeds, 1.5% for rabi, and 5% for commercial and horticultural crops"],"answer":3,"explanation":"The scheme, begun in 2016, fixes the farmer's share at 2% for kharif foodgrain and oilseed crops, 1.5% for rabi, and 5% for annual commercial and horticultural crops. The Centre and States share the balance of the actuarial premium.","difficulty":"very-hard","questionHi":"प्रधानमंत्री फसल बीमा योजना के अंतर्गत किसानों द्वारा देय प्रीमियम की अधिकतम सीमा क्या है?","optionsHi":["सभी फसलों के लिए 10%, शेष राज्य द्वारा देय","खरीफ खाद्यान्न के लिए 5%, रबी के लिए 2% और वाणिज्यिक तथा बागवानी फसलों के लिए 1.5%","खरीफ खाद्यान्न के लिए 1.5%, रबी के लिए 5% और वाणिज्यिक तथा बागवानी फसलों के लिए 2%","खरीफ खाद्यान्न और तिलहन के लिए 2%, रबी के लिए 1.5% और वाणिज्यिक तथा बागवानी फसलों के लिए 5%"],"explanationHi":"2016 में आरंभ इस योजना में किसान का हिस्सा खरीफ खाद्यान्न और तिलहन फसलों के लिए 2%, रबी के लिए 1.5% और वार्षिक वाणिज्यिक तथा बागवानी फसलों के लिए 5% तय है। बीमांकिक प्रीमियम का शेष भाग केंद्र और राज्य बाँटते हैं।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-soils-agriculture-200","question":"Which statement correctly compares the two main coffee species grown in India?","options":["Robusta tolerates hotter, lower and wetter conditions and has more caffeine than Arabica","Arabica tolerates hotter, lower and wetter conditions and has more caffeine than Robusta","Robusta needs cool, high-altitude slopes above 1,500 m and is grown only in the Nilgiris","Arabica and Robusta need identical altitude and have identical caffeine content"],"answer":0,"explanation":"Arabica prefers cooler, higher slopes, about 600-1,800 m, and has less caffeine. Robusta is hardier, grows at lower altitudes in warmer, wetter conditions, resists leaf rust better and has roughly twice the caffeine; it is the main species in Kodagu.","difficulty":"hard","questionHi":"भारत में उगाई जाने वाली कॉफी की दो मुख्य प्रजातियों की तुलना करने वाला कौन-सा कथन सही है?","optionsHi":["रोबस्टा अरेबिका की अपेक्षा गर्म, निचली और अधिक नम परिस्थितियाँ सह लेती है और उसमें कैफीन अधिक होता है","अरेबिका रोबस्टा की अपेक्षा गर्म, निचली और अधिक नम परिस्थितियाँ सह लेती है और उसमें कैफीन अधिक होता है","रोबस्टा को 1,500 m से ऊपर की ठंडी, ऊँची ढालें चाहिए और वह केवल नीलगिरि में उगती है","अरेबिका और रोबस्टा को समान ऊँचाई चाहिए और उनमें कैफीन की मात्रा समान है"],"explanationHi":"अरेबिका ठंडी, ऊँची ढालें, लगभग 600-1,800 m, पसंद करती है और उसमें कैफीन कम होता है। रोबस्टा अधिक सहनशील है, निचली ऊँचाइयों पर गर्म और नम परिस्थितियों में उगती है, पत्ती रतुआ का बेहतर प्रतिरोध करती है और उसमें लगभग दोगुना कैफीन होता है; यह कोडागु की मुख्य प्रजाति है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-soils-agriculture-201","question":"Which statement about the tea bushes of Darjeeling and Assam is correct?","options":["Both regions grow only the large-leaved assamica type","Darjeeling bushes are mainly small-leaved China type, while Assam bushes are large-leaved assamica type","Both regions grow only the small-leaved China type","Darjeeling bushes are mainly large-leaved assamica type, while Assam bushes are small-leaved China type"],"answer":1,"explanation":"Darjeeling's cool, high gardens grow mostly the China variety (Camellia sinensis var. sinensis), giving delicate flavour, while the warm, humid Brahmaputra valley grows the large-leaved assamica variety, giving strong, malty tea.","difficulty":"very-hard","questionHi":"दार्जिलिंग और असम की चाय झाड़ियों के बारे में कौन-सा कथन सही है?","optionsHi":["दोनों क्षेत्रों में केवल बड़ी पत्ती वाली असमिका प्रकार उगती है","दार्जिलिंग की झाड़ियाँ मुख्यतः छोटी पत्ती वाली चीनी प्रकार की हैं, जबकि असम की झाड़ियाँ बड़ी पत्ती वाली असमिका प्रकार की","दोनों क्षेत्रों में केवल छोटी पत्ती वाली चीनी प्रकार उगती है","दार्जिलिंग की झाड़ियाँ मुख्यतः बड़ी पत्ती वाली असमिका प्रकार की हैं, जबकि असम की झाड़ियाँ छोटी पत्ती वाली चीनी प्रकार की"],"explanationHi":"दार्जिलिंग के ठंडे, ऊँचे बागानों में अधिकांश चीनी किस्म (कैमेलिया साइनेंसिस वर. साइनेंसिस) उगती है, जो नाजुक स्वाद देती है, जबकि गर्म, आर्द्र ब्रह्मपुत्र घाटी में बड़ी पत्ती वाली असमिका किस्म उगती है, जो तेज़, माल्टी चाय देती है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-soils-agriculture-202","question":"The spice saffron, grown at Pampore in Kashmir, consists of the:","options":["Dried petals of the Crocus sativus flower","Dried seeds of the Crocus sativus fruit","Dried stigmas of the Crocus sativus flower","Dried underground corms of the Crocus sativus plant"],"answer":2,"explanation":"Saffron is made of the three red stigmas of each Crocus sativus flower, picked by hand and dried, which is why it is so costly. The plant is propagated by corms, and it flowers in autumn.","difficulty":"moderate","questionHi":"कश्मीर के पंपोर में उगने वाला मसाला केसर किससे बनता है?","optionsHi":["क्रोकस सैटिवस पुष्प की सूखी पंखुड़ियाँ","क्रोकस सैटिवस फल के सूखे बीज","क्रोकस सैटिवस पुष्प के सूखे वर्तिकाग्र","क्रोकस सैटिवस पौधे के सूखे भूमिगत घनकंद"],"explanationHi":"केसर प्रत्येक क्रोकस सैटिवस पुष्प के तीन लाल वर्तिकाग्रों से बनता है, जिन्हें हाथ से चुनकर सुखाया जाता है, इसीलिए यह इतना महँगा है। पौधा घनकंदों से प्रवर्धित होता है और शरद में फूलता है।","source":"SSC CGL · State PCS"},
  {"id":"geo-soils-agriculture-203","question":"Which cultivated cotton species yields the extra-long staple fibre known as Egyptian or Sea Island cotton?","options":["Gossypium hirsutum","Gossypium arboreum","Gossypium herbaceum","Gossypium barbadense"],"answer":3,"explanation":"Gossypium barbadense gives extra-long, fine fibre. G. hirsutum is the American upland cotton that makes up most of today's crop, and G. arboreum and G. herbaceum are the short-staple Asiatic or desi cottons.","difficulty":"very-hard","questionHi":"कपास की कौन-सी कृषित प्रजाति मिस्री या सी आइलैंड कपास के नाम से जानी जाने वाली अतिदीर्घ रेशे वाली कपास देती है?","optionsHi":["गॉसिपियम हिर्सुटम","गॉसिपियम आर्बोरियम","गॉसिपियम हर्बेसियम","गॉसिपियम बारबाडेंस"],"explanationHi":"गॉसिपियम बारबाडेंस अतिदीर्घ, महीन रेशा देती है। G. हिर्सुटम अमेरिकी अपलैंड कपास है जो आज की अधिकांश फसल बनाती है, और G. आर्बोरियम तथा G. हर्बेसियम छोटे रेशे वाली एशियाई या देशी कपासें हैं।","source":"UPSC Prelims · UGC NET style"},
  {"id":"geo-soils-agriculture-204","question":"Retting, the process that frees jute fibre from the stem, is carried out by:","options":["Soaking bundles of stems in slow-moving or stagnant water so that microbes rot the binding tissue","Crushing the green stems between steel rollers and washing them in a fast-flowing river","Drying the stems in the sun and beating them until the fibre falls loose","Boiling the stems in a strong alkali solution to dissolve the lignin"],"answer":0,"explanation":"In retting, jute stems are bundled and submerged in ponds or slow streams for 10-20 days, so bacteria decompose the pectin and gums that bind the fibre. The loosened fibre is then stripped by hand.","difficulty":"hard","questionHi":"रेटिंग (सड़ाना), जो जूट के रेशे को तने से मुक्त करने की प्रक्रिया है, किस प्रकार की जाती है?","optionsHi":["तनों के गट्ठर को धीमी बहती या ठहरी पानी में भिगोना ताकि सूक्ष्मजीव बाँधने वाले ऊतक को सड़ा दें","हरे तनों को इस्पात बेलनों के बीच कुचलना और तेज़ बहती नदी में धोना","तनों को धूप में सुखाकर तब तक पीटना जब तक रेशा ढीला होकर निकल न आए","तनों को तीव्र क्षार विलयन में उबालकर लिग्निन घोलना"],"explanationHi":"रेटिंग में जूट के तनों के गट्ठर तालाबों या धीमी धाराओं में 10-20 दिन डुबोए जाते हैं, जिससे जीवाणु रेशे को बाँधने वाले पेक्टिन और गोंद को अपघटित करते हैं। ढीला हुआ रेशा फिर हाथ से अलग किया जाता है।","source":"SSC CGL · State PCS"},
  {"id":"geo-soils-agriculture-205","question":"Muga silk, famed for its natural golden sheen, is produced almost exclusively in:","options":["Jammu and Kashmir","Assam","Karnataka","Jharkhand"],"answer":1,"explanation":"Muga silk comes from the semi-domesticated silkworm Antheraea assamensis, which feeds on som and soalu leaves in the Brahmaputra valley, and it is the speciality of Assam. Karnataka leads in mulberry silk and Jharkhand in tasar.","difficulty":"hard","questionHi":"मूगा रेशम, जो अपनी प्राकृतिक सुनहरी चमक के लिए प्रसिद्ध है, लगभग विशेष रूप से कहाँ उत्पादित होता है?","optionsHi":["जम्मू और कश्मीर","असम","कर्नाटक","झारखंड"],"explanationHi":"मूगा रेशम अर्ध-पालतू रेशम कीट एन्थेरिया असामेंसिस से मिलता है, जो ब्रह्मपुत्र घाटी में सोम और सोआलू की पत्तियाँ खाता है, और यह असम की विशेषता है। कर्नाटक शहतूत रेशम में और झारखंड तसर में अग्रणी है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-soils-agriculture-206","question":"Which silk is often called 'ahimsa' or peace silk because the moth is allowed to emerge before the cocoon is spun into yarn?","options":["Muga silk","Tasar silk","Eri silk","Mulberry silk"],"answer":2,"explanation":"Eri silk comes from Samia ricini, which feeds on castor leaves; its open-ended cocoon lets the moth leave without being killed and the cocoon is then spun like cotton. Mulberry cocoons are usually boiled to extract the continuous filament.","difficulty":"hard","questionHi":"किस रेशम को प्रायः 'अहिंसा' या शांति रेशम कहा जाता है क्योंकि कोया से सूत कातने से पहले शलभ को बाहर निकलने दिया जाता है?","optionsHi":["मूगा रेशम","तसर रेशम","एरी रेशम","शहतूत रेशम"],"explanationHi":"एरी रेशम सामिया रिसिनी से मिलता है, जो अरंडी की पत्तियाँ खाता है; इसका खुले सिरे वाला कोया शलभ को बिना मारे निकलने देता है और फिर कोये को कपास की तरह काता जाता है। शहतूत के कोयों को सतत तंतु निकालने के लिए प्रायः उबाला जाता है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-soils-agriculture-207","question":"Which honeybee species of India, called the rock bee, builds a single large open comb hanging from a tree branch or cliff and has never been domesticated in hives?","options":["Apis mellifera","Apis florea","Apis cerana indica","Apis dorsata"],"answer":3,"explanation":"Apis dorsata, the giant rock bee, builds a single huge exposed comb, is aggressive and migratory, and cannot be kept in boxes. A. cerana and A. mellifera are hive bees, and A. florea, the little bee, builds a small single comb.","difficulty":"hard","questionHi":"भारत की कौन-सी मधुमक्खी प्रजाति, जिसे भँवर (शैल) मक्खी कहते हैं, पेड़ की डाल या चट्टान से लटका एकल बड़ा खुला छत्ता बनाती है और कभी पेटियों में पाली नहीं गई?","optionsHi":["एपिस मेलिफेरा","एपिस फ्लोरिया","एपिस सेराना इंडिका","एपिस डोरसाटा"],"explanationHi":"एपिस डोरसाटा, विशाल शैल मधुमक्खी, एकल विशाल खुला छत्ता बनाती है, आक्रामक और प्रवासी है, और डिब्बों में नहीं रखी जा सकती। A. सेराना और A. मेलिफेरा पेटी की मधुमक्खियाँ हैं, और A. फ्लोरिया, छोटी मधुमक्खी, छोटा एकल छत्ता बनाती है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-soils-agriculture-208","question":"Match the goat breed with its home State. A. Jamunapari  B. Beetal  C. Sirohi  D. Malabari. 1. Kerala  2. Rajasthan  3. Punjab  4. Uttar Pradesh","options":["A-4, B-3, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1"],"answer":0,"explanation":"Jamunapari, the long-eared milch goat, comes from the Etawah region of Uttar Pradesh, Beetal from Punjab, Sirohi from Rajasthan, and Malabari (Tellicherry) from Kerala.","difficulty":"hard","questionHi":"बकरी की नस्ल का उसके गृह राज्य से मिलान कीजिए। A. जमुनापारी  B. बीटल  C. सिरोही  D. मालाबारी। 1. केरल  2. राजस्थान  3. पंजाब  4. उत्तर प्रदेश","optionsHi":["A-4, B-3, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1"],"explanationHi":"लंबे कानों वाली दुधारू जमुनापारी उत्तर प्रदेश के इटावा क्षेत्र की है, बीटल पंजाब की, सिरोही राजस्थान की और मालाबारी (तेलिचेरी) केरल की।","source":"State PCS · SSC CGL"},
  {"id":"geo-soils-agriculture-209","question":"Match the pastoral community with the State where it moves its flocks seasonally between highland and lowland pastures. A. Gaddi  B. Bakarwal  C. Bhotia  D. Maldhari. 1. Gujarat  2. Uttarakhand  3. Jammu and Kashmir  4. Himachal Pradesh","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-2, C-3, D-1"],"answer":1,"explanation":"The Gaddis of Himachal (Dhauladhar and Chamba) and the Bakarwals of Jammu and Kashmir practise vertical transhumance, as do the Bhotias of Uttarakhand, while the Maldharis of Gujarat herd cattle, buffalo and camels.","difficulty":"very-hard","questionHi":"चरवाहा समुदाय का उस राज्य से मिलान कीजिए जहाँ वह अपने झुंडों को ऊँचे और निचले चरागाहों के बीच मौसम के अनुसार ले जाता है। A. गद्दी  B. बकरवाल  C. भोटिया  D. मालधारी। 1. गुजरात  2. उत्तराखंड  3. जम्मू और कश्मीर  4. हिमाचल प्रदेश","optionsHi":["A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-2, C-3, D-1"],"explanationHi":"हिमाचल (धौलाधार और चंबा) के गद्दी और जम्मू-कश्मीर के बकरवाल तथा उत्तराखंड के भोटिया ऊर्ध्वाधर ऋतु-प्रवास करते हैं, जबकि गुजरात के मालधारी गाय, भैंस और ऊँट पालते हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-soils-agriculture-210","question":"Apple orchards flourish in the temperate Himalaya of Jammu and Kashmir, Himachal Pradesh and Uttarakhand largely because the tree:","options":["Needs heavy monsoon rain spread throughout the year with no dry or cold spell","Needs the long, hot, dry summers found on the Deccan plateau and in Rajasthan","Needs a spell of winter chilling to break dormancy and flower properly","Needs a frost-free winter with temperatures staying well above 20 °C throughout"],"answer":2,"explanation":"Apple, like most temperate fruits, needs several weeks of temperatures below about 7 °C in winter to end dormancy and flower normally, so it succeeds in the cold highlands and fails in the tropical plains.","difficulty":"hard","questionHi":"जम्मू और कश्मीर, हिमाचल प्रदेश और उत्तराखंड के शीतोष्ण हिमालय में सेब के बाग मुख्यतः इसलिए फलते-फूलते हैं क्योंकि इस वृक्ष को:","optionsHi":["पूरे वर्ष भारी मानसूनी वर्षा चाहिए","दक्कन पठार जैसी लंबी गर्म ग्रीष्म चाहिए","सुषुप्ति तोड़ने और ठीक से फूलने के लिए शीतकालीन ठंड की अवधि चाहिए","20 °C से ऊपर के तापमान वाला पाला-रहित शीत चाहिए"],"explanationHi":"सेब को, अधिकांश शीतोष्ण फलों की तरह, सुषुप्ति समाप्त करने और सामान्य रूप से फूलने के लिए शीत में लगभग 7 °C से नीचे के तापमान के कई सप्ताह चाहिए, इसलिए वह ठंडे उच्च प्रदेशों में सफल होता है और उष्णकटिबंधीय मैदानों में विफल।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-soils-agriculture-211","question":"Which statement correctly compares buffalo milk with cow milk?","options":["Buffalo milk has almost no fat, which is why it is used for skimmed milk powder","Cow milk is richer in fat, about 6-8%, than buffalo milk at about 3.5-5%","Both contain the same fat, about 4%, but buffalo milk has more lactose","Buffalo milk is richer in fat, about 6-8%, than cow milk at about 3.5-5%"],"answer":3,"explanation":"Buffalo milk is whiter and thicker, with 6-8% fat against 3.5-5% in cow milk, which makes it well suited to ghee, paneer and khoa. Its carotene is converted to vitamin A, so it is whiter.","difficulty":"hard","questionHi":"भैंस के दूध की गाय के दूध से तुलना करने वाला कौन-सा कथन सही है?","optionsHi":["भैंस के दूध में लगभग वसा नहीं होती, इसीलिए उसका उपयोग स्किम्ड मिल्क पाउडर के लिए होता है","गाय के दूध में वसा, लगभग 6-8%, भैंस के दूध की लगभग 3.5-5% से अधिक होती है","दोनों में वसा समान, लगभग 4%, होती है, पर भैंस के दूध में लैक्टोज़ अधिक होता है","भैंस के दूध में वसा, लगभग 6-8%, गाय के दूध की लगभग 3.5-5% से अधिक होती है"],"explanationHi":"भैंस का दूध अधिक सफ़ेद और गाढ़ा होता है, जिसमें 6-8% वसा होती है जबकि गाय के दूध में 3.5-5%, इसलिए वह घी, पनीर और खोये के लिए उपयुक्त है। उसका कैरोटीन विटामिन A में बदल जाता है, इसीलिए वह अधिक सफ़ेद होता है।","source":"SSC CGL · State PCS"},
  {"id":"geo-soils-agriculture-212","question":"Agmark, the quality-grading mark for farm produce in India, was introduced under the Agricultural Produce (Grading and Marking) Act of:","options":["1937","1947","1966","1955"],"answer":0,"explanation":"The Agricultural Produce (Grading and Marking) Act of 1937 created Agmark certification, administered by the Directorate of Marketing and Inspection, Faridabad. The Essential Commodities Act is of 1955, and 1966 saw the start of the Green Revolution's HYV programme.","difficulty":"hard","questionHi":"भारत में कृषि उपज की गुणवत्ता श्रेणीकरण चिह्न एगमार्क किस वर्ष के कृषि उपज (श्रेणीकरण और चिह्नांकन) अधिनियम के अंतर्गत आरंभ हुआ?","optionsHi":["1937","1947","1966","1955"],"explanationHi":"1937 के कृषि उपज (श्रेणीकरण और चिह्नांकन) अधिनियम ने एगमार्क प्रमाणन आरंभ किया, जिसका प्रशासन फरीदाबाद का विपणन एवं निरीक्षण निदेशालय करता है। आवश्यक वस्तु अधिनियम 1955 का है और 1966 में हरित क्रांति का HYV कार्यक्रम शुरू हुआ।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-soils-agriculture-213","question":"Which of these fertilisers is still sold in India at a maximum retail price fixed by the Government, while the prices of phosphatic and potassic fertilisers are set by companies under a nutrient-based subsidy?","options":["Single superphosphate","Urea","Muriate of potash","Diammonium phosphate"],"answer":1,"explanation":"Urea remains under statutory price control, with the Government fixing its maximum retail price and reimbursing the difference to makers. Phosphatic and potassic fertilisers such as DAP, MOP and SSP are under the Nutrient Based Subsidy scheme from 2010.","difficulty":"hard","questionHi":"इनमें से कौन-सा उर्वरक आज भी भारत में सरकार द्वारा तय अधिकतम खुदरा मूल्य पर बिकता है, जबकि फॉस्फेटिक और पोटाशिक उर्वरकों के मूल्य पोषक तत्व आधारित सब्सिडी के अंतर्गत कंपनियाँ तय करती हैं?","optionsHi":["सिंगल सुपरफॉस्फेट","यूरिया","म्यूरिएट ऑफ पोटाश","डाइअमोनियम फॉस्फेट"],"explanationHi":"यूरिया वैधानिक मूल्य नियंत्रण में है, जिसका अधिकतम खुदरा मूल्य सरकार तय करती है और अंतर निर्माताओं को चुकाती है। DAP, MOP और SSP जैसे फॉस्फेटिक और पोटाशिक उर्वरक 2010 से पोषक तत्व आधारित सब्सिडी योजना के अंतर्गत हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-soils-agriculture-214","question":"Mango orchards are usually raised from grafts, not from stones (seeds), mainly because:","options":["Grafting shifts the ripening of every variety into the winter months","Mango pollen is sterile in most varieties, so stones rarely form viable seeds","Seedlings do not come true to type and give variable fruit","Seedling roots cannot tolerate the alluvial soils of the Gangetic plains"],"answer":2,"explanation":"Mango is highly heterozygous, so a seedling gives fruit unlike its parent. Grafting (veneer, inarching) multiplies a chosen variety such as Alphonso or Dasheri exactly and brings the tree into bearing earlier.","difficulty":"hard","questionHi":"आम के बाग सामान्यतः गुठली (बीज) से नहीं, कलमों (ग्राफ्ट) से तैयार किए जाते हैं, मुख्यतः क्योंकि:","optionsHi":["कलम बाँधने से हर किस्म का पकना शीत ऋतु के महीनों में चला जाता है","अधिकांश किस्मों में आम का परागकण बंध्य होता है, इसलिए गुठलियों में जीवनक्षम बीज बहुत कम बनते हैं","बीजू पौधे मातृ गुण के अनुरूप नहीं आते और अलग-अलग फल देते हैं","बीजू पौधों की जड़ें गंगा के मैदानों की जलोढ़ मिट्टी सह नहीं पातीं"],"explanationHi":"आम अत्यंत विषमयुग्मजी है, इसलिए बीजू पौधा अपने जनक से भिन्न फल देता है। कलम बाँधने (विनियर, इनआर्चिंग) से अल्फोंसो या दशहरी जैसी चुनी किस्म हूबहू बढ़ाई जाती है और पेड़ जल्दी फलने लगता है।","source":"State PCS · UPSC Prelims"},
];

export default questions;
